INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38727, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「日の出と共に」の決まった形。"}, {"text": "を", "is_correct": false, "explanation": "「日の出を共に」は非文。"}, {"text": "が", "is_correct": false, "explanation": "「日の出が共に」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「日の出へ共に」は非文。"}], "correct_answer": "と", "explanations": {"と": "「日の出と共に」の決まった形。", "を": "「日の出を共に」は非文。", "が": "「日の出が共に」は不自然。", "へ": "「日の出へ共に」は非文。"}, "error_tags": {"を": "object_marking", "が": "other", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38727, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "栄養", "is_correct": true, "explanation": "正解。「えいよう」。"}, {"text": "栄誉", "is_correct": false, "explanation": "「えいよ」。最後の長音「う」がなくなる。"}, {"text": "太陽", "is_correct": false, "explanation": "「たいよう」。最初のモーラ「え」が「た」に変わる。"}, {"text": "掲揚", "is_correct": false, "explanation": "「けいよう」。最初に「け」が付く。"}, {"text": "器用", "is_correct": false, "explanation": "「きよう」。「えい」が「き」に変わる。"}], "explanations": {"栄養": "正解。「えいよう」。", "栄誉": "「えいよ」。最後の長音「う」がなくなる。", "太陽": "「たいよう」。最初のモーラ「え」が「た」に変わる。", "掲揚": "「けいよう」。最初に「け」が付く。", "器用": "「きよう」。「えい」が「き」に変わる。"}, "sentence_index": null, "correct_answer": "栄養"}, "level_3": {"options": [{"text": "栄養", "is_correct": true, "explanation": "根から体に必要な成分をとる、が自然。"}, {"text": "空気", "is_correct": false, "explanation": "意味：植物は根から空気をとるとは普通いわない。"}, {"text": "光", "is_correct": false, "explanation": "意味：光は葉で受けるもので根からではない。"}, {"text": "写真", "is_correct": false, "explanation": "連語：「写真をとる」になり意味がずれる。"}], "explanations": {"栄養": "根から体に必要な成分をとる、が自然。", "空気": "意味：植物は根から空気をとるとは普通いわない。", "光": "意味：光は葉で受けるもので根からではない。", "写真": "連語：「写真をとる」になり意味がずれる。"}, "sentence_index": 6, "correct_answer": "栄養"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子犬に栄養するえさをあげた。", "explanation": "品詞の誤り：「栄養」は「する」動詞にならない。"}, {"text": "子犬に栄養をたっぷりのえさをあげた。", "explanation": "助詞の誤り：「栄養たっぷりの」で名詞を修飾する。"}, {"text": "子犬に栄養たっぷりのおもちゃをあげた。", "explanation": "意味の誤り：栄養は食べ物の成分で、おもちゃには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38727, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "栄養をして元気になった。", "corrected_sentence": "栄養をとって元気になった。", "error_description": "「栄養をとる」が正しい。「栄養をする」とはいわない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38727, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「栄養が足りない」の主語。"}, {"text": "を", "is_correct": false, "explanation": "「栄養を足りない」は非文。"}, {"text": "で", "is_correct": false, "explanation": "「栄養で足りない」は意味がずれる。"}, {"text": "へ", "is_correct": false, "explanation": "「栄養へ足りない」は非文。"}], "correct_answer": "が", "explanations": {"が": "「栄養が足りない」の主語。", "を": "「栄養を足りない」は非文。", "で": "「栄養で足りない」は意味がずれる。", "へ": "「栄養へ足りない」は非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37451, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "能力", "is_correct": true, "explanation": "対象語。"}, {"text": "暴力", "is_correct": false, "explanation": "ぼうりょく：第1モーラ「の」が「ぼ」に変わる一モーラ差。"}, {"text": "効力", "is_correct": false, "explanation": "こうりょく：第1モーラ「の」が「こ」に変わる一モーラ差。"}, {"text": "納涼", "is_correct": false, "explanation": "のうりょう：最後のモーラ「く」が「う」に変わる一モーラ差。"}, {"text": "有力", "is_correct": false, "explanation": "ゆうりょく：第1モーラ「の」が「ゆ」に変わる一モーラ差。"}], "explanations": {"能力": "対象語。", "暴力": "ぼうりょく：第1モーラ「の」が「ぼ」に変わる一モーラ差。", "効力": "こうりょく：第1モーラ「の」が「こ」に変わる一モーラ差。", "納涼": "のうりょう：最後のモーラ「く」が「う」に変わる一モーラ差。", "有力": "ゆうりょく：第1モーラ「の」が「ゆ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "能力"}, "level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "「認知能力」で、物事を理解する力を表す。"}, {"text": "予算", "is_correct": false, "explanation": "意味：お金の計画であり、認知と結びつかない。"}, {"text": "建物", "is_correct": false, "explanation": "意味：具体物で、子どもの中で育つものではない。"}, {"text": "税金", "is_correct": false, "explanation": "連語：「認知税金」という結びつきはない。"}], "explanations": {"能力": "「認知能力」で、物事を理解する力を表す。", "予算": "意味：お金の計画であり、認知と結びつかない。", "建物": "意味：具体物で、子どもの中で育つものではない。", "税金": "連語：「認知税金」という結びつきはない。"}, "sentence_index": 0, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "能力をある人が選ばれた。", "explanation": "助詞の誤り：「ある」の主語は「の／が」。"}, {"text": "能力な人が選ばれた。", "explanation": "接続の誤り：「能力」は名詞なので「能力のある人」。"}, {"text": "能力のある机が選ばれた。", "explanation": "意味の誤り：能力は人や生き物の力で、机には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37451, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は高い能力にある。", "corrected_sentence": "彼は高い能力がある。", "error_description": "助詞の誤り：存在・所有を表す「ある」の主語は「が」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37451, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ある」の対象（持っているもの）を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「ある」は自動詞なので目的語の「を」は取れない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、この位置では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「ある」と結びつかない。"}], "correct_answer": "が", "explanations": {"が": "「ある」の対象（持っているもの）を示す格助詞。", "を": "「ある」は自動詞なので目的語の「を」は取れない。", "で": "手段・場所を表し、この位置では非文。", "へ": "方向を表し、「ある」と結びつかない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無能力", "is_correct": true, "explanation": "力がないことを表し、能力の対義語。"}, {"text": "才能", "is_correct": false, "explanation": "生まれつきの力で、類義語に近く対義ではない。"}, {"text": "実力", "is_correct": false, "explanation": "実際の力で、類義語であり対義ではない。"}, {"text": "努力", "is_correct": false, "explanation": "がんばることで、対の関係にない。"}], "correct_answer": "無能力", "explanations": {"無能力": "力がないことを表し、能力の対義語。", "才能": "生まれつきの力で、類義語に近く対義ではない。", "実力": "実際の力で、類義語であり対義ではない。", "努力": "がんばることで、対の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37451, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "能力", "is_correct": true, "explanation": "対象語。"}, {"text": "動力", "is_correct": false, "explanation": "どうりょく：第1モーラ「の」が「ど」に変わる一モーラ差。"}, {"text": "協力", "is_correct": false, "explanation": "きょうりょく：第1モーラ「の」が「きょ」に変わる一モーラ差。"}, {"text": "重力", "is_correct": false, "explanation": "じゅうりょく：第1モーラ「の」が「じゅ」に変わる一モーラ差。"}, {"text": "常緑", "is_correct": false, "explanation": "じょうりょく：第1モーラ「の」が「じょ」に変わる一モーラ差。"}], "explanations": {"能力": "対象語。", "動力": "どうりょく：第1モーラ「の」が「ど」に変わる一モーラ差。", "協力": "きょうりょく：第1モーラ「の」が「きょ」に変わる一モーラ差。", "重力": "じゅうりょく：第1モーラ「の」が「じゅ」に変わる一モーラ差。", "常緑": "じょうりょく：第1モーラ「の」が「じょ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "能力"}, "level_3": {"options": [{"text": "能力", "is_correct": true, "explanation": "自分の力に合った仕事を探す、という意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気に合った仕事、では文の意図にならない。"}, {"text": "道路", "is_correct": false, "explanation": "意味：道路は人の力ではなく、仕事を選ぶ基準にならない。"}, {"text": "机", "is_correct": false, "explanation": "連語：「机に合った仕事」という結びつきは不自然。"}], "explanations": {"能力": "自分の力に合った仕事を探す、という意味になる。", "天気": "意味：天気に合った仕事、では文の意図にならない。", "道路": "意味：道路は人の力ではなく、仕事を選ぶ基準にならない。", "机": "連語：「机に合った仕事」という結びつきは不自然。"}, "sentence_index": 6, "correct_answer": "能力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "能力に十分に発揮できた。", "explanation": "助詞の誤り：「発揮する」の対象は「を」。"}, {"text": "能力を十分に食べた。", "explanation": "連語の誤り：能力は「発揮する」もので「食べる」とはいわない。"}, {"text": "能力を十分に冷やした。", "explanation": "連語の誤り：能力は「冷やす」ものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37451, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "能力が十分に発揮した。", "corrected_sentence": "能力を十分に発揮した。", "error_description": "助詞の誤り：「発揮する」は他動詞なので、発揮するものは「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37451, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「認める」動作をする人（皆）を示す主格の助詞。"}, {"text": "を", "is_correct": false, "explanation": "「皆を認める」となり、文の意味が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「皆に認めている」は非文。受身でなければ使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「認める」の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「認める」動作をする人（皆）を示す主格の助詞。", "を": "「皆を認める」となり、文の意味が崩れる。", "に": "「皆に認めている」は非文。受身でなければ使えない。", "へ": "方向を表し、「認める」の主語を示せない。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無能", "is_correct": true, "explanation": "能力がないことで、能力の対義語。"}, {"text": "技能", "is_correct": false, "explanation": "技術的な能力で、類義語に近い。"}, {"text": "知識", "is_correct": false, "explanation": "知っていることで、対義ではない。"}, {"text": "才能", "is_correct": false, "explanation": "生まれつきの力で、類義であり対義ではない。"}], "correct_answer": "無能", "explanations": {"無能": "能力がないことで、能力の対義語。", "技能": "技術的な能力で、類義語に近い。", "知識": "知っていることで、対義ではない。", "才能": "生まれつきの力で、類義であり対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51536, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穀物", "is_correct": true, "explanation": "対象語。"}, {"text": "作物", "is_correct": false, "explanation": "さくもつ：第1モーラ「こ」が「さ」に変わる一モーラ差。"}, {"text": "食物", "is_correct": false, "explanation": "しょくもつ：第1モーラ「こ」が「しょ」に変わる一モーラ差。"}, {"text": "供物", "is_correct": false, "explanation": "くもつ：第1モーラ「こ」が抜けた一モーラ差。"}], "explanations": {"穀物": "対象語。", "作物": "さくもつ：第1モーラ「こ」が「さ」に変わる一モーラ差。", "食物": "しょくもつ：第1モーラ「こ」が「しょ」に変わる一モーラ差。", "供物": "くもつ：第1モーラ「こ」が抜けた一モーラ差。"}, "sentence_index": null, "correct_answer": "穀物"}, "level_3": {"options": [{"text": "穀物", "is_correct": true, "explanation": "米・麦など、豆類と並んで主食になる食べ物。"}, {"text": "金属", "is_correct": false, "explanation": "意味：食べ物ではなく主食にならない。"}, {"text": "薬品", "is_correct": false, "explanation": "連語：「薬品を主食として摂取する」は不自然。"}, {"text": "家具", "is_correct": false, "explanation": "意味：食べられる物ではない。"}], "explanations": {"穀物": "米・麦など、豆類と並んで主食になる食べ物。", "金属": "意味：食べ物ではなく主食にならない。", "薬品": "連語：「薬品を主食として摂取する」は不自然。", "家具": "意味：食べられる物ではない。"}, "sentence_index": 0, "correct_answer": "穀物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "穀物を三人買った。", "explanation": "助数詞の誤り：穀物は人ではないので「人」で数えない。"}, {"text": "穀物で畑が実った。", "explanation": "助詞の誤り：実るのは穀物なので「穀物が畑で実った」が正しい。"}, {"text": "鉄は大切な穀物です。", "explanation": "意味の誤り：鉄は金属で、米や麦のような食用の種子ではないので穀物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51536, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この国は穀物がたくさん作る。", "corrected_sentence": "この国は穀物をたくさん作る。", "error_description": "助詞の誤り：「作る」の目的語は「を」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51536, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「昇華される」ものを示す主格の助詞。"}, {"text": "を", "is_correct": false, "explanation": "受身「昇華される」の主語に「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、主語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "この位置では受身の主語にならず非文。"}], "correct_answer": "が", "explanations": {"が": "「昇華される」ものを示す主格の助詞。", "を": "受身「昇華される」の主語に「を」は使えない。", "で": "手段を表し、主語を示せない。", "に": "この位置では受身の主語にならず非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "に": "location_vs_target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51536, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "穀物", "is_correct": true, "explanation": "対象語。"}, {"text": "書物", "is_correct": false, "explanation": "しょもつ：「こく」が「しょ」に変わる違い。"}, {"text": "荷物", "is_correct": false, "explanation": "にもつ：「こく」が「に」に変わる違い。"}, {"text": "禁物", "is_correct": false, "explanation": "きんもつ：「こく」が「きん」に変わる違い。"}], "explanations": {"穀物": "対象語。", "書物": "しょもつ：「こく」が「しょ」に変わる違い。", "荷物": "にもつ：「こく」が「に」に変わる違い。", "禁物": "きんもつ：「こく」が「きん」に変わる違い。"}, "sentence_index": null, "correct_answer": "穀物"}, "level_3": {"options": [{"text": "穀物", "is_correct": true, "explanation": "倉庫に米や麦などを保存する、という自然な文。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は倉庫に保存できない。"}, {"text": "景色", "is_correct": false, "explanation": "意味：景色は物ではなく保存できない。"}, {"text": "約束", "is_correct": false, "explanation": "連語：「約束を倉庫に保存する」は不自然。"}], "explanations": {"穀物": "倉庫に米や麦などを保存する、という自然な文。", "天気": "意味：天気は倉庫に保存できない。", "景色": "意味：景色は物ではなく保存できない。", "約束": "連語：「約束を倉庫に保存する」は不自然。"}, "sentence_index": 6, "correct_answer": "穀物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "穀物を一匹買った。", "explanation": "助数詞の誤り：穀物は動物ではないので「匹」で数えない。"}, {"text": "穀物が私を食べた。", "explanation": "意味の誤り：穀物は食べられる側で、食べる主体にならない。"}, {"text": "穀物で外国から買っている。", "explanation": "助詞の誤り：買う対象は「を」で示すべきで「で」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
