INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51536, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "だめになった原因（雨）を示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "「雨を」は目的語になり、この文では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、原因を示せない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表し、原因を示せない。"}], "correct_answer": "で", "explanations": {"で": "だめになった原因（雨）を示す助詞。", "を": "「雨を」は目的語になり、この文では非文。", "へ": "方向を表し、原因を示せない。", "と": "並列・相手を表し、原因を示せない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "と": "listing"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35673, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "発酵", "is_correct": true, "explanation": "対象語。"}, {"text": "学校", "is_correct": false, "explanation": "がっこう：第1モーラ「は」が「が」に変わる一モーラ差。"}, {"text": "格好", "is_correct": false, "explanation": "かっこう：第1モーラ「は」が「か」に変わる一モーラ差。"}, {"text": "発想", "is_correct": false, "explanation": "はっそう：第3モーラ「こ」が「そ」に変わる一モーラ差。"}, {"text": "発砲", "is_correct": false, "explanation": "はっぽう：第3モーラ「こ」が「ぽ」に変わる一モーラ差。"}, {"text": "発祥", "is_correct": false, "explanation": "はっしょう：第3モーラ「こ」が「しょ」に変わる一モーラ差。"}], "explanations": {"発酵": "対象語。", "学校": "がっこう：第1モーラ「は」が「が」に変わる一モーラ差。", "格好": "かっこう：第1モーラ「は」が「か」に変わる一モーラ差。", "発想": "はっそう：第3モーラ「こ」が「そ」に変わる一モーラ差。", "発砲": "はっぽう：第3モーラ「こ」が「ぽ」に変わる一モーラ差。", "発祥": "はっしょう：第3モーラ「こ」が「しょ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "発酵"}, "level_3": {"options": [{"text": "発酵", "is_correct": true, "explanation": "微生物の代謝作用としての発酵を表す。"}, {"text": "地震", "is_correct": false, "explanation": "意味：地震は微生物の作用ではない。"}, {"text": "選挙", "is_correct": false, "explanation": "意味：選挙は社会の制度で、代謝作用ではない。"}, {"text": "輸送", "is_correct": false, "explanation": "連語：「微生物の代謝作用である輸送」は不自然。"}], "explanations": {"発酵": "微生物の代謝作用としての発酵を表す。", "地震": "意味：地震は微生物の作用ではない。", "選挙": "意味：選挙は社会の制度で、代謝作用ではない。", "輸送": "連語：「微生物の代謝作用である輸送」は不自然。"}, "sentence_index": 0, "correct_answer": "発酵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "発酵を三枚食べた。", "explanation": "助数詞・意味の誤り：発酵は食べ物ではなく「枚」で数えない。"}, {"text": "発酵で駅まで歩いた。", "explanation": "意味の誤り：発酵は移動の手段にならない。"}, {"text": "発酵に座って休んだ。", "explanation": "意味の誤り：発酵は化学変化で、座る場所ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
