INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35673, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "発酵", "is_correct": true, "explanation": "対象語。"}, {"text": "発狂", "is_correct": false, "explanation": "はっきょう：第3モーラ「こ」が「きょ」に変わる一モーラ差。"}, {"text": "白骨", "is_correct": false, "explanation": "はっこつ：最後のモーラ「う」が「つ」に変わる一モーラ差。"}, {"text": "発送", "is_correct": false, "explanation": "はっそう：第3モーラ「こ」が「そ」に変わる一モーラ差。"}, {"text": "格好", "is_correct": false, "explanation": "かっこう：第1モーラ「は」が「か」に変わる一モーラ差。"}, {"text": "学校", "is_correct": false, "explanation": "がっこう：第1モーラ「は」が濁音「が」に変わる違い。"}], "explanations": {"発酵": "対象語。", "発狂": "はっきょう：第3モーラ「こ」が「きょ」に変わる一モーラ差。", "白骨": "はっこつ：最後のモーラ「う」が「つ」に変わる一モーラ差。", "発送": "はっそう：第3モーラ「こ」が「そ」に変わる一モーラ差。", "格好": "かっこう：第1モーラ「は」が「か」に変わる一モーラ差。", "学校": "がっこう：第1モーラ「は」が濁音「が」に変わる違い。"}, "sentence_index": null, "correct_answer": "発酵"}, "level_3": {"options": [{"text": "発酵", "is_correct": true, "explanation": "夏は気温が高く、発酵が早く進む。"}, {"text": "気温", "is_correct": false, "explanation": "連語：「気温が早く進む」とは言わない。"}, {"text": "野菜", "is_correct": false, "explanation": "意味：野菜は進むものではない。"}, {"text": "色", "is_correct": false, "explanation": "連語：「色が早く進む」とは言わない。"}], "explanations": {"発酵": "夏は気温が高く、発酵が早く進む。", "気温": "連語：「気温が早く進む」とは言わない。", "野菜": "意味：野菜は進むものではない。", "色": "連語：「色が早く進む」とは言わない。"}, "sentence_index": 6, "correct_answer": "発酵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "発酵を一冊買った。", "explanation": "助数詞の誤り：発酵は本ではないので「冊」で数えない。"}, {"text": "発酵が温度を低くした。", "explanation": "意味の誤り：発酵は温度を下げる主体ではない。"}, {"text": "発酵を手紙で送った。", "explanation": "意味の誤り：発酵は物ではない現象なので、郵送できない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUD