INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52080, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凝縮", "is_correct": true, "explanation": "対象語。"}, {"text": "恐縮", "is_correct": false, "explanation": "きょうしゅく：第1モーラが清音「きょ」になる清濁の違い。"}, {"text": "業種", "is_correct": false, "explanation": "ぎょうしゅ：最後のモーラ「く」がない一モーラ差。"}, {"text": "濃縮", "is_correct": false, "explanation": "のうしゅく：第1モーラ「ぎょ」が「の」に変わる一モーラ差。"}, {"text": "拘縮", "is_correct": false, "explanation": "こうしゅく：第1モーラ「ぎょ」が「こ」に変わる一モーラ差。"}], "explanations": {"凝縮": "対象語。", "恐縮": "きょうしゅく：第1モーラが清音「きょ」になる清濁の違い。", "業種": "ぎょうしゅ：最後のモーラ「く」がない一モーラ差。", "濃縮": "のうしゅく：第1モーラ「ぎょ」が「の」に変わる一モーラ差。", "拘縮": "こうしゅく：第1モーラ「ぎょ」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "凝縮"}, "level_3": {"options": [{"text": "凝縮", "is_correct": true, "explanation": "大切な役割がぎっしり詰まっている、という意味になる。"}, {"text": "運転", "is_correct": false, "explanation": "意味：役割が運転されることはない。"}, {"text": "誕生", "is_correct": false, "explanation": "項構造：「誕生される」という受身は作れない。"}, {"text": "休憩", "is_correct": false, "explanation": "項構造：「休憩される」は役割を主語にとれない。"}], "explanations": {"凝縮": "大切な役割がぎっしり詰まっている、という意味になる。", "運転": "意味：役割が運転されることはない。", "誕生": "項構造：「誕生される」という受身は作れない。", "休憩": "項構造：「休憩される」は役割を主語にとれない。"}, "sentence_index": 0, "correct_answer": "凝縮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凝縮を三枚買った。", "explanation": "助数詞・意味の誤り：凝縮は物ではなく「枚」で数えない。"}, {"text": "彼の考えがこの本を凝縮されている。", "explanation": "助詞の誤り：受身の文で「を」は使えない。「この本には」が正しい。"}, {"text": "水が凝縮されて大きく広がった。", "explanation": "意味の誤り：凝縮は詰まって小さくなることで、広がるとは逆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_e