INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39435, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「融合した」ものを示す主格の助詞。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、「融合した」の主語を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、この位置では非文。"}], "correct_answer": "が", "explanations": {"が": "「融合した」ものを示す主格の助詞。", "から": "起点を表し、「融合した」の主語を示せない。", "で": "手段を表し、主語を示せない。", "へ": "方向を表し、この位置では非文。"}, "error_tags": {"から": "source_vs_goal", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分離", "is_correct": true, "explanation": "分かれて離れることで、融合の対義語。"}, {"text": "統合", "is_correct": false, "explanation": "一つにまとめることで、類義語。"}, {"text": "結合", "is_correct": false, "explanation": "結びつくことで、類義語。"}, {"text": "合併", "is_correct": false, "explanation": "一つに合わさることで、類義に近い。"}], "correct_answer": "分離", "explanations": {"分離": "分かれて離れることで、融合の対義語。", "統合": "一つにまとめることで、類義語。", "結合": "結びつくことで、類義語。", "合併": "一つに合わさることで、類義に近い。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39435, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "融合", "is_correct": true, "explanation": "対象語。"}, {"text": "勇壮", "is_correct": false, "explanation": "ゆうそう：「ご」が「そ」に変わる一モーラ差。"}, {"text": "優遇", "is_correct": false, "explanation": "ゆうぐう：「ごう」が「ぐう」に変わる違い。"}, {"text": "有能", "is_correct": false, "explanation": "ゆうのう：「ご」が「の」に変わる一モーラ差。"}, {"text": "友好", "is_correct": false, "explanation": "ゆうこう：「ご」が清音「こ」になる違い。"}], "explanations": {"融合": "対象語。", "勇壮": "ゆうそう：「ご」が「そ」に変わる一モーラ差。", "優遇": "ゆうぐう：「ごう」が「ぐう」に変わる違い。", "有能": "ゆうのう：「ご」が「の」に変わる一モーラ差。", "友好": "ゆうこう：「ご」が清音「こ」になる違い。"}, "sentence_index": null, "correct_answer": "融合"}, "level_3": {"options": [{"text": "融合", "is_correct": true, "explanation": "異なるものが一つになるには時間がかかる、という意味。"}, {"text": "机", "is_correct": false, "explanation": "意味：机は時間を必要とするものではない。"}, {"text": "昨日", "is_correct": false, "explanation": "意味：過去の日で、「には時間が必要だ」と結びつかない。"}, {"text": "青", "is_correct": false, "explanation": "連語：「青には時間が必要だ」は不自然。"}], "explanations": {"融合": "異なるものが一つになるには時間がかかる、という意味。", "机": "意味：机は時間を必要とするものではない。", "昨日": "意味：過去の日で、「には時間が必要だ」と結びつかない。", "青": "連語：「青には時間が必要だ」は不自然。"}, "sentence_index": 6, "correct_answer": "融合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "融合を二匹飼っている。", "explanation": "助数詞の誤り：融合は動物ではないので「匹」で数えない。"}, {"text": "融合が二階で寝ている。", "explanation": "意味の誤り：融合は出来事で、人のように寝ることはない。"}, {"text": "融合を冷蔵庫に入れた。", "explanation": "意味の誤り：融合は物ではないので冷蔵庫に入れられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
