INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39435, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「融合した」ものを示す主格の助詞。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、主語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表し、この文では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「融合した」ものを示す主格の助詞。", "で": "手段を表し、主語を示せない。", "から": "起点を表し、この文では非文。", "へ": "方向を表し、主語を示せない。"}, "error_tags": {"で": "instrument", "から": "source_vs_goal", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分裂", "is_correct": true, "explanation": "一つのものが分かれることで、融合の対義語。"}, {"text": "調和", "is_correct": false, "explanation": "うまく合うことで、類義に近い。"}, {"text": "結合", "is_correct": false, "explanation": "結びつくことで、類義語。"}, {"text": "統一", "is_correct": false, "explanation": "一つにまとめることで、類義語。"}], "correct_answer": "分裂", "explanations": {"分裂": "一つのものが分かれることで、融合の対義語。", "調和": "うまく合うことで、類義に近い。", "結合": "結びつくことで、類義語。", "統一": "一つにまとめることで、類義語。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36943, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "評価", "is_correct": true, "explanation": "「ひょうか」と聞こえる正解。"}, {"text": "氷河", "is_correct": false, "explanation": "「ひょうが」で、か／がが違う。"}, {"text": "表記", "is_correct": false, "explanation": "「ひょうき」で、最後の音が違う。"}, {"text": "評判", "is_correct": false, "explanation": "「ひょうばん」で、後半が違う。"}, {"text": "標高", "is_correct": false, "explanation": "「ひょうこう」で、後半が違う。"}], "explanations": {"評価": "「ひょうか」と聞こえる正解。", "氷河": "「ひょうが」で、か／がが違う。", "表記": "「ひょうき」で、最後の音が違う。", "評判": "「ひょうばん」で、後半が違う。", "標高": "「ひょうこう」で、後半が違う。"}, "sentence_index": null, "correct_answer": "評価"}, "level_3": {"options": [{"text": "評価", "is_correct": true, "explanation": "「世界的に評価される」は価値が認められるという意味。"}, {"text": "説明", "is_correct": false, "explanation": "芸術が「説明される」では、文の意味が通らない。"}, {"text": "注文", "is_correct": false, "explanation": "芸術が「注文される」は文脈に合わない。"}, {"text": "修理", "is_correct": false, "explanation": "意味：芸術が世界的に修理される、では意味が通らない。"}], "explanations": {"評価": "「世界的に評価される」は価値が認められるという意味。", "説明": "芸術が「説明される」では、文の意味が通らない。", "注文": "芸術が「注文される」は文脈に合わない。", "修理": "意味：芸術が世界的に修理される、では意味が通らない。"}, "sentence_index": 0, "correct_answer": "評価"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱を評価して、棚に置いてください。", "explanation": "評価は価値を判断することで、物を動かす意味はない。"}, {"text": "雨が評価して、道がぬれた。", "explanation": "雨は評価する主体になれない。"}, {"text": "評価を一杯飲んだ。", "explanation": "評価は判断することで、飲み物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36943, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "テストの結果で成績を評価る。", "corrected_sentence": "テストの結果で成績を評価する。", "error_description": "活用の誤り：「評価」は「評価する」と「する」をつけて動詞にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
