INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36943, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "評価", "is_correct": true, "explanation": "正解の「ひょうか」。"}, {"text": "降下", "is_correct": false, "explanation": "「こうか」で、最初の音が違う。"}, {"text": "表彰", "is_correct": false, "explanation": "「ひょうしょう」で後半が違う。"}, {"text": "表裏", "is_correct": false, "explanation": "「ひょうり」で、最後の音が違う。"}, {"text": "ひよこ", "is_correct": false, "explanation": "「ひよこ」で、音が似ているが違う。"}], "explanations": {"評価": "正解の「ひょうか」。", "降下": "「こうか」で、最初の音が違う。", "表彰": "「ひょうしょう」で後半が違う。", "表裏": "「ひょうり」で、最後の音が違う。", "ひよこ": "「ひよこ」で、音が似ているが違う。"}, "sentence_index": null, "correct_answer": "評価"}, "level_3": {"options": [{"text": "評価", "is_correct": true, "explanation": "「みんなの評価」は人々の判断・意見の意味。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を聞いて安心」は文脈に合いにくい。"}, {"text": "机", "is_correct": false, "explanation": "意味：みんなの机を聞くことはできない。"}, {"text": "速度", "is_correct": false, "explanation": "「みんなの速度を聞く」は意味が通らない。"}], "explanations": {"評価": "「みんなの評価」は人々の判断・意見の意味。", "天気": "「天気を聞いて安心」は文脈に合いにくい。", "机": "意味：みんなの机を聞くことはできない。", "速度": "「みんなの速度を聞く」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "評価"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "評価で手を洗ってから食べよう。", "explanation": "評価は道具ではない。"}, {"text": "駅まで評価で十分かかる。", "explanation": "評価は時間や距離を表さない。"}, {"text": "冷蔵庫に評価を入れておいた。", "explanation": "評価は物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36943, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その本はネットで良い評価に受けている。", "corrected_sentence": "その本はネットで良い評価を受けている。", "error_description": "助詞の誤り：「受ける」の目的語「評価」は「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36943, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「自分で」は自分自身がするという意味。"}, {"text": "を", "is_correct": false, "explanation": "「自分を評価する」になり意味が変わる。"}, {"text": "に", "is_correct": false, "explanation": "「自分に評価する」は誤り。動作主は「で」で示す。"}, {"text": "へ", "is_correct": false, "explanation": "「自分へ評価する」は不自然。"}], "correct_answer": "で", "explanations": {"で": "「自分で」は自分自身がするという意味。", "を": "「自分を評価する」になり意味が変わる。", "に": "「自分に評価する」は誤り。動作主は「で」で示す。", "へ": "「自分へ評価する」は不自然。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35195, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与える", "is_correct": true, "explanation": "正解の「あたえる」。"}, {"text": "支える", "is_correct": false, "explanation": "「ささえる」で、最初の音が違う。"}, {"text": "数える", "is_correct": false, "explanation": "「かぞえる」で、前半が違う。"}, {"text": "耐える", "is_correct": false, "explanation": "「たえる」で、最初の音がない。"}, {"text": "当てる", "is_correct": false, "explanation": "「あてる」で、途中が違う。"}], "explanations": {"与える": "正解の「あたえる」。", "支える": "「ささえる」で、最初の音が違う。", "数える": "「かぞえる」で、前半が違う。", "耐える": "「たえる」で、最初の音がない。", "当てる": "「あてる」で、途中が違う。"}, "sentence_index": null, "correct_answer": "与える"}, "level_3": {"options": [{"text": "与える", "is_correct": true, "explanation": "水や肥料を作物に渡すので「与える」が合う。"}, {"text": "奪う", "is_correct": false, "explanation": "水や肥料を奪う仕組みでは意味が逆。"}, {"text": "隠す", "is_correct": false, "explanation": "肥料を隠す仕組みは文脈に合わない。"}, {"text": "忘れる", "is_correct": false, "explanation": "「的確に忘れる」は意味が通らない。"}], "explanations": {"与える": "水や肥料を作物に渡すので「与える」が合う。", "奪う": "水や肥料を奪う仕組みでは意味が逆。", "隠す": "肥料を隠す仕組みは文脈に合わない。", "忘れる": "「的確に忘れる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "与える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は大きな影を与えて、ゆっくり歩いた。", "explanation": "影を「与える」とは言わない。"}, {"text": "駅で電車を与えて、学校へ行った。", "explanation": "電車は「乗る」もので、与えない。"}, {"text": "私は昨日、友だちから手紙を与えた。", "explanation": "「から」と一緒なら「もらった」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35195, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "必要な水や肥料に的確に与える仕組みです。", "corrected_sentence": "必要な水や肥料を的確に与える仕組みです。", "error_description": "与えるものは「を」で示す。「水や肥料に与える」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "与える", "is_correct": true, "explanation": "後ろの名詞「食べ物」を修飾する辞書形。"}, {"text": "与えて", "is_correct": false, "explanation": "て形では名詞につながらない。"}, {"text": "与えれば", "is_correct": false, "explanation": "条件形は名詞「食べ物」を修飾しない。"}, {"text": "与えろ", "is_correct": false, "explanation": "命令形は名詞を修飾しない。"}], "correct_form": "与える", "base_form": "与える", "form_label": "辞書形（連体）", "sentence_index": 1, "explanations": {"与える": "後ろの名詞「食べ物」を修飾する辞書形。", "与えて": "て形では名詞につながらない。", "与えれば": "条件形は名詞「食べ物」を修飾しない。", "与えろ": "命令形は名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35195, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「この時間帯に」で時を示す。"}, {"text": "を", "is_correct": false, "explanation": "「時間帯を与える」になり意味が変わる。"}, {"text": "が", "is_correct": false, "explanation": "「時間帯が与える」は誤り。"}, {"text": "へ", "is_correct": false, "explanation": "時を表すのに「へ」は使わない。"}], "correct_answer": "に", "explanations": {"に": "「この時間帯に」で時を示す。", "を": "「時間帯を与える」になり意味が変わる。", "が": "「時間帯が与える」は誤り。", "へ": "時を表すのに「へ」は使わない。"}, "error_tags": {"を": "wrong_case", "が": "subject_object", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奪う", "is_correct": true, "explanation": "「与える」の反対で、相手から取り上げること。"}, {"text": "渡す", "is_correct": false, "explanation": "「与える」と近い意味で、反対ではない。"}, {"text": "配る", "is_correct": false, "explanation": "人に分けて渡すことで、反対ではない。"}, {"text": "育てる", "is_correct": false, "explanation": "世話をすることで、反対の意味ではない。"}], "correct_answer": "奪う", "explanations": {"奪う": "「与える」の反対で、相手から取り上げること。", "渡す": "「与える」と近い意味で、反対ではない。", "配る": "人に分けて渡すことで、反対ではない。", "育てる": "世話をすることで、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35195, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "与える", "is_correct": true, "explanation": "正解の「あたえる」。"}, {"text": "抑える", "is_correct": false, "explanation": "「おさえる」で、最初の音が違う。"}, {"text": "終える", "is_correct": false, "explanation": "「おえる」で、音の数が違う。"}, {"text": "考える", "is_correct": false, "explanation": "「かんがえる」で、前半が違う。"}, {"text": "あわてる", "is_correct": false, "explanation": "「あわてる」で、後半が違う。"}], "explanations": {"与える": "正解の「あたえる」。", "抑える": "「おさえる」で、最初の音が違う。", "終える": "「おえる」で、音の数が違う。", "考える": "「かんがえる」で、前半が違う。", "あわてる": "「あわてる」で、後半が違う。"}, "sentence_index": null, "correct_answer": "与える"}, "level_3": {"options": [{"text": "与え", "is_correct": true, "explanation": "えさが動物に渡されるので「与えられる」が合う。"}, {"text": "答え", "is_correct": false, "explanation": "「えさが答えられる」は意味が通らない。"}, {"text": "着", "is_correct": false, "explanation": "「えさが着られる」は意味が通らない。"}, {"text": "売れ", "is_correct": false, "explanation": "「えさが売れる」は文の形に合わない。"}], "explanations": {"与え": "えさが動物に渡されるので「与えられる」が合う。", "答え": "「えさが答えられる」は意味が通らない。", "着": "「えさが着られる」は意味が通らない。", "売れ": "「えさが売れる」は文の形に合わない。"}, "sentence_index": 6, "correct_answer": "与え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ねこが窓の外を与えている。", "explanation": "「外を見る」が正しく、与えるは使えない。"}, {"text": "雨が与えて、かさを持って出た。", "explanation": "雨は「降る」もので与えない。"}, {"text": "ぼくは毎朝七時に目を与える。", "explanation": "「目を覚ます」が正しく、「目を与える」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35195, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ねこにミルクを与えらってはいけない。", "corrected_sentence": "ねこにミルクを与えてはいけない。", "error_description": "「与えらって」という活用はない。て形は「与えて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "与え", "is_correct": true, "explanation": "意向形「与えよう」の語幹部分。"}, {"text": "与えろ", "is_correct": false, "explanation": "「与えろよう」という形はない。"}, {"text": "与えて", "is_correct": false, "explanation": "「与えてよう」という形はない。"}, {"text": "与えれ", "is_correct": false, "explanation": "「与えれよう」という形はない。"}], "correct_form": "与え", "base_form": "与える", "form_label": "意向形（与えよう）", "sentence_index": 7, "explanations": {"与え": "意向形「与えよう」の語幹部分。", "与えろ": "「与えろよう」という形はない。", "与えて": "「与えてよう」という形はない。", "与えれ": "「与えれよう」という形はない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35195, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "与えるもの「チャンス」を示す。"}, {"text": "に", "is_correct": false, "explanation": "「チャンスに与える」では受け手になる。"}, {"text": "が", "is_correct": false, "explanation": "「チャンスが与えよう」は誤り。"}, {"text": "で", "is_correct": false, "explanation": "「チャンスで」は手段になり意味が変わる。"}], "correct_answer": "を", "explanations": {"を": "与えるもの「チャンス」を示す。", "に": "「チャンスに与える」では受け手になる。", "が": "「チャンスが与えよう」は誤り。", "で": "「チャンスで」は手段になり意味が変わる。"}, "error_tags": {"に": "wrong_case", "が": "subject_object", "で": "means"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受け取る", "is_correct": true, "explanation": "与える側の反対で、もらう側の動作。"}, {"text": "あげる", "is_correct": false, "explanation": "与えるとほぼ同じ意味。"}, {"text": "与え直す", "is_correct": false, "explanation": "同じ動作をもう一度すること。"}, {"text": "見せる", "is_correct": false, "explanation": "相手に見えるようにすることで反対ではない。"}], "correct_answer": "受け取る", "explanations": {"受け取る": "与える側の反対で、もらう側の動作。", "あげる": "与えるとほぼ同じ意味。", "与え直す": "同じ動作をもう一度すること。", "見せる": "相手に見えるようにすることで反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42675, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "過酷", "is_correct": true, "explanation": "正解の「かこく」。"}, {"text": "過去", "is_correct": false, "explanation": "「かこ」で、最後の音がない。"}, {"text": "価格", "is_correct": false, "explanation": "「かかく」で、真ん中の音が違う。"}, {"text": "各国", "is_correct": false, "explanation": "「かっこく」で、促音が入る。"}, {"text": "加工", "is_correct": false, "explanation": "「かこう」で、最後の音が違う。"}], "explanations": {"過酷": "正解の「かこく」。", "過去": "「かこ」で、最後の音がない。", "価格": "「かかく」で、真ん中の音が違う。", "各国": "「かっこく」で、促音が入る。", "加工": "「かこう」で、最後の音が違う。"}, "sentence_index": null, "correct_answer": "過酷"}, "level_3": {"options": [{"text": "過酷", "is_correct": true, "explanation": "泥にまみれた労働なので「過酷な」が合う。"}, {"text": "快適", "is_correct": false, "explanation": "「裏腹に」とあるので美しさと逆の厳しさが必要。快適は合わない。"}, {"text": "静か", "is_correct": false, "explanation": "肉体労働を「静かな」とは言わない。"}, {"text": "便利", "is_correct": false, "explanation": "労働が「便利な」は不自然。"}], "explanations": {"過酷": "泥にまみれた労働なので「過酷な」が合う。", "快適": "「裏腹に」とあるので美しさと逆の厳しさが必要。快適は合わない。", "静か": "肉体労働を「静かな」とは言わない。", "便利": "労働が「便利な」は不自然。"}, "sentence_index": 0, "correct_answer": "過酷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この過酷はとてもおいしい。", "explanation": "過酷は様子を表す語で、食べ物ではない。"}, {"text": "彼は毎朝過酷して、学校に行く。", "explanation": "「過酷する」という動詞はない。"}, {"text": "赤ちゃんの過酷な笑顔がかわいい。", "explanation": "笑顔に「厳しくつらい」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷い肉体労働の連続でした。", "corrected_sentence": "最初の一年は、美しい田園風景とは裏腹に、泥にまみれた過酷な肉体労働の連続でした。", "error_description": "「過酷」はな形容詞なので「過酷い」ではなく「過酷な」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "過酷", "is_correct": true, "explanation": "「過酷だ」の形で文を終える。"}, {"text": "過酷な", "is_correct": false, "explanation": "「過酷なだ」とは言わない。"}, {"text": "過酷に", "is_correct": false, "explanation": "「過酷にだ」とは言わない。"}, {"text": "過酷さ", "is_correct": false, "explanation": "「とても過酷さだ」は不自然。"}], "correct_form": "過酷", "base_form": "過酷", "form_label": "語幹（過酷だ）", "sentence_index": 1, "explanations": {"過酷": "「過酷だ」の形で文を終える。", "過酷な": "「過酷なだ」とは言わない。", "過酷に": "「過酷にだ」とは言わない。", "過酷さ": "「とても過酷さだ」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42675, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快適", "is_correct": true, "explanation": "心地よく過ごしやすいことで、過酷の反対。"}, {"text": "厳しい", "is_correct": false, "explanation": "過酷と近い意味。"}, {"text": "苛烈", "is_correct": false, "explanation": "非常に激しく厳しいことで、近い意味。"}, {"text": "つらい", "is_correct": false, "explanation": "苦しいことで、近い意味。"}], "correct_answer": "快適", "explanations": {"快適": "心地よく過ごしやすいことで、過酷の反対。", "厳しい": "過酷と近い意味。", "苛烈": "非常に激しく厳しいことで、近い意味。", "つらい": "苦しいことで、近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42675, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "過酷", "is_correct": true, "explanation": "正解の「かこく」。"}, {"text": "覚悟", "is_correct": false, "explanation": "「かくご」で、音の順が違う。"}, {"text": "拡張", "is_correct": false, "explanation": "「かくちょう」で、後半が違う。"}, {"text": "監獄", "is_correct": false, "explanation": "「かんごく」で、音が違う。"}, {"text": "かこう", "is_correct": false, "explanation": "「かこう」で、最後の音が違う。"}], "explanations": {"過酷": "正解の「かこく」。", "覚悟": "「かくご」で、音の順が違う。", "拡張": "「かくちょう」で、後半が違う。", "監獄": "「かんごく」で、音が違う。", "かこう": "「かこう」で、最後の音が違う。"}, "sentence_index": null, "correct_answer": "過酷"}, "level_3": {"options": [{"text": "過酷", "is_correct": true, "explanation": "昔の工場の厳しい労働環境を表す。"}, {"text": "正直", "is_correct": false, "explanation": "場所を「正直な」とは言わない。"}, {"text": "高価", "is_correct": false, "explanation": "工場を「高価な場所」とは言わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "工場を「新鮮な場所」とは言わない。"}], "explanations": {"過酷": "昔の工場の厳しい労働環境を表す。", "正直": "場所を「正直な」とは言わない。", "高価": "工場を「高価な場所」とは言わない。", "新鮮": "工場を「新鮮な場所」とは言わない。"}, "sentence_index": 6, "correct_answer": "過酷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このケーキは過酷に甘くておいしい。", "explanation": "「過酷」はつらさを表し、味をほめるのには使わない。"}, {"text": "過酷を一つください。", "explanation": "過酷は物ではない。"}, {"text": "春の風は過酷で気持ちがいい。", "explanation": "気持ちがいいものを過酷とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の工場は過酷の場所だった。", "corrected_sentence": "昔の工場は過酷な場所だった。", "error_description": "名詞を修飾するときは「過酷の」ではなく「過酷な」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "過酷", "is_correct": true, "explanation": "後ろの「な」とあわせて名詞を修飾する語幹。"}, {"text": "過酷だ", "is_correct": false, "explanation": "「過酷だなレース」とは言わない。"}, {"text": "過酷に", "is_correct": false, "explanation": "「過酷になレース」とは言わない。"}, {"text": "過酷さ", "is_correct": false, "explanation": "「過酷さなレース」とは言わない。"}], "correct_form": "過酷", "base_form": "過酷", "form_label": "語幹（連体形 過酷な）", "sentence_index": 7, "explanations": {"過酷": "後ろの「な」とあわせて名詞を修飾する語幹。", "過酷だ": "「過酷だなレース」とは言わない。", "過酷に": "「過酷になレース」とは言わない。", "過酷さ": "「過酷さなレース」とは言わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42675, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "楽", "is_correct": true, "explanation": "つらくないことで、過酷の反対。"}, {"text": "きつい", "is_correct": false, "explanation": "過酷と近い意味。"}, {"text": "ハード", "is_correct": false, "explanation": "厳しいことで、近い意味。"}, {"text": "大変", "is_correct": false, "explanation": "苦労が多いことで、近い意味。"}], "correct_answer": "楽", "explanations": {"楽": "つらくないことで、過酷の反対。", "きつい": "過酷と近い意味。", "ハード": "厳しいことで、近い意味。", "大変": "苦労が多いことで、近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36803, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "野菜", "is_correct": true, "explanation": "正解の「やさい」。"}, {"text": "易しい", "is_correct": false, "explanation": "「やさしい」で、後に音が増える。"}, {"text": "矢先", "is_correct": false, "explanation": "「やさき」で、最後の音が違う。"}, {"text": "火災", "is_correct": false, "explanation": "「かさい」で、最初の音が違う。"}, {"text": "やせい", "is_correct": false, "explanation": "「やせい」（野生）で、真ん中の音が違う。"}], "explanations": {"野菜": "正解の「やさい」。", "易しい": "「やさしい」で、後に音が増える。", "矢先": "「やさき」で、最後の音が違う。", "火災": "「かさい」で、最初の音が違う。", "やせい": "「やせい」（野生）で、真ん中の音が違う。"}, "sentence_index": null, "correct_answer": "野菜"}, "level_3": {"options": [{"text": "野菜", "is_correct": true, "explanation": "農薬を使わずに育てるのは畑の作物である野菜。"}, {"text": "機械", "is_correct": false, "explanation": "機械は「育てる」ものではない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙を農薬なしで育てることはない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は育てるものではない。"}], "explanations": {"野菜": "農薬を使わずに育てるのは畑の作物である野菜。", "機械": "機械は「育てる」ものではない。", "手紙": "手紙を農薬なしで育てることはない。", "時計": "時計は育てるものではない。"}, "sentence_index": 0, "correct_answer": "野菜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "野菜で駅まで走っていった。", "explanation": "野菜は乗り物ではない。"}, {"text": "今日は野菜がとても暑い。", "explanation": "野菜は天気を表さない。"}, {"text": "彼は野菜を読むのが好きだ。", "explanation": "野菜は読むものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
