INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36803, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "野菜", "is_correct": true, "explanation": "正解の「やさい」。"}, {"text": "小さい", "is_correct": false, "explanation": "「ちいさい」で、最初の音が違う。"}, {"text": "書斎", "is_correct": false, "explanation": "「しょさい」で、最初の音が違う。"}, {"text": "薬剤", "is_correct": false, "explanation": "「やくざい」で、真ん中の音が違う。"}, {"text": "野心", "is_correct": false, "explanation": "「やしん」で、後半が違う。"}], "explanations": {"野菜": "正解の「やさい」。", "小さい": "「ちいさい」で、最初の音が違う。", "書斎": "「しょさい」で、最初の音が違う。", "薬剤": "「やくざい」で、真ん中の音が違う。", "野心": "「やしん」で、後半が違う。"}, "sentence_index": null, "correct_answer": "野菜"}, "level_3": {"options": [{"text": "野菜", "is_correct": true, "explanation": "スーパーで買う新鮮な食べ物として合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は買えない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題は新鮮でもなく買わない。"}, {"text": "空気", "is_correct": false, "explanation": "空気はスーパーで買わない。"}], "explanations": {"野菜": "スーパーで買う新鮮な食べ物として合う。", "天気": "天気は買えない。", "宿題": "宿題は新鮮でもなく買わない。", "空気": "空気はスーパーで買わない。"}, "sentence_index": 6, "correct_answer": "野菜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "野菜が空を飛んでいる。", "explanation": "野菜は飛ばない。"}, {"text": "私の野菜は小学校の先生です。", "explanation": "野菜は人ではない。"}, {"text": "野菜を聞きながら勉強した。", "explanation": "野菜は聞くものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
