INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42777, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向き合う", "is_correct": true, "explanation": "正解の「むきあう」。"}, {"text": "巻き合う", "is_correct": false, "explanation": "「まきあう」で、最初の音が違う。"}, {"text": "引き合う", "is_correct": false, "explanation": "「ひきあう」で、最初の音が違う。"}, {"text": "向かい合う", "is_correct": false, "explanation": "「むかいあう」で、音が多い。"}, {"text": "結び合う", "is_correct": false, "explanation": "「むすびあう」で、前半が違う。"}], "explanations": {"向き合う": "正解の「むきあう」。", "巻き合う": "「まきあう」で、最初の音が違う。", "引き合う": "「ひきあう」で、最初の音が違う。", "向かい合う": "「むかいあう」で、音が多い。", "結び合う": "「むすびあう」で、前半が違う。"}, "sentence_index": null, "correct_answer": "向き合う"}, "level_3": {"options": [{"text": "向き合っ", "is_correct": true, "explanation": "画用紙に正面から取り組む様子。"}, {"text": "落とし", "is_correct": false, "explanation": "「画用紙に落としている」は意味が通らない。"}, {"text": "走っ", "is_correct": false, "explanation": "「画用紙に走っている」は不自然。"}, {"text": "忘れ", "is_correct": false, "explanation": "「画用紙に忘れている」は誤り。"}], "explanations": {"向き合っ": "画用紙に正面から取り組む様子。", "落とし": "「画用紙に落としている」は意味が通らない。", "走っ": "「画用紙に走っている」は不自然。", "忘れ": "「画用紙に忘れている」は誤り。"}, "sentence_index": 0, "correct_answer": "向き合っ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このシャツは私によく向き合う。", "explanation": "服が似合う意味では「似合う」を使う。"}, {"text": "電車が駅に向き合って着いた。", "explanation": "到着の意味では使わない。"}, {"text": "彼はお茶を向き合って飲んだ。", "explanation": "「お茶を向き合う」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42777, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放課後の美術室で、私は白い画用紙を向き合っている。", "corrected_sentence": "放課後の美術室で、私は白い画用紙に向き合っている。", "error_description": "「向き合う」は「〜に／〜と向き合う」で、「を」は使わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "向き合う", "is_correct": true, "explanation": "名詞「本質」へつながる辞書形（連体）。"}, {"text": "向き合えば", "is_correct": false, "explanation": "条件形は名詞を修飾しない。"}, {"text": "向き合って", "is_correct": false, "explanation": "て形は名詞を修飾しない。"}, {"text": "向き合おう", "is_correct": false, "explanation": "意向形は名詞を修飾しない。"}], "correct_form": "向き合う", "base_form": "向き合う", "form_label": "辞書形（連体）", "sentence_index": 1, "explanations": {"向き合う": "名詞「本質」へつながる辞書形（連体）。", "向き合えば": "条件形は名詞を修飾しない。", "向き合って": "て形は名詞を修飾しない。", "向き合おう": "意向形は名詞を修飾しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42777, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「初学者が向き合う」で動作の主体を示す。"}, {"text": "を", "is_correct": false, "explanation": "「初学者を向き合う」は誤り。"}, {"text": "で", "is_correct": false, "explanation": "「初学者で」は意味が変わる。"}, {"text": "へ", "is_correct": false, "explanation": "「初学者へ」は方向になり不自然。"}], "correct_answer": "が", "explanations": {"が": "「初学者が向き合う」で動作の主体を示す。", "を": "「初学者を向き合う」は誤り。", "で": "「初学者で」は意味が変わる。", "へ": "「初学者へ」は方向になり不自然。"}, "error_tags": {"を": "wrong_case", "で": "means", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "目を背ける", "is_correct": true, "explanation": "問題から目をそらすことで、向き合うの反対。"}, {"text": "取り組む", "is_correct": false, "explanation": "真剣に向かうことで、近い意味。"}, {"text": "直面する", "is_correct": false, "explanation": "問題の前に立つことで、近い意味。"}, {"text": "見つめる", "is_correct": false, "explanation": "じっと見ることで、反対ではない。"}], "correct_answer": "目を背ける", "explanations": {"目を背ける": "問題から目をそらすことで、向き合うの反対。", "取り組む": "真剣に向かうことで、近い意味。", "直面する": "問題の前に立つことで、近い意味。", "見つめる": "じっと見ることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42777, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "向き合う", "is_correct": true, "explanation": "正解の「むきあう」。"}, {"text": "付き合う", "is_correct": false, "explanation": "「つきあう」で、最初の音が違う。"}, {"text": "向き直る", "is_correct": false, "explanation": "「むきなおる」で、後半が違う。"}, {"text": "抱き合う", "is_correct": false, "explanation": "「だきあう」で、最初の音が違う。"}, {"text": "聞き合う", "is_correct": false, "explanation": "「ききあう」で、最初の音が違う。"}], "explanations": {"向き合う": "正解の「むきあう」。", "付き合う": "「つきあう」で、最初の音が違う。", "向き直る": "「むきなおる」で、後半が違う。", "抱き合う": "「だきあう」で、最初の音が違う。", "聞き合う": "「ききあう」で、最初の音が違う。"}, "sentence_index": null, "correct_answer": "向き合う"}, "level_3": {"options": [{"text": "向き合う", "is_correct": true, "explanation": "子どもと真剣に関わる時間。"}, {"text": "忘れる", "is_correct": false, "explanation": "「子どもとしっかり忘れる」は不自然。"}, {"text": "買う", "is_correct": false, "explanation": "「子どもと買う時間」はしっかりと合わない。"}, {"text": "落ちる", "is_correct": false, "explanation": "「子どもと落ちる時間」は意味が通らない。"}], "explanations": {"向き合う": "子どもと真剣に関わる時間。", "忘れる": "「子どもとしっかり忘れる」は不自然。", "買う": "「子どもと買う時間」はしっかりと合わない。", "落ちる": "「子どもと落ちる時間」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "向き合う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この窓は南に向き合って開く。", "explanation": "建物の方角には「向いている」を使う。"}, {"text": "母はスープを向き合って作った。", "explanation": "「スープを向き合う」は誤り。"}, {"text": "ぼくは毎朝バスに向き合って学校へ行く。", "explanation": "乗り物には「乗る」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42777, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二人は将来に真剣に向き合いた。", "corrected_sentence": "二人は将来に真剣に向き合った。", "error_description": "「向き合う」の過去形は「向き合った」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "向き合っ", "is_correct": true, "explanation": "過去形「向き合った」の一部。"}, {"text": "向き合い", "is_correct": false, "explanation": "「向き合いた」という形はない。"}, {"text": "向き合わ", "is_correct": false, "explanation": "「向き合わた」という形はない。"}, {"text": "向き合う", "is_correct": false, "explanation": "「向き合うた」という形はない。"}], "correct_form": "向き合っ", "base_form": "向き合う", "form_label": "た形（向き合った）", "sentence_index": 7, "explanations": {"向き合っ": "過去形「向き合った」の一部。", "向き合い": "「向き合いた」という形はない。", "向き合わ": "「向き合わた」という形はない。", "向き合う": "「向き合うた」という形はない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (42777, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「将来に向き合う」で向き合う相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「将来を向き合う」とは言わない。"}, {"text": "が", "is_correct": false, "explanation": "「将来が向き合った」では主語になり誤り。"}, {"text": "で", "is_correct": false, "explanation": "「将来で」は場所・手段になり誤り。"}], "correct_answer": "に", "explanations": {"に": "「将来に向き合う」で向き合う相手を示す。", "を": "「将来を向き合う」とは言わない。", "が": "「将来が向き合った」では主語になり誤り。", "で": "「将来で」は場所・手段になり誤り。"}, "error_tags": {"を": "wrong_case", "が": "subject_object", "で": "means"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "逃げる", "is_correct": true, "explanation": "問題を避けることで、向き合うの反対。"}, {"text": "立ち向かう", "is_correct": false, "explanation": "困難に向かうことで、近い意味。"}, {"text": "取り組む", "is_correct": false, "explanation": "真剣に行うことで、近い意味。"}, {"text": "考える", "is_correct": false, "explanation": "反対の意味ではない。"}], "correct_answer": "逃げる", "explanations": {"逃げる": "問題を避けることで、向き合うの反対。", "立ち向かう": "困難に向かうことで、近い意味。", "取り組む": "真剣に行うことで、近い意味。", "考える": "反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52130, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摂理", "is_correct": true, "explanation": "正解の「せつり」。"}, {"text": "設置", "is_correct": false, "explanation": "「せっち」で、後半が違う。"}, {"text": "設立", "is_correct": false, "explanation": "「せつりつ」で、音が多い。"}, {"text": "切り", "is_correct": false, "explanation": "「きり」で、最初の音がない。"}, {"text": "説明", "is_correct": false, "explanation": "「せつめい」で、後半が違う。"}], "explanations": {"摂理": "正解の「せつり」。", "設置": "「せっち」で、後半が違う。", "設立": "「せつりつ」で、音が多い。", "切り": "「きり」で、最初の音がない。", "説明": "「せつめい」で、後半が違う。"}, "sentence_index": null, "correct_answer": "摂理"}, "level_3": {"options": [{"text": "摂理", "is_correct": true, "explanation": "宇宙の秩序・法則を表す。"}, {"text": "切符", "is_correct": false, "explanation": "「宇宙の切符を体現」は意味が通らない。"}, {"text": "机", "is_correct": false, "explanation": "机は宇宙を体現しない。"}, {"text": "住所", "is_correct": false, "explanation": "「宇宙の住所そのもの」は不自然。"}], "explanations": {"摂理": "宇宙の秩序・法則を表す。", "切符": "「宇宙の切符を体現」は意味が通らない。", "机": "机は宇宙を体現しない。", "住所": "「宇宙の住所そのもの」は不自然。"}, "sentence_index": 0, "correct_answer": "摂理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "摂理を一杯ください。", "explanation": "摂理は飲み物ではない。"}, {"text": "このかばんは摂理でできている。", "explanation": "摂理は材料ではない。"}, {"text": "妹は摂理を着て出かけた。", "explanation": "摂理は服ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52130, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その姿は、まさに宇宙に摂理そのものを体現しているかのようであった。", "corrected_sentence": "その姿は、まさに宇宙の摂理そのものを体現しているかのようであった。", "error_description": "「宇宙の摂理」は「の」でつなぐ。「宇宙に摂理」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52130, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「自然の摂理と人間の叡智」で二つを並べる。"}, {"text": "を", "is_correct": false, "explanation": "「摂理を人間の叡智」は誤り。"}, {"text": "が", "is_correct": false, "explanation": "「摂理が人間の叡智が」は誤り。"}, {"text": "で", "is_correct": false, "explanation": "「摂理で」は手段になる。"}], "correct_answer": "と", "explanations": {"と": "「自然の摂理と人間の叡智」で二つを並べる。", "を": "「摂理を人間の叡智」は誤り。", "が": "「摂理が人間の叡智が」は誤り。", "で": "「摂理で」は手段になる。"}, "error_tags": {"を": "wrong_case", "が": "subject_object", "で": "means"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52130, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "摂理", "is_correct": true, "explanation": "正解の「せつり」。"}, {"text": "ゼリー", "is_correct": false, "explanation": "「ぜりー」で、音が違う。"}, {"text": "接吻", "is_correct": false, "explanation": "「せっぷん」で、後半が違う。"}, {"text": "節約", "is_correct": false, "explanation": "「せつやく」で、後半が違う。"}, {"text": "瀬戸", "is_correct": false, "explanation": "「せと」で、音が違う。"}], "explanations": {"摂理": "正解の「せつり」。", "ゼリー": "「ぜりー」で、音が違う。", "接吻": "「せっぷん」で、後半が違う。", "節約": "「せつやく」で、後半が違う。", "瀬戸": "「せと」で、音が違う。"}, "sentence_index": null, "correct_answer": "摂理"}, "level_3": {"options": [{"text": "摂理", "is_correct": true, "explanation": "季節がめぐるのは自然の法則の一つ。"}, {"text": "料理", "is_correct": false, "explanation": "「季節がめぐるのも料理の一つ」は意味が通らない。"}, {"text": "趣味", "is_correct": false, "explanation": "季節の巡りは趣味ではない。"}, {"text": "建物", "is_correct": false, "explanation": "季節がめぐることは建物ではない。"}], "explanations": {"摂理": "季節がめぐるのは自然の法則の一つ。", "料理": "「季節がめぐるのも料理の一つ」は意味が通らない。", "趣味": "季節の巡りは趣味ではない。", "建物": "季節がめぐることは建物ではない。"}, "sentence_index": 6, "correct_answer": "摂理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前で摂理を買って食べた。", "explanation": "摂理は食べ物ではない。"}, {"text": "摂理で公園まで走った。", "explanation": "摂理は乗り物ではない。"}, {"text": "ぼくの摂理は三年生です。", "explanation": "摂理は人ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52130, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この本は自然の摂理について書くている。", "corrected_sentence": "この本は自然の摂理について書いている。", "error_description": "「書く」のて形は「書いて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52130, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「摂理を見た」で見る対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「摂理に見た」は誤り。"}, {"text": "が", "is_correct": false, "explanation": "「摂理が見た」では主語になる。"}, {"text": "と", "is_correct": false, "explanation": "「摂理と見た」は意味が変わる。"}], "correct_answer": "を", "explanations": {"を": "「摂理を見た」で見る対象を示す。", "に": "「摂理に見た」は誤り。", "が": "「摂理が見た」では主語になる。", "と": "「摂理と見た」は意味が変わる。"}, "error_tags": {"に": "wrong_case", "が": "subject_object", "と": "wrong_case"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52074, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正に", "is_correct": true, "explanation": "正解。「まさに」と読む。"}, {"text": "まさか", "is_correct": false, "explanation": "「まさか」。最後のモーラ「に」が「か」に変わる一モーラ差。"}, {"text": "摩擦", "is_correct": false, "explanation": "「まさつ」。最後のモーラ「に」が「つ」に変わる一モーラ差。"}, {"text": "勝る", "is_correct": false, "explanation": "「まさる」。最後のモーラ「に」が「る」に変わる一モーラ差。"}], "explanations": {"正に": "正解。「まさに」と読む。", "まさか": "「まさか」。最後のモーラ「に」が「か」に変わる一モーラ差。", "摩擦": "「まさつ」。最後のモーラ「に」が「つ」に変わる一モーラ差。", "勝る": "「まさる」。最後のモーラ「に」が「る」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "正に"}, "level_3": {"options": [{"text": "まさに", "is_correct": true, "explanation": "正解。「まさに」は後の「そのもの」と呼応して強調する。"}, {"text": "やっと", "is_correct": false, "explanation": "意味：長い時間の後に実現する意で、強調にならない。"}, {"text": "たまに", "is_correct": false, "explanation": "意味：頻度を表し、この文の比喩の強調に合わない。"}, {"text": "少しも", "is_correct": false, "explanation": "連語：否定と呼応する語で、肯定文には入らない。"}], "explanations": {"まさに": "正解。「まさに」は後の「そのもの」と呼応して強調する。", "やっと": "意味：長い時間の後に実現する意で、強調にならない。", "たまに": "意味：頻度を表し、この文の比喩の強調に合わない。", "少しも": "連語：否定と呼応する語で、肯定文には入らない。"}, "sentence_index": 0, "correct_answer": "まさに"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まさに彼は来なかったかもしれない。", "explanation": "推量・可能性の表現とは合わない。まさには事実を断定的に強める。"}, {"text": "まさに彼が来るかどうか分からない。", "explanation": "不確かさを表す文で、断定を強めるまさにと合わない。"}, {"text": "まさに、明日は雨が降るだろうか。", "explanation": "疑問文と組み合わせると強調の意味が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52074, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "これはまさにに私がほしかった本だ。", "corrected_sentence": "これはまさに私がほしかった本だ。", "error_description": "「まさに」は副詞で、さらに「に」を付けない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
