INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52074, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正に", "is_correct": true, "explanation": "正解。読みは「まさに」。"}, {"text": "真砂", "is_correct": false, "explanation": "「まさご」：最後の音が違う。"}, {"text": "眼", "is_correct": false, "explanation": "「まなこ」：後半が違う。"}, {"text": "正夢", "is_correct": false, "explanation": "「まさゆめ」：後半が違う。"}], "explanations": {"正に": "正解。読みは「まさに」。", "真砂": "「まさご」：最後の音が違う。", "眼": "「まなこ」：後半が違う。", "正夢": "「まさゆめ」：後半が違う。"}, "sentence_index": null, "correct_answer": "正に"}, "level_3": {"options": [{"text": "まさに", "is_correct": true, "explanation": "正解。「まさに天才」で、その評価が疑いなく正しいと強める。"}, {"text": "決して", "is_correct": false, "explanation": "連語：否定と呼応するため「言える」と合わない。"}, {"text": "たぶん", "is_correct": false, "explanation": "意味：推量であり、強い断定の強調にならない。"}, {"text": "ときどき", "is_correct": false, "explanation": "意味：頻度の副詞で、天才という評価に合わない。"}], "explanations": {"まさに": "正解。「まさに天才」で、その評価が疑いなく正しいと強める。", "決して": "連語：否定と呼応するため「言える」と合わない。", "たぶん": "意味：推量であり、強い断定の強調にならない。", "ときどき": "意味：頻度の副詞で、天才という評価に合わない。"}, "sentence_index": 6, "correct_answer": "まさに"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末はまさに家で寝ている。", "explanation": "まさには「たいてい」のような頻度の意味では使わない。"}, {"text": "まさにか、試合に負けるとは思わなかった。", "explanation": "意外さを表すのは「まさか」で、まさにではない。"}, {"text": "試合はまさに始まるかどうか知らない。", "explanation": "不確かさを表す文で、強調のまさにと矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52074, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女はまさにな天才と言える。", "corrected_sentence": "彼女はまさに天才と言える。", "error_description": "「まさに」は副詞なので「な」を付けて名詞を修飾しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
