INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51764, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "変数", "is_correct": true, "explanation": "正解。「へんすう」と読む。"}, {"text": "関数", "is_correct": false, "explanation": "「かんすう」：一拍目「へ」→「か」の一モーラ差。"}, {"text": "点数", "is_correct": false, "explanation": "「てんすう」：一拍目「へ」→「て」の一モーラ差。"}, {"text": "変装", "is_correct": false, "explanation": "「へんそう」：三拍目「す」→「そ」の一モーラ差。"}, {"text": "編集", "is_correct": false, "explanation": "「へんしゅう」：三拍目「す」→「しゅ」の一モーラ差。"}], "explanations": {"変数": "正解。「へんすう」と読む。", "関数": "「かんすう」：一拍目「へ」→「か」の一モーラ差。", "点数": "「てんすう」：一拍目「へ」→「て」の一モーラ差。", "変装": "「へんそう」：三拍目「す」→「そ」の一モーラ差。", "編集": "「へんしゅう」：三拍目「す」→「しゅ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "変数"}, "level_3": {"options": [{"text": "変数", "is_correct": true, "explanation": "正解。データを入力する値として扱うので「変数」。"}, {"text": "景色", "is_correct": false, "explanation": "意味：風景のことで、アルゴリズムの入力値にならない。"}, {"text": "感想", "is_correct": false, "explanation": "意味：気持ちの表明で、データとして入力する値ではない。"}, {"text": "文句", "is_correct": false, "explanation": "意味：不満の言葉で、アルゴリズムに入力するデータではない。"}], "explanations": {"変数": "正解。データを入力する値として扱うので「変数」。", "景色": "意味：風景のことで、アルゴリズムの入力値にならない。", "感想": "意味：気持ちの表明で、データとして入力する値ではない。", "文句": "意味：不満の言葉で、アルゴリズムに入力するデータではない。"}, "sentence_index": 0, "correct_answer": "変数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "プログラムで新しい変数を一匹作った。", "explanation": "助数詞の誤り：変数を「匹」で数えない。"}, {"text": "プログラムが新しい変数で作った。", "explanation": "助詞の混同：目的語は「を」で示す。"}, {"text": "プログラムで変数を新しい作った。", "explanation": "語順の誤り：連体修飾の「新しい」が名詞の前にない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51764, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "プログラムで新しい変数を焼いた。", "corrected_sentence": "プログラムで新しい変数を作った。", "error_description": "「変数」は値が変わる記号で、パンのように「焼く」ものではない。「作る」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51764, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。他動詞「制御する」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「制御する」の目的語を主格で示すことはできない。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、制御の対象を示さない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、この位置では非文。"}], "correct_answer": "を", "explanations": {"を": "正解。他動詞「制御する」の目的語を示す。", "が": "「制御する」の目的語を主格で示すことはできない。", "に": "着点を表し、制御の対象を示さない。", "で": "手段・場所を表し、この位置では非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "定数", "is_correct": true, "explanation": "正解。値が変わらない記号で、変数の対義語。"}, {"text": "関数", "is_correct": false, "explanation": "入力から出力を決める規則で、対義関係ではない。"}, {"text": "記号", "is_correct": false, "explanation": "変数を含む上位の語で、対義ではない。"}, {"text": "数式", "is_correct": false, "explanation": "変数を使う式そのもので、対義ではない。"}], "correct_answer": "定数", "explanations": {"定数": "正解。値が変わらない記号で、変数の対義語。", "関数": "入力から出力を決める規則で、対義関係ではない。", "記号": "変数を含む上位の語で、対義ではない。", "数式": "変数を使う式そのもので、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51764, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "変数", "is_correct": true, "explanation": "正解。読みは「へんすう」。"}, {"text": "変装", "is_correct": false, "explanation": "「へんそう」：「す」と「そ」の一モーラ差。"}, {"text": "点数", "is_correct": false, "explanation": "「てんすう」：「へ」と「て」の一モーラ差。"}, {"text": "関数", "is_correct": false, "explanation": "「かんすう」：「へ」と「か」の一モーラ差。"}], "explanations": {"変数": "正解。読みは「へんすう」。", "変装": "「へんそう」：「す」と「そ」の一モーラ差。", "点数": "「てんすう」：「へ」と「て」の一モーラ差。", "関数": "「かんすう」：「へ」と「か」の一モーラ差。"}, "sentence_index": null, "correct_answer": "変数"}, "level_3": {"options": [{"text": "変数", "is_correct": true, "explanation": "正解。先生が意味を説明する数学の用語として「変数」が入る。"}, {"text": "机", "is_correct": false, "explanation": "意味：教室の家具で、授業で意味を説明する用語ではない。"}, {"text": "靴", "is_correct": false, "explanation": "意味：履物で、授業で意味を説明する用語ではない。"}, {"text": "傘", "is_correct": false, "explanation": "意味：雨具で、授業で意味を説明する用語ではない。"}], "explanations": {"変数": "正解。先生が意味を説明する数学の用語として「変数」が入る。", "机": "意味：教室の家具で、授業で意味を説明する用語ではない。", "靴": "意味：履物で、授業で意味を説明する用語ではない。", "傘": "意味：雨具で、授業で意味を説明する用語ではない。"}, "sentence_index": 6, "correct_answer": "変数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの変数を一冊比べてみよう。", "explanation": "助数詞の誤り：変数を「冊」で数えない。"}, {"text": "二つの変数が比べてみよう。", "explanation": "助詞の混同：「比べる」の目的語は「を」。"}, {"text": "二つの比べて変数をみよう。", "explanation": "語順の誤り：目的語「変数を」が「比べて」と「みよう」の間に割り込んでいる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51764, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "変数がおいしいと計算が難しい。", "corrected_sentence": "変数が多いと計算が難しい。", "error_description": "「変数」は値が変わる記号で、味の「おいしい」とは結びつかない。「多い」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51764, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「多い」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "形容詞「多い」は目的語をとらない。"}, {"text": "に", "is_correct": false, "explanation": "対象を表し、主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、この位置では非文。"}], "correct_answer": "が", "explanations": {"が": "正解。「多い」の主語を示す。", "を": "形容詞「多い」は目的語をとらない。", "に": "対象を表し、主語にならない。", "で": "手段を表し、この位置では非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "定数", "is_correct": true, "explanation": "正解。値が一定の記号で、変数と対になる。"}, {"text": "数字", "is_correct": false, "explanation": "数を書き表す文字で、対義ではない。"}, {"text": "答え", "is_correct": false, "explanation": "計算の結果で、対義関係にない。"}, {"text": "記号", "is_correct": false, "explanation": "変数を含む広い語で、対義ではない。"}], "correct_answer": "定数", "explanations": {"定数": "正解。値が一定の記号で、変数と対になる。", "数字": "数を書き表す文字で、対義ではない。", "答え": "計算の結果で、対義関係にない。", "記号": "変数を含む広い語で、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51516, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "黙々", "is_correct": true, "explanation": "正解。「もくもく」と読む。"}, {"text": "目録", "is_correct": false, "explanation": "「もくろく」：三拍目「も」→「ろ」の一モーラ差。"}, {"text": "黙読", "is_correct": false, "explanation": "「もくどく」：三拍目「も」→「ど」の一モーラ差。"}, {"text": "沐浴", "is_correct": false, "explanation": "「もくよく」：三拍目「も」→「よ」の一モーラ差。"}], "explanations": {"黙々": "正解。「もくもく」と読む。", "目録": "「もくろく」：三拍目「も」→「ろ」の一モーラ差。", "黙読": "「もくどく」：三拍目「も」→「ど」の一モーラ差。", "沐浴": "「もくよく」：三拍目「も」→「よ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "黙々"}, "level_3": {"options": [{"text": "黙々", "is_correct": true, "explanation": "正解。静かにひたすら打ち込むさまを表す。"}, {"text": "わいわい", "is_correct": false, "explanation": "意味：にぎやかに騒ぐさまで、静かな情景に合わない。"}, {"text": "ぺらぺら", "is_correct": false, "explanation": "意味：よくしゃべるさまで、文脈と矛盾する。"}, {"text": "いらいら", "is_correct": false, "explanation": "意味：落ち着かない気持ちで、一体化の情景に合わない。"}], "explanations": {"黙々": "正解。静かにひたすら打ち込むさまを表す。", "わいわい": "意味：にぎやかに騒ぐさまで、静かな情景に合わない。", "ぺらぺら": "意味：よくしゃべるさまで、文脈と矛盾する。", "いらいら": "意味：落ち着かない気持ちで、一体化の情景に合わない。"}, "sentence_index": 0, "correct_answer": "黙々"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は黙々と大声でしゃべっている。", "explanation": "意味の矛盾：黙ってする「黙々と」と「大声でしゃべる」が両立しない。"}, {"text": "兄は黙々と宿題をしていた明日。", "explanation": "テンスの誤り：過去形と「明日」が合わない。"}, {"text": "兄が黙々は宿題をしている。", "explanation": "助詞の誤り：副詞の後に「は」を置き構造が崩れる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
