INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51516, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "黙々", "is_correct": true, "explanation": "正解。読みは「もくもく」。"}, {"text": "沐浴", "is_correct": false, "explanation": "「もくよく」：「も」と「よ」の一モーラ差。"}, {"text": "目録", "is_correct": false, "explanation": "「もくろく」：「も」と「ろ」の一モーラ差。"}, {"text": "黙読", "is_correct": false, "explanation": "「もくどく」：「も」と「ど」の一モーラ差。"}], "explanations": {"黙々": "正解。読みは「もくもく」。", "沐浴": "「もくよく」：「も」と「よ」の一モーラ差。", "目録": "「もくろく」：「も」と「ろ」の一モーラ差。", "黙読": "「もくどく」：「も」と「ど」の一モーラ差。"}, "sentence_index": null, "correct_answer": "黙々"}, "level_3": {"options": [{"text": "黙々", "is_correct": true, "explanation": "正解。話さずにただ食べ続けるさま。"}, {"text": "にこにこ", "is_correct": false, "explanation": "意味：笑顔のさまで、ひたすら集中する意味ではない。"}, {"text": "がやがや", "is_correct": false, "explanation": "意味：騒がしいさまで、父一人の食事に合わない。"}, {"text": "ぶつぶつ", "is_correct": false, "explanation": "意味：小声で不平を言うさまで、黙る意味と逆。"}], "explanations": {"黙々": "正解。話さずにただ食べ続けるさま。", "にこにこ": "意味：笑顔のさまで、ひたすら集中する意味ではない。", "がやがや": "意味：騒がしいさまで、父一人の食事に合わない。", "ぶつぶつ": "意味：小声で不平を言うさまで、黙る意味と逆。"}, "sentence_index": 6, "correct_answer": "黙々"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黙々と大声で話すことが大切だ。", "explanation": "黙っての意味と「大声で話す」が矛盾する。"}, {"text": "黙々と練習したことが明日大切だった。", "explanation": "テンスの誤り：「明日」と過去形「だった」が合わない。"}, {"text": "黙々を練習することが大切だ。", "explanation": "助詞の誤り：副詞に「を」はつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "みんな黙々とおしゃべりを続けた。", "corrected_sentence": "みんな黙々と掃除を続けた。", "error_description": "「黙々と」は黙って作業するさまで、「おしゃべり」とは両立しない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
