INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52108, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渇望", "is_correct": true, "explanation": "正解。「かつぼう」と読む。"}, {"text": "失望", "is_correct": false, "explanation": "「しつぼう」：一拍目「か」→「し」の一モーラ差。"}, {"text": "絶望", "is_correct": false, "explanation": "「ぜつぼう」：一拍目「か」→「ぜ」の一モーラ差。"}, {"text": "活動", "is_correct": false, "explanation": "「かつどう」：三拍目「ぼ」→「ど」の一モーラ差。"}, {"text": "活用", "is_correct": false, "explanation": "「かつよう」：三拍目「ぼ」→「よ」の一モーラ差。"}], "explanations": {"渇望": "正解。「かつぼう」と読む。", "失望": "「しつぼう」：一拍目「か」→「し」の一モーラ差。", "絶望": "「ぜつぼう」：一拍目「か」→「ぜ」の一モーラ差。", "活動": "「かつどう」：三拍目「ぼ」→「ど」の一モーラ差。", "活用": "「かつよう」：三拍目「ぼ」→「よ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "渇望"}, "level_3": {"options": [{"text": "渇望", "is_correct": true, "explanation": "正解。手に入らないことで強く欲しくなる気持ち。"}, {"text": "満足", "is_correct": false, "explanation": "意味：もう足りている状態で、拒絶で生まれる気持ちと逆。"}, {"text": "退屈", "is_correct": false, "explanation": "意味：興味がない状態で、「強烈な」と合わない。"}, {"text": "軽蔑", "is_correct": false, "explanation": "意味：見下す気持ちで、欲しがる気持ちではない。"}], "explanations": {"渇望": "正解。手に入らないことで強く欲しくなる気持ち。", "満足": "意味：もう足りている状態で、拒絶で生まれる気持ちと逆。", "退屈": "意味：興味がない状態で、「強烈な」と合わない。", "軽蔑": "意味：見下す気持ちで、欲しがる気持ちではない。"}, "sentence_index": 0, "correct_answer": "渇望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人々は平和を一個渇望している。", "explanation": "助数詞の誤り：渇望に「一個」はつかない。"}, {"text": "人々が平和に渇望している。", "explanation": "助詞の混同：渇望する対象は「を」で示す。"}, {"text": "人々は平和をいる渇望して。", "explanation": "語順の誤り：補助動詞「いる」が「渇望して」の前に来ている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52108, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ただ生命の根源的な渇望を食べるのみだ。", "corrected_sentence": "ただ生命の根源的な渇望があるのみだ。", "error_description": "「渇望」は強く欲しがる気持ちで、「食べる」ものではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52108, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「渇望」と「受容」を並べる。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、後に動詞がなく非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、並列の意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、この位置では不自然。"}], "correct_answer": "と", "explanations": {"と": "正解。「渇望」と「受容」を並べる。", "を": "目的語標示で、後に動詞がなく非文。", "に": "着点を表し、並列の意味にならない。", "で": "手段を表し、この位置では不自然。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52108, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "渇望", "is_correct": true, "explanation": "正解。読みは「かつぼう」。"}, {"text": "活用", "is_correct": false, "explanation": "「かつよう」：「ぼ」と「よ」の一モーラ差。"}, {"text": "絶望", "is_correct": false, "explanation": "「ぜつぼう」：「か」と「ぜ」の一モーラ差。"}, {"text": "失望", "is_correct": false, "explanation": "「しつぼう」：「か」と「し」の一モーラ差。"}], "explanations": {"渇望": "正解。読みは「かつぼう」。", "活用": "「かつよう」：「ぼ」と「よ」の一モーラ差。", "絶望": "「ぜつぼう」：「か」と「ぜ」の一モーラ差。", "失望": "「しつぼう」：「か」と「し」の一モーラ差。"}, "sentence_index": null, "correct_answer": "渇望"}, "level_3": {"options": [{"text": "渇望", "is_correct": true, "explanation": "正解。「していた」と続き、強く望んでいた夢を表す。"}, {"text": "後悔", "is_correct": false, "explanation": "意味：後で悔やむことで、夢がかなう文と合わない。"}, {"text": "忘却", "is_correct": false, "explanation": "意味：忘れることで、かなった夢と矛盾する。"}, {"text": "拒否", "is_correct": false, "explanation": "意味：断ることで、望む意味と逆。"}], "explanations": {"渇望": "正解。「していた」と続き、強く望んでいた夢を表す。", "後悔": "意味：後で悔やむことで、夢がかなう文と合わない。", "忘却": "意味：忘れることで、かなった夢と矛盾する。", "拒否": "意味：断ることで、望む意味と逆。"}, "sentence_index": 6, "correct_answer": "渇望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の目には渇望が三冊あった。", "explanation": "助数詞の誤り：渇望を「冊」で数えない。"}, {"text": "彼の目を渇望の色があった。", "explanation": "助詞の混同：存在の場所は「に」で示す。"}, {"text": "色があった彼の目には渇望の。", "explanation": "語順の誤り：連体修飾が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52108, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その国は変化を渇望で切っていた。", "corrected_sentence": "その国は変化を渇望していた。", "error_description": "「渇望」は気持ちであり、物を切る道具ではない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52108, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「渇望する」の対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格で、「変化」が渇望する主体になり文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、この動詞と合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「渇望する」の対象を示す。", "が": "主格で、「変化」が渇望する主体になり文が成立しない。", "で": "手段・場所を表し、非文になる。", "へ": "方向を表し、この動詞と合わない。"}, "error_tags": {"が": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51590, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "操作", "is_correct": true, "explanation": "正解。「そうさ」と読む。"}, {"text": "交差", "is_correct": false, "explanation": "「こうさ」：一拍目「そ」→「こ」の一モーラ差。"}, {"text": "動作", "is_correct": false, "explanation": "「どうさ」：一拍目「そ」→「ど」の一モーラ差。"}, {"text": "装置", "is_correct": false, "explanation": "「そうち」：三拍目「さ」→「ち」の一モーラ差。"}], "explanations": {"操作": "正解。「そうさ」と読む。", "交差": "「こうさ」：一拍目「そ」→「こ」の一モーラ差。", "動作": "「どうさ」：一拍目「そ」→「ど」の一モーラ差。", "装置": "「そうち」：三拍目「さ」→「ち」の一モーラ差。"}, "sentence_index": null, "correct_answer": "操作"}, "level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "正解。機械を動かす意味で「操作する」が入る。"}, {"text": "尊敬", "is_correct": false, "explanation": "意味：人を敬う意味で、機械を目的語にとらない。"}, {"text": "想像", "is_correct": false, "explanation": "意味：心に思い描くことで、専門知識の対象として不自然。"}, {"text": "説得", "is_correct": false, "explanation": "項構造：人を相手にとる語で、機械には使えない。"}], "explanations": {"操作": "正解。機械を動かす意味で「操作する」が入る。", "尊敬": "意味：人を敬う意味で、機械を目的語にとらない。", "想像": "意味：心に思い描くことで、専門知識の対象として不自然。", "説得": "項構造：人を相手にとる語で、機械には使えない。"}, "sentence_index": 0, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父がクレーンに操作している。", "explanation": "助詞の混同：操作の対象は「を」で示す。"}, {"text": "父がクレーンを一冊操作している。", "explanation": "助数詞の誤り：操作に「冊」はつかない。"}, {"text": "父が明日クレーンを操作した。", "explanation": "テンスの誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51590, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "機械を操作する気持ちを持つ人材が必要だ。", "corrected_sentence": "機械を操作する専門知識を持つ人材が必要だ。", "error_description": "「操作」には技術や知識が伴うのが自然で、「気持ち」とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '726fcf96-a96f-41d2-b559-6296334d4f4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
