INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36381, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "一度起こった変化が、再び元の状態に戻ることが可能な性質", "primary_collocate": null, "pronunciation": "かぎゃく", "ipa": "kaɡʲakɯ", "syllable_count": 3, "sentences": [{"text": "金属イオンとの錯体形成を通じて、色は初めてその真の輝きを帯び、生地へと不可逆的に定着するのだ。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "我々は、この不可逆的な変化の連鎖をどう受け止めるべきか、文明の存続をかけて抜本的な転換を迫られているのである。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "氷が水になる変化は可逆だ。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "こおり みず へんか かぎゃく", "sentence_source": "generated"}, {"text": "この反応は可逆な反応です。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "はんのう かぎゃく はんのう", "sentence_source": "generated"}, {"text": "可逆の変化なら元に戻せる。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "かぎゃく へんか もと もど", "sentence_source": "generated"}, {"text": "先生は可逆的な変化を説明した。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "せんせい かぎゃくてき へんか せつめい", "sentence_source": "generated"}, {"text": "卵を焼くのは可逆ではない。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "たまご や かぎゃく", "sentence_source": "generated"}, {"text": "この圧縮方式は可逆だそうだ。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "あっしゅく ほうしき かぎゃく", "sentence_source": "generated"}, {"text": "可逆かどうかを実験で調べた。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "かぎゃく じっけん しら", "sentence_source": "generated"}, {"text": "溶ける変化は可逆と言える。", "target_word": "可逆", "complexity_tier": "T3", "furigana": "と へんか かぎゃく い", "sentence_source": "generated"}], "morphological_forms": [{"form": "可逆的", "label": "派生"}, {"form": "不可逆", "label": "派生"}, {"form": "可逆性", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 元の状態に戻せる性質", "collocate_grounding": {"