INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39071, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "糸や布の原料となる、細くて長い物質のことです。植物や動物、石油などから作られます。", "primary_collocate": null, "pronunciation": "せんい", "ipa": "seɴi", "syllable_count": 3, "sentences": [{"text": "古来、人類は植物の生命力を繊維に宿す術を磨き上げてきた。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "綿は植物からとれる繊維だ。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "わた しょくぶつ せんい", "sentence_source": "generated"}, {"text": "この服は丈夫な繊維でできている。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ふく じょうぶ せんい", "sentence_source": "generated"}, {"text": "羊の毛も繊維の一つです。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ひつじ け せんい ひと", "sentence_source": "generated"}, {"text": "繊維を集めて糸を作る。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "せんい あつ いと つく", "sentence_source": "generated"}, {"text": "麻の繊維はとても強い。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "あさ せんい つよ", "sentence_source": "generated"}, {"text": "石油から新しい繊維が作られた。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "せきゆ あたら せんい つく", "sentence_source": "generated"}, {"text": "布の繊維がほつれている。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ぬの せんい", "sentence_source": "generated"}, {"text": "祖父は繊維の工場で働いた。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "そふ せんい こうじょう はたら", "sentence_source": "generated"}, {"text": "細い繊維を顕微鏡で見た。", "target_word": "繊維", "complexity_tier": "T3", "furigana": "ほそ せんい けんびきょう み", "sentence_source": "generated"}], "morphological_forms": [{"form": "化学繊維", "label": "派生"}, {"form": "食物繊維", "label": "派生"}, {"form": "本", "label": "助数詞"}], "register": "formal", "sense_fingerprint": "名詞 | 糸や布になる細長い物質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44c8d91d-7342-44af-a7dd-38575012f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36773, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "心の中や物事の奥に隠して、外からはっきり見えないようにする。", "primary_collocate": null, "pronunciation": "ひめる", "ipa": "çimeɾɯ", "syllable_count": 3, "sentences": [{"text": "まず、季節の移ろいと共に採取された植物は、熱と水によってその奥底に秘められた色素を解放される。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "現代の商業的なベーキングにおいては往々にして画一的な効率性が優先されがちであるが、彼が真に渇望するのは、サワードウ特有の繊細かつ複雑な酸味と、穀物本来が秘める深い旨みの極致である。", "target_word": "秘める", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "彼は強い思いを胸に秘めている。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "かれ つよ おも むね ひ", "sentence_source": "generated"}, {"text": "その子は大きな力を秘めている。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "こ おお ちから ひ", "sentence_source": "generated"}, {"text": "秘めた夢を友だちに話した。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "ひ ゆめ とも はな", "sentence_source": "generated"}, {"text": "この石は不思議な力を秘める。", "target_word": "秘める", "complexity_tier": "T3", "furigana": "いし ふしぎ ちから ひ", "sentence_source": "generated"}, {"text": "怒りを心に秘めて笑った。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "いか こころ ひ わら", "sentence_source": "generated"}, {"text": "秘めた気持ちは言えなかった。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "ひ きも い", "sentence_source": "generated"}, {"text": "彼女は才能を秘めた選手だ。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "かのじょ さいのう ひ せんしゅ", "sentence_source": "generated"}, {"text": "町は長い歴史を秘めている。", "target_word": "秘め", "complexity_tier": "T3", "furigana": "まち なが れきし ひ", "sentence_source": "generated"}], "morphological_forms": [{"form": "秘めた", "label": "活用"}, {"form": "秘めて", "label": "活用"}, {"form": "秘められる", "label": "活用"}, {"form": "秘めない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 内に隠して外に見せない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44c8d91d-7342-44af-a7dd-38575012f72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36019, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "程度が普通を超えていることを表す。また、動詞の連用形に付いて、その動作をしすぎるという意味を加える。", "primary_collocate": null, "pronunciation": "すぎる", "ipa": "sɯɡiɾɯ", "syllable_count": 3, "sentences": [{"text": "単なるエネルギー源に過ぎなかった穀物が、生命の維持と豊かな食体験を同時に叶える食文化へと昇華される。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "昨日はご飯を食べ過ぎた。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "きのう はん た す", "sentence_source": "generated"}, {"text": "この服は大き過ぎる。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "ふく おお す", "sentence_source": "generated"}, {"text": "ゲームのやり過ぎはよくない。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "す", "sentence_source": "generated"}, {"text": "彼は少し働き過ぎている。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "かれ すこ はたら す", "sentence_source": "generated"}, {"text": "このカレーは辛過ぎて食べられない。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "から す た", "sentence_source": "generated"}, {"text": "飲み過ぎて頭が痛い。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "の す あたま いた", "sentence_source": "generated"}, {"text": "その問題は難し過ぎた。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "もんだい むずか す", "sentence_source": "generated"}, {"text": "考え過ぎないほうがいい。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "かんが す", "sentence_source": "generated"}, {"text": "塩の入れ過ぎに気をつけて。", "target_word": "過ぎ", "complexity_tier": "T3", "furigana": "しお い す き", "sentence_source": "generated"}], "morphological_forms": [{"form": "過ぎた", "label": "活用"}, {"form": "過ぎて", "label": "活用"}, {"form": "過ぎない", "label": "活用"}, {"form": "過ぎ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 程度が普通を超えている", "collocate_grounding": {"status": "no_source", "reason": "no 