INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36553, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物体の温度が高い状態。また、その度合い。", "primary_collocate": null, "pronunciation": "ねつ", "ipa": "netsɯ", "syllable_count": 2, "sentences": [{"text": "まず、季節の移ろいと共に採取された植物は、熱と水によってその奥底に秘められた色素を解放される。", "target_word": "熱", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "高温のオーブンへ投入された瞬間、生地は熱エネルギーによって急激に膨張します。", "target_word": "熱", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "太陽の熱で氷がとけた。", "target_word": "熱", "complexity_tier": "T3", "furigana": "たいよう ねつ こおり", "sentence_source": "generated"}, {"text": "鉄は熱をよく伝える。", "target_word": "熱", "complexity_tier": "T3", "furigana": "てつ ねつ つた", "sentence_source": "generated"}, {"text": "なべに熱が残っている。", "target_word": "熱", "complexity_tier": "T3", "furigana": "ねつ のこ", "sentence_source": "generated"}, {"text": "熱を加えると水は湯になる。", "target_word": "熱", "complexity_tier": "T3", "furigana": "ねつ くわ みず ゆ", "sentence_source": "generated"}, {"text": "この壁は熱を通しにくい。", "target_word": "熱", "complexity_tier": "T3", "furigana": "かべ ねつ とお", "sentence_source": "generated"}, {"text": "ストーブの熱で部屋が暖かい。", "target_word": "熱", "complexity_tier": "T3", "furigana": "ねつ へや あたた", "sentence_source": "generated"}, {"text": "熱が逃げないようにふたをした。", "target_word": "熱", "complexity_tier": "T3", "furigana": "ねつ に", "sentence_source": "generated"}, {"text": "エンジンから強い熱が出る。", "target_word": "熱", "complexity_tier": "T3", "furigana": "つよ ねつ で", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱い", "label": "派生"}, {"form": "熱する", "label": "派生"}, {"form": "熱湯", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物体の温度が高い状態や度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:f