INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52366, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "結晶", "is_correct": true, "explanation": "正解。読みは「けっしょう」。"}, {"text": "結構", "is_correct": false, "explanation": "読みは「けっこう」。「しょ」が「こ」に変わる一モーラ差。"}, {"text": "決闘", "is_correct": false, "explanation": "読みは「けっとう」。「しょ」が「と」に変わる一モーラ差。"}, {"text": "血色", "is_correct": false, "explanation": "読みは「けっしょく」。最後の「う」が「く」に変わる一モーラ差。"}, {"text": "合唱", "is_correct": false, "explanation": "読みは「がっしょう」。最初の「け」が「が」に変わる一モーラ差。"}, {"text": "血相", "is_correct": false, "explanation": "読みは「けっそう」。「しょ」が「そ」に変わる一モーラ差。"}], "explanations": {"結晶": "正解。読みは「けっしょう」。", "結構": "読みは「けっこう」。「しょ」が「こ」に変わる一モーラ差。", "決闘": "読みは「けっとう」。「しょ」が「と」に変わる一モーラ差。", "血色": "読みは「けっしょく」。最後の「う」が「く」に変わる一モーラ差。", "合唱": "読みは「がっしょう」。最初の「け」が「が」に変わる一モーラ差。", "血相": "読みは「けっそう」。「しょ」が「そ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "結晶"}, "level_3": {"options": [{"text": "結晶", "is_correct": true, "explanation": "意味：雪が作る規則正しい形の固体を指す。"}, {"text": "気分", "is_correct": false, "explanation": "意味：雪は気分を持たない。"}, {"text": "約束", "is_correct": false, "explanation": "意味：雪とは結びつかない抽象語。"}, {"text": "値段", "is_correct": false, "explanation": "連語：「雪の値段が美しい形」は意味が通らない。"}], "explanations": {"結晶": "意味：雪が作る規則正しい形の固体を指す。", "気分": "意味：雪は気分を持たない。", "約束": "意味：雪とは結びつかない抽象語。", "値段": "連語：「雪の値段が美しい形」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "結晶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂糖の結晶を一冊買った。", "explanation": "助数詞の誤り：結晶を「冊」で数えない。"}, {"text": "砂糖に結晶が大きく育った。", "explanation": "助詞の混同：「砂糖の結晶」とすべき。"}, {"text": "砂糖の結晶が明日大きく育った。", "explanation": "時制の誤り：「明日」と過去形「育った」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd48c05-9369-4575-9a85-0f232a9377ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version