INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52366, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置に自然に入る助詞。"}, {"text": "が", "is_correct": false, "explanation": "「見た」の目的語を主格で示すと非文になる。"}, {"text": "に", "is_correct": false, "explanation": "「見る」の対象は「に」で示さない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、「見た」の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "この位置に自然に入る助詞。", "が": "「見た」の目的語を主格で示すと非文になる。", "に": "「見る」の対象は「に」で示さない。", "へ": "方向を表し、「見た」の目的語にならない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd48c05-9369-4575-9a85-0f232a9377ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52366, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "結晶", "is_correct": true, "explanation": "正解。読みは「けっしょう」。"}, {"text": "化粧", "is_correct": false, "explanation": "読みは「けしょう」。促音の有無の差。"}, {"text": "実証", "is_correct": false, "explanation": "読みは「じっしょう」。最初の「け」が「じ」に変わる一モーラ差。"}, {"text": "発症", "is_correct": false, "explanation": "読みは「はっしょう」。最初の「け」が「は」に変わる一モーラ差。"}, {"text": "熱唱", "is_correct": false, "explanation": "読みは「ねっしょう」。最初の「け」が「ね」に変わる一モーラ差。"}], "explanations": {"結晶": "正解。読みは「けっしょう」。", "化粧": "読みは「けしょう」。促音の有無の差。", "実証": "読みは「じっしょう」。最初の「け」が「じ」に変わる一モーラ差。", "発症": "読みは「はっしょう」。最初の「け」が「は」に変わる一モーラ差。", "熱唱": "読みは「ねっしょう」。最初の「け」が「ね」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "結晶"}, "level_3": {"options": [{"text": "結晶", "is_correct": true, "explanation": "意味：水晶は鉱物の結晶である。"}, {"text": "足音", "is_correct": false, "explanation": "意味：石が足音であることはない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：石と天気は結びつかない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：水晶の宿題という概念はない。"}], "explanations": {"結晶": "意味：水晶は鉱物の結晶である。", "足音": "意味：石が足音であることはない。", "天気": "意味：石と天気は結びつかない。", "宿題": "意味：水晶の宿題という概念はない。"}, "sentence_index": 6, "correct_answer": "結晶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "顕微鏡を雪の結晶で調べた。", "explanation": "助詞の混同：道具と対象が入れ替わっている。"}, {"text": "雪の結晶を三人調べた。", "explanation": "助数詞の誤り：結晶を「人」で数えない。"}, {"text": "顕微鏡で雪の結晶を明日調べた。", "explanation": "時制の誤り：「明日」と過去形が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd48c05-9369-4575-9a85-0f232a9377ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings,