INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52366, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "この位置に自然に入る助詞。"}, {"text": "を", "is_correct": false, "explanation": "名詞を修飾する位置に目的格は入らない。"}, {"text": "に", "is_correct": false, "explanation": "「雪に結晶は」は名詞修飾にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、ここでは非文。"}], "correct_answer": "の", "explanations": {"の": "この位置に自然に入る助詞。", "を": "名詞を修飾する位置に目的格は入らない。", "に": "「雪に結晶は」は名詞修飾にならない。", "で": "手段・場所を表し、ここでは非文。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd48c05-9369-4575-9a85-0f232a9377ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36381, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可逆", "is_correct": true, "explanation": "正解。読みは「かぎゃく」。"}, {"text": "家族", "is_correct": false, "explanation": "読みは「かぞく」。「ぎゃ」が「ぞ」に変わる一モーラ差。"}, {"text": "加速", "is_correct": false, "explanation": "読みは「かそく」。「ぎゃ」が「そ」に変わる一モーラ差。"}, {"text": "化学", "is_correct": false, "explanation": "読みは「かがく」。「ぎゃ」が「が」に変わる一モーラ差。"}, {"text": "火薬", "is_correct": false, "explanation": "読みは「かやく」。「ぎゃ」が「や」に変わる一モーラ差。"}], "explanations": {"可逆": "正解。読みは「かぎゃく」。", "家族": "読みは「かぞく」。「ぎゃ」が「ぞ」に変わる一モーラ差。", "加速": "読みは「かそく」。「ぎゃ」が「そ」に変わる一モーラ差。", "化学": "読みは「かがく」。「ぎゃ」が「が」に変わる一モーラ差。", "火薬": "読みは「かやく」。「ぎゃ」が「や」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "可逆"}, "level_3": {"options": [{"text": "可逆", "is_correct": true, "explanation": "意味：「不可逆的」で元に戻せない性質を表す。"}, {"text": "可燃", "is_correct": false, "explanation": "意味：「不可燃的に定着」は意味をなさない。"}, {"text": "可視", "is_correct": false, "explanation": "意味：見えるかどうかは定着の仕方と無関係。"}, {"text": "可決", "is_correct": false, "explanation": "意味：議案の承認であり、色の定着と結びつかない。"}], "explanations": {"可逆": "意味：「不可逆的」で元に戻せない性質を表す。", "可燃": "意味：「不可燃的に定着」は意味をなさない。", "可視": "意味：見えるかどうかは定着の仕方と無関係。", "可決": "意味：議案の承認であり、色の定着と結びつかない。"}, "sentence_index": 0, "correct_answer": "可逆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この反応は可逆を一冊読んだ。", "explanation": "項構造の誤り：可逆は読む対象にならない。"}, {"text": "この反応に可逆な反応です。", "explanation": "助詞の混同：主題は「は」で示す。"}, {"text": "この反応は昨日可逆な反応になるでしょう。", "explanation": "時制の誤り：「昨日」と推量の未来表現が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd48c05-9369-4575-9a85-0f232a9377ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, v