INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36553, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "熱", "is_correct": true, "explanation": "正解。読みは「ねつ」。"}, {"text": "蜜", "is_correct": false, "explanation": "読みは「みつ」。「ね」が「み」に変わる一モーラ差。"}, {"text": "葱", "is_correct": false, "explanation": "読みは「ねぎ」。「つ」が「ぎ」に変わる一モーラ差。"}, {"text": "夏", "is_correct": false, "explanation": "読みは「なつ」。「ね」が「な」に変わる一モーラ差。"}, {"text": "猫", "is_correct": false, "explanation": "読みは「ねこ」。「つ」が「こ」に変わる一モーラ差。"}], "explanations": {"熱": "正解。読みは「ねつ」。", "蜜": "読みは「みつ」。「ね」が「み」に変わる一モーラ差。", "葱": "読みは「ねぎ」。「つ」が「ぎ」に変わる一モーラ差。", "夏": "読みは「なつ」。「ね」が「な」に変わる一モーラ差。", "猫": "読みは「ねこ」。「つ」が「こ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "熱"}, "level_3": {"options": [{"text": "熱", "is_correct": true, "explanation": "意味：壁が熱を通しにくい。"}, {"text": "約束", "is_correct": false, "explanation": "意味：壁が約束を通すことはない。"}, {"text": "意見", "is_correct": false, "explanation": "意味：壁は意見を通さない。"}, {"text": "試合", "is_correct": false, "explanation": "意味：壁と試合は結びつかない。"}], "explanations": {"熱": "意味：壁が熱を通しにくい。", "約束": "意味：壁が約束を通すことはない。", "意見": "意味：壁は意見を通さない。", "試合": "意味：壁と試合は結びつかない。"}, "sentence_index": 6, "correct_answer": "熱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "エンジンから強い熱を出る。", "explanation": "助詞の混同：自動詞「出る」の主語は「が」で示す。"}, {"text": "エンジンから強い熱が二匹出る。", "explanation": "助数詞の誤り：熱を「匹」で数えない。"}, {"text": "エンジンから強い熱が昨日出るだろう。", "explanation": "時制の誤り：「昨日」と推量が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4dd48c05-9369-4575-9a85-0f232a9377ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_bat