INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39127, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "自然のままで、人の手が加わっていないこと。", "primary_collocate": null, "pronunciation": "てんねん", "ipa": "teɴneɴ", "syllable_count": 4, "sentences": [{"text": "天然染料による染色は、単なる化学的操作の連鎖ではなく、素材と対話する儀礼にも等しい。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "mined"}, {"text": "天然酵母を用いた製パンは、職人の緻密な管理が不可欠な工程です。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "mined"}, {"text": "この水は山の天然の水です。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}, {"text": "天然の魚は少し高いです。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}, {"text": "この石は天然ではありません。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}, {"text": "祖母は天然の素材を好んでいる。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}, {"text": "天然ガスを使って料理する。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}, {"text": "天然の色はとてもやさしい。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}, {"text": "この島には天然の港がある。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}, {"text": "天然か人工か、見て分かりますか。", "target_word": "天然", "complexity_tier": "T3", "furigana": "てんねん", "sentence_source": "generated"}], "morphological_forms": [{"form": "天然もの", "label": "派生"}, {"form": "天然水", "label": "派生"}, {"form": "天然ガス", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人の手が加わらず自然のままのこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47a7e27-7029-4783-8c7c-afd23037a542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事や心の、いちばん深いところ。", "primary_collocate": null, "pronunciation": "おくそこ", "ipa": "okɯsoko", "syllable_count": 4, "sentences": [{"text": "まず、季節の移ろいと共に採取された植物は、熱と水によってその奥底に秘められた色素を解放される。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "mined"}, {"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "mined"}, {"text": "心の奥底では彼を信じている。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}, {"text": "その言葉は胸の奥底に残った。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}, {"text": "海の奥底には光が届かない。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}, {"text": "彼女の奥底にある悲しみを知った。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}, {"text": "奥底から怒りがわいてきた。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}, {"text": "箱の奥底に古い手紙があった。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}, {"text": "本当の気持ちは奥底に隠している。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}, {"text": "奥底まで見ることはできない。", "target_word": "奥底", "complexity_tier": "T3", "furigana": "おくそこ", "sentence_source": "generated"}], "morphological_forms": [{"form": "心の奥底", "label": "派生"}, {"form": "胸の奥底", "label": "派生"}, {"form": "奥底から", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事や心の最も深い部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47a7e27-7029-4783-8c7c-afd23037a542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38117, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が次々とつながって起こること。", "primary_collocate": null, "pronunciation": "れんさ", "ipa": "ɾeɴsa", "syllable_count": 3, "sentences": [{"text": "天然染料による染色は、単なる化学的操作の連鎖ではなく、素材と対話する儀礼にも等しい。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "mined"}, {"text": "我々は、この不可逆的な変化の連鎖をどう受け止めるべきか、文明の存続をかけて抜本的な転換を迫られているのである。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "mined"}, {"text": "事故が連鎖して起きた。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}, {"text": "失敗の連鎖を止めたい。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}, {"text": "笑いが教室で連鎖した。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}, {"text": "悪い連鎖はどこかで切るべきだ。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}, {"text": "連鎖はまだ続いている。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}, {"text": "小さなミスが連鎖を生んだ。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}, {"text": "喜びの連鎖が町に広がった。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}, {"text": "その連鎖は誰にも止められない。", "target_word": "連鎖", "complexity_tier": "T3", "furigana": "れんさ", "sentence_source": "generated"}], "morphological_forms": [{"form": "連鎖する", "label": "派生"}, {"form": "連鎖反応", "label": "派生"}, {"form": "食物連鎖", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が次々につながり起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47a7e27-7029-4783-8c7c-afd23037a542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37739, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地面や海面から上の方までの高さ。", "primary_collocate": null, "pronunciation": "こうど", "ipa": "koːdo", "syllable_count": 3, "sentences": [{"text": "飛行機が高度を上げている。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "この高度では空気が薄い。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "高度一万メートルを飛んでいる。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "鳥はとても高い高度を飛べる。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "高度が下がると耳が痛くなる。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "山の高度を地図で調べた。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "飛行機は高度を下げ始めた。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "画面で高度を見て、位置を確かめた。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "この高度から町がよく見える。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}, {"text": "高度が変わると気温も変わる。", "target_word": "高度", "complexity_tier": "T3", "furigana": "こうど", "sentence_source": "generated"}], "morphological_forms": [{"form": "高度計", "label": "派生"}, {"form": "高度を上げる", "label": "派生"}, {"form": "高度を下げる", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 地表や海面から測った高さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47a7e27-7029-4783-8c