INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35199, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間という生き物の全体。", "primary_collocate": null, "pronunciation": "じんるい", "ipa": "dʑiɴɾɯi", "syllable_count": 4, "sentences": [{"text": "古来、人類は植物の生命力を繊維に宿す術を磨き上げてきた。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "mined"}, {"text": "人類は火を使うようになった。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類の歴史はとても長い。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "月に行くのは人類の夢だった。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "戦争は人類の大きな問題だ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類は地球を守るべきだ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "この発見は人類を救うかもしれない。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類が生まれたのはアフリカだ。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "全人類が平和を願っている。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}, {"text": "人類の未来を考えている。", "target_word": "人類", "complexity_tier": "T3", "furigana": "じんるい", "sentence_source": "generated"}], "morphological_forms": [{"form": "人類学", "label": "派生"}, {"form": "人類史", "label": "派生"}, {"form": "全人類", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 生物の種としての人間全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd47a7e27-7