INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奥底", "is_correct": true, "explanation": "正解。「奥底」（おくそこ）。"}, {"text": "憶測", "is_correct": false, "explanation": "「憶測」はおくそくと読み、「こ」が「く」に変わる一モーラ差。"}, {"text": "奥地", "is_correct": false, "explanation": "「奥地」はおくちと読み、「そこ」が「ち」になる。"}, {"text": "奥歯", "is_correct": false, "explanation": "「奥歯」はおくばと読み、「そこ」が「ば」になる。"}], "explanations": {"奥底": "正解。「奥底」（おくそこ）。", "憶測": "「憶測」はおくそくと読み、「こ」が「く」に変わる一モーラ差。", "奥地": "「奥地」はおくちと読み、「そこ」が「ち」になる。", "奥歯": "「奥歯」はおくばと読み、「そこ」が「ば」になる。"}, "sentence_index": null, "correct_answer": "奥底"}, "level_3": {"options": [{"text": "奥底", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "表面", "is_correct": false, "explanation": "意味：表面に秘められたとは言わず、隠れた色素という文意と逆。"}, {"text": "周辺", "is_correct": false, "explanation": "意味：植物の外側を指し、内部に秘めるという文意に合わない。"}, {"text": "値段", "is_correct": false, "explanation": "意味：植物の値段に色素が秘められることはない。"}], "explanations": {"奥底": "文脈に合う正しい語。", "表面": "意味：表面に秘められたとは言わず、隠れた色素という文意と逆。", "周辺": "意味：植物の外側を指し、内部に秘めるという文意に合わない。", "値段": "意味：植物の値段に色素が秘められることはない。"}, "sentence_index": 0, "correct_answer": "奥底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その言葉は胸の奥底を残った。", "explanation": "助詞の混同：場所を表す「に」を「を」にしている。"}, {"text": "その言葉は胸の奥底に残るった。", "explanation": "活用の誤り：「残るった」ではなく「残った」が正しい。"}, {"text": "胸のその言葉は奥底に残った。", "explanation": "語順の誤り：「胸の」が「言葉」にかかり意味が崩れる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の奥底がある悲しみを知った。", "corrected_sentence": "彼女の奥底にある悲しみを知った。", "error_description": "存在を表す「ある」の場所は「に」で示し、「奥底がある」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "動作が起こる場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、場所を表せない。"}, {"text": "が", "is_correct": false, "explanation": "主格で、この位置では非文になる。"}, {"text": "と", "is_correct": false, "explanation": "並列を表し、「奥底と、…引きずり出した」は非文。"}], "correct_answer": "で", "explanations": {"で": "動作が起こる場所を表す。", "を": "目的語標示で、場所を表せない。", "が": "主格で、この位置では非文になる。", "と": "並列を表し、「奥底と、…引きずり出した」は非文。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "と": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表面", "is_correct": true, "explanation": "物の外側を指し、奥底の対義語。"}, {"text": "深部", "is_correct": false, "explanation": "奥底の類義語で対義ではない。"}, {"text": "記憶", "is_correct": false, "explanation": "心に関わるが反対の関係ではない。"}, {"text": "言葉", "is_correct": false, "explanation": "無関係の語。"}], "correct_answer": "表面", "explanations": {"表面": "物の外側を指し、奥底の対義語。", "深部": "奥底の類義語で対義ではない。", "記憶": "心に関わるが反対の関係ではない。", "言葉": "無関係の語。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奥底", "is_correct": true, "explanation": "正解。「奥底」（おくそこ）。"}, {"text": "憶測", "is_correct": false, "explanation": "「憶測」はおくそくと読み、最後の「こ」が「く」に変わる一モーラ差。"}, {"text": "遅く", "is_correct": false, "explanation": "「遅く」はおそくと読み、「く」が抜けて「こ」が「く」になる。"}, {"text": "屋外", "is_correct": false, "explanation": "「屋外」はおくがいと読み、「そこ」が「がい」になる。"}], "explanations": {"奥底": "正解。「奥底」（おくそこ）。", "憶測": "「憶測」はおくそくと読み、最後の「こ」が「く」に変わる一モーラ差。", "遅く": "「遅く」はおそくと読み、「く」が抜けて「こ」が「く」になる。", "屋外": "「屋外」はおくがいと読み、「そこ」が「がい」になる。"}, "sentence_index": null, "correct_answer": "奥底"}, "level_3": {"options": [{"text": "奥底", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "頭上", "is_correct": false, "explanation": "意味：怒りが頭上からわくとは言わない。"}, {"text": "外側", "is_correct": false, "explanation": "意味：心の外側から感情はわかない。"}, {"text": "明日", "is_correct": false, "explanation": "意味：時を表す語で、わいてくる起点にならない。"}], "explanations": {"奥底": "文脈に合う正しい語。", "頭上": "意味：怒りが頭上からわくとは言わない。", "外側": "意味：心の外側から感情はわかない。", "明日": "意味：時を表す語で、わいてくる起点にならない。"}, "sentence_index": 6, "correct_answer": "奥底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奥底へ見ることはできない。", "explanation": "助詞の混同：範囲の終点は「まで」で、「へ」は不自然。"}, {"text": "奥底まで見ることはできらない。", "explanation": "活用の誤り：「できらない」ではなく「できない」が正しい。"}, {"text": "できない奥底まで見ることは。", "explanation": "語順の誤り：述語が前に出て文が成立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "箱の奥底で古い手紙があった。", "corrected_sentence": "箱の奥底に古い手紙があった。", "error_description": "存在を表す「ある」には場所の「に」を使い、「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52832, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、「ある」とは結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "動作の場所を表し、存在の「ある」には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、存在の「ある」とは結びつかない。"}], "correct_answer": "に", "explanations": {"に": "存在の場所を表す。", "を": "目的語標示で、「ある」とは結びつかない。", "で": "動作の場所を表し、存在の「ある」には使えない。", "へ": "方向を表し、存在の「ある」とは結びつかない。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "へ": "location_vs_target"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "表面", "is_correct": true, "explanation": "奥底と反対に、外側を指す。"}, {"text": "心底", "is_correct": false, "explanation": "奥底に近い意味で対義ではない。"}, {"text": "手紙", "is_correct": false, "explanation": "無関係の語。"}, {"text": "中身", "is_correct": false, "explanation": "内部を指し、対義ではない。"}], "correct_answer": "表面", "explanations": {"表面": "奥底と反対に、外側を指す。", "心底": "奥底に近い意味で対義ではない。", "手紙": "無関係の語。", "中身": "内部を指し、対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38117, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "正解。「連鎖」（れんさ）。"}, {"text": "煉瓦", "is_correct": false, "explanation": "「煉瓦」はれんがと読み、「さ」が「が」に変わる一モーラ差。"}, {"text": "廉価", "is_correct": false, "explanation": "「廉価」はれんかと読み、「さ」が「か」に変わる一モーラ差。"}, {"text": "検査", "is_correct": false, "explanation": "「検査」はけんさと読み、「れ」が「け」に変わる一モーラ差。"}, {"text": "偏差", "is_correct": false, "explanation": "「偏差」はへんさと読み、「れ」が「へ」に変わる一モーラ差。"}], "explanations": {"連鎖": "正解。「連鎖」（れんさ）。", "煉瓦": "「煉瓦」はれんがと読み、「さ」が「が」に変わる一モーラ差。", "廉価": "「廉価」はれんかと読み、「さ」が「か」に変わる一モーラ差。", "検査": "「検査」はけんさと読み、「れ」が「け」に変わる一モーラ差。", "偏差": "「偏差」はへんさと読み、「れ」が「へ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "連鎖"}, "level_3": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "停止", "is_correct": false, "explanation": "意味：操作が止まることで、次々と続く染色工程の意味にならない。"}, {"text": "価格", "is_correct": false, "explanation": "意味：化学的操作の値段ではなく、文意に合わない。"}, {"text": "無視", "is_correct": false, "explanation": "項構造：「操作の無視ではなく」は対比として不自然。"}], "explanations": {"連鎖": "文脈に合う正しい語。", "停止": "意味：操作が止まることで、次々と続く染色工程の意味にならない。", "価格": "意味：化学的操作の値段ではなく、文意に合わない。", "無視": "項構造：「操作の無視ではなく」は対比として不自然。"}, "sentence_index": 0, "correct_answer": "連鎖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "失敗の連鎖に止めたい。", "explanation": "助詞の混同：他動詞「止める」の目的語は「を」で、「に」は誤り。"}, {"text": "失敗の連鎖を二枚止めたい。", "explanation": "助数詞の誤り：連鎖を「枚」で数えない。"}, {"text": "失敗の連鎖を止めるたい。", "explanation": "活用の誤り：「たい」は連用形につき「止めたい」が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
