INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38117, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "正解。「連鎖」（れんさ）。"}, {"text": "偏差", "is_correct": false, "explanation": "「偏差」はへんさと読み、最初の「れ」が「へ」に変わる一モーラ差。"}, {"text": "検査", "is_correct": false, "explanation": "「検査」はけんさと読み、最初の「れ」が「け」に変わる一モーラ差。"}, {"text": "連座", "is_correct": false, "explanation": "「連座」はれんざと読み、「さ」が濁音の「ざ」になる清濁の対立。"}, {"text": "連打", "is_correct": false, "explanation": "「連打」はれんだと読み、「さ」が「だ」に変わる一モーラ差。"}], "explanations": {"連鎖": "正解。「連鎖」（れんさ）。", "偏差": "「偏差」はへんさと読み、最初の「れ」が「へ」に変わる一モーラ差。", "検査": "「検査」はけんさと読み、最初の「れ」が「け」に変わる一モーラ差。", "連座": "「連座」はれんざと読み、「さ」が濁音の「ざ」になる清濁の対立。", "連打": "「連打」はれんだと読み、「さ」が「だ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "連鎖"}, "level_3": {"options": [{"text": "連鎖", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "昨日", "is_correct": false, "explanation": "意味：時の語で「まだ続いている」の主語にならない。"}, {"text": "机", "is_correct": false, "explanation": "意味：物が続いているとは言わない。"}, {"text": "終わり", "is_correct": false, "explanation": "意味：終わりが続いているは矛盾する。"}], "explanations": {"連鎖": "文脈に合う正しい語。", "昨日": "意味：時の語で「まだ続いている」の主語にならない。", "机": "意味：物が続いているとは言わない。", "終わり": "意味：終わりが続いているは矛盾する。"}, "sentence_index": 6, "correct_answer": "連鎖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その連鎖は誰にを止められない。", "explanation": "助詞の混同：「誰にも」の「も」を「を」にしている。"}, {"text": "その連鎖は誰にも止められなかっている。", "explanation": "活用の誤り：「止められなかっている」は存在しない形。"}, {"text": "誰にもその止められない連鎖は。", "explanation": "語順の誤り：述語が欠け、文が成立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04e1d9ab-3efb-4f6d-8f3f-b4ce787f2fa7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_