INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37315, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目標を達成するために、全体の流れを考えて立てる、大きな計画や方法。", "primary_collocate": null, "pronunciation": "せんりゃく", "ipa": "seɴɾʲakɯ", "syllable_count": 4, "sentences": [{"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "せんりゃく", "sentence_source": "mined"}, {"text": "単なる出資にとどまらず、経営戦略やネットワークを提供することで、市場に新たな価値を生むイノベーションを加速させるのだ。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "せんりゃく", "sentence_source": "mined"}, {"text": "チームで試合の戦略を考えた。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "しあい せんりゃく かんが", "sentence_source": "generated"}, {"text": "その戦略はうまくいかなかった。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "せんりゃく", "sentence_source": "generated"}, {"text": "会社は新しい戦略を立てている。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "かいしゃ あたら せんりゃく た", "sentence_source": "generated"}, {"text": "戦略を変えて、もう一度挑戦する。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "せんりゃく か いちど ちょうせん", "sentence_source": "generated"}, {"text": "彼は戦略を考えるのが得意だ。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "かれ せんりゃく かんが とくい", "sentence_source": "generated"}, {"text": "このゲームは戦略が大切だ。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "せんりゃく たいせつ", "sentence_source": "generated"}, {"text": "監督の戦略で試合に勝てた。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "かんとく せんりゃく しあい か", "sentence_source": "generated"}, {"text": "店の売り上げを伸ばす戦略を話し合う。", "target_word": "戦略", "complexity_tier": "T3", "furigana": "みせ う あ の せんりゃく はな あ", "sentence_source": "generated"}], "morphological_forms": [{"form": "戦略的", "label": "派生"}, {"form": "経営戦略", "label": "派生"}, {"form": "戦略家", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 目標達成のための大きな計画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: エグジット (Zipf 1.27)']::text[], '8eabe010-75e1-49b7-9bfa-245c9904244b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36427, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "利益を得るために、資金や資本を出すこと。", "primary_collocate": null, "pronunciation": "とうし", "ipa": "toːɕi", "syllable_count": 3, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "投資", "complexity_tier": "T3", "furigana": "とうし", "sentence_source": "mined"}, {"text": "やがて企業が成熟すると、創業者や投資家は投資した対価を得るために、他社による買収や株式上場といったエグジット、すなわち出口戦略を選択する。", "target_word": "投資", "complexity_tier": "T3", "furigana": "とうし", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "投資", "complexity_tier": "T3", "furigana": "とうし", "sentence_source": "mined"}, {"text": "父は株に投資している。", "target_word": "投資", "complexity_tier": "T3", "furigana": "ちち かぶ とうし", "sentence_source": "generated"}, {"text": "投資にはリスクがある。", "target_word": "投資", "complexity_tier": "T3", "furigana": "とうし", "sentence_source": "generated"}, {"text": "会社は新しい工場に投資した。", "target_word": "投資", "complexity_tier": "T3", "furigana": "かいしゃ あたら こうじょう とうし", "sentence_source": "generated"}, {"text": "投資のお金が戻ってきた。", "target_word": "投資", "complexity_tier": "T3", "furigana": "とうし かね もど", "sentence_source": "generated"}, {"text": "彼は投資で大金を失った。", "target_word": "投資", "complexity_tier": "T3", "furigana": "かれ とうし たいきん うしな", "sentence_source": "generated"}, {"text": "町は教育への投資を増やした。", "target_word": "投資", "complexity_tier": "T3", "furigana": "まち きょういく とうし ふ", "sentence_source": "generated"}, {"text": "投資を始める前によく調べよう。", "target_word": "投資", "complexity_tier": "T3", "furigana": "とうし はじ まえ しら", "sentence_source": "generated"}], "morphological_forms": [{"form": "投資する", "label": "派生"}, {"form": "投資家", "label": "派生"}, {"form": "設備投資", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 利益のために資金を出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: エグジット (Zipf 1.27)','sentence 2 above tier T2: 5 words above tier T2 (max 3): サプライ (Zipf 3.19), 文脈 (Zipf 3.63), ミクロ (Zipf 3.34), 局所 (Zipf 3.35), 線形 (Zipf 2.97)']::text[], '8eabe010-75e1-49b7-9bfa-245c9904244b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37241, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目標や目的地を定めて、それに向かって努力したり進んだりすること。", "primary_collocate": null, "pronunciation": "めざす", "ipa": "mezasɯ", "syllable_count": 3, "sentences": [{"text": "初期段階では、投資家からの資金調達を通じて事業の基盤を固め、市場での急速な成長を目指す。", "target_word": "目指す", "complexity_tier": "T3", "furigana": "めざ", "sentence_source": "mined"}, {"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "目指さ", "complexity_tier": "T3", "furigana": "めざ", "sentence_source": "mined"}, {"text": "兄は医者を目指している。", "target_word": "目指", "complexity_tier": "T3", "furigana": "あに いしゃ めざ", "sentence_source": "generated"}, {"text": "私たちは優勝を目指す。", "target_word": "目指す", "complexity_tier": "T3", "furigana": "わたし ゆうしょう めざ", "sentence_source": "generated"}, {"text": "山の頂上を目指して歩いた。", "target_word": "目指", "complexity_tier": "T3", "furigana": "やま ちょうじょう めざ ある", "sentence_source": "generated"}, {"text": "彼女が目指す学校は遠い。", "target_word": "目指す", "complexity_tier": "T3", "furigana": "かのじょ めざ がっこう とお", "sentence_source": "generated"}, {"text": "夢を目指して毎日練習する。", "target_word": "目指", "complexity_tier": "T3", "furigana": "ゆめ めざ まいにち れんしゅう", "sentence_source": "generated"}, {"text": "目指す場所はもうすぐだ。", "target_word": "目指す", "complexity_tier": "T3", "furigana": "めざ ばしょ", "sentence_source": "generated"}, {"text": "船は港を目指して進んだ。", "target_word": "目指", "complexity_tier": "T3", "furigana": "ふね みなと めざ すす", "sentence_source": "generated"}, {"text": "合格を目指すなら、今がんばろう。", "target_word": "目指す", "complexity_tier": "T3", "furigana": "ごうかく めざ いま", "sentence_source": "generated"}], "morphological_forms": [{"form": "目指した", "label": "活用"}, {"form": "目指して", "label": "活用"}, {"form": "目指さない", "label": "活用"}, {"form": "目指せる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 目標に向かって努力し進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8eabe010-75e1-49b7-9bfa-245c9904244b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35601, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分が住んでいる地域や場所。", "primary_collocate": null, "pronunciation": "じもと", "ipa": "dʑimoto", "syllable_count": 3, "sentences": [{"text": "この時間帯に与える食べ物は、地元で採れた新鮮な穀物と野菜を混ぜ合わせたものだ。", "target_word": "地元", "complexity_tier": "T3", "furigana": "じもと", "sentence_source": "mined"}, {"text": "地元の風景を愛するロックバンドが、新たなオリジナルTシャツを製作しました。", "target_word": "地元", "complexity_tier": "T3", "furigana": "じもと", "sentence_source": "mined"}, {"text": "夏休みに地元へ帰った。", "target_word": "地元", "complexity_tier": "T3", "furigana": "なつやす じもと かえ", "sentence_source": "generated"}, {"text": "地元の友だちと会った。", "target_word": "地元", "complexity_tier": "T3", "furigana": "じもと とも あ", "sentence_source": "generated"}, {"text": "私の地元は海が近い。", "target_word": "地元", "complexity_tier": "T3", "furigana": "わたし じもと うみ ちか", "sentence_source": "generated"}, {"text": "この店は地元で有名だ。", "target_word": "地元", "complexity_tier": "T3", "furigana": "みせ じもと ゆうめい", "sentence_source": "generated"}, {"text": "地元の野菜はおいしい。", "target_word": "地元", "complexity_tier": "T3", "furigana": "じもと やさい", "sentence_source": "generated"}, {"text": "彼は地元を離れて東京で働いている。", "target_word": "地元", "complexity_tier": "T3", "furigana": "かれ じもと はな とうきょう はたら", "sentence_source": "generated"}, {"text": "地元の祭りに参加した。", "target_word": "地元", "complexity_tier": "T3", "furigana": "じもと まつ さんか", "sentence_source": "generated"}, {"text": "地元が大好きだ。", "target_word": "地元", "complexity_tier": "T3", "furigana": "じもと だいす", "sentence_source": "generated"}], "morphological_forms": [{"form": "地元民", "label": "派生"}, {"form": "地元産", "label": "派生"}, {"form": "地元愛", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分が住んでいる地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::json