INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35995, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の、目に見える姿や、全体のようす。", "primary_collocate": null, "pronunciation": "かたち", "ipa": "katatɕi", "syllable_count": 3, "sentences": [{"text": "それは、言葉を持たぬ者が自然と交わす、最も純粋な対話の形なのかもしれない。", "target_word": "形", "complexity_tier": "T3", "furigana": "かたち", "sentence_source": "mined"}, {"text": "このTシャツは、単なるグッズではなく、彼らのルーツへの敬意を形にしたものです。", "target_word": "形", "complexity_tier": "T3", "furigana": "かたち", "sentence_source": "mined"}, {"text": "この石はハートの形をしている。", "target_word": "形", "complexity_tier": "T3", "furigana": "いし かたち", "sentence_source": "generated"}, {"text": "雲の形が毎日変わる。", "target_word": "形", "complexity_tier": "T3", "furigana": "くも かたち まいにち か", "sentence_source": "generated"}, {"text": "形のきれいなりんごを選んだ。", "target_word": "形", "complexity_tier": "T3", "furigana": "かたち えら", "sentence_source": "generated"}, {"text": "家族の形はいろいろある。", "target_word": "形", "complexity_tier": "T3", "furigana": "かぞく かたち", "sentence_source": "generated"}, {"text": "粘土で星の形を作った。", "target_word": "形", "complexity_tier": "T3", "furigana": "ねんど ほし かたち つく", "sentence_source": "generated"}, {"text": "その案はやっと形になった。", "target_word": "形", "complexity_tier": "T3", "furigana": "あん かたち", "sentence_source": "generated"}, {"text": "このコップは形が変わっている。", "target_word": "形", "complexity_tier": "T3", "furigana": "かたち か", "sentence_source": "generated"}, {"text": "感謝の気持ちを形で表したい。", "target_word": "形", "complexity_tier": "T3", "furigana": "かんしゃ きも かたち あらわ", "sentence_source": "generated"}], "morphological_forms": [{"form": "形づくる", "label": "派生"}, {"form": "形見", "label": "派生"}, {"form": "形にする", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の目に見える姿やようす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb,