INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51828, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "高校を出たあとに進む、専門の分野を深く学ぶ学校。", "primary_collocate": null, "pronunciation": "だいがく", "ipa": "daiɡakɯ", "syllable_count": 4, "sentences": [{"text": "大学教育の現場において、教授陣が個々の学修到達度を最大化するためにこのシステムを如何に設計し、運用するかが問われているのである。", "target_word": "大学", "complexity_tier": "T3", "furigana": "だいがくきょういく げんば きょうじゅじん ここ がくしゅうとうたつど さいだいか せっけい うんよう と", "sentence_source": "mined"}, {"text": "デザインを担当したのは、美術大学に通うメンバーです。", "target_word": "大学", "complexity_tier": "T3", "furigana": "たんとう びじゅつだいがく かよ", "sentence_source": "mined"}, {"text": "兄は東京の大学に通っている。", "target_word": "大学", "complexity_tier": "T3", "furigana": "あに とうきょう だいがく かよ", "sentence_source": "generated"}, {"text": "来年、大学を受験します。", "target_word": "大学", "complexity_tier": "T3", "furigana": "らいねん だいがく じゅけん", "sentence_source": "generated"}, {"text": "大学で経済を勉強したい。", "target_word": "大学", "complexity_tier": "T3", "furigana": "だいがく けいざい べんきょう", "sentence_source": "generated"}, {"text": "この大学は図書館が広い。", "target_word": "大学", "complexity_tier": "T3", "furigana": "だいがく としょかん ひろ", "sentence_source": "generated"}, {"text": "姉は春に大学を卒業した。", "target_word": "大学", "complexity_tier": "T3", "furigana": "あね はる だいがく そつぎょう", "sentence_source": "generated"}, {"text": "大学の友達と旅行に行った。", "target_word": "大学", "complexity_tier": "T3", "furigana": "だいがく ともだち りょこう い", "sentence_source": "generated"}, {"text": "大学は駅から近いです。", "target_word": "大学", "complexity_tier": "T3", "furigana": "だいがく えき ちか", "sentence_source": "generated"}, {"text": "父が出た大学を見学した。", "target_word": "大学", "complexity_tier": "T3", "furigana": "ちち で だいがく けんがく", "sentence_source": "generated"}], "morphological_forms": [{"form": "校", "label": "助数詞"}, {"form": "大学生", "label": "派生"}, {"form": "大学院", "label": "派生"}], "register": "plain", "sense_fingerprint": 