INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53246, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「抑える」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「色数が抑えた」は他動詞と合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は目的語を示さない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段で、ここに合わない。"}], "correct_answer": "を", "explanations": {"を": "「抑える」の目的語を示す。", "が": "「色数が抑えた」は他動詞と合わない。", "に": "「に」は目的語を示さない。", "で": "「で」は手段で、ここに合わない。"}, "error_tags": {"が": "object_vs_subject", "に": "target_vs_object", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "増やす", "is_correct": true, "explanation": "費用を少なく保つ「抑える」の反対。"}, {"text": "減らす", "is_correct": false, "explanation": "同じ方向の語で反対語ではない。"}, {"text": "控える", "is_correct": false, "explanation": "類義語で反対語ではない。"}, {"text": "止める", "is_correct": false, "explanation": "類義語に近く反対語ではない。"}], "correct_answer": "増やす", "explanations": {"増やす": "費用を少なく保つ「抑える」の反対。", "減らす": "同じ方向の語で反対語ではない。", "控える": "類義語で反対語ではない。", "止める": "類義語に近く反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e865bcea-c569-4f22-8864-82c030d8bc83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
