INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53246, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "受身の動作主を示す「に」（衝動に駆られる）。"}, {"text": "を", "is_correct": false, "explanation": "「衝動を駆られ」は受身と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「衝動へ駆られ」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「衝動が駆られ」は意味が逆になる。"}], "correct_answer": "に", "explanations": {"に": "受身の動作主を示す「に」（衝動に駆られる）。", "を": "「衝動を駆られ」は受身と合わない。", "へ": "「衝動へ駆られ」は成り立たない。", "が": "「衝動が駆られ」は意味が逆になる。"}, "error_tags": {"を": "object_vs_agent", "へ": "direction_vs_agent", "が": "subject_vs_agent"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出す", "is_correct": true, "explanation": "気持ちを外に出さない「抑える」の反対。"}, {"text": "こらえる", "is_correct": false, "explanation": "類義語で反対語ではない。"}, {"text": "我慢する", "is_correct": false, "explanation": "類義語で反対語ではない。"}, {"text": "隠す", "is_correct": false, "explanation": "似た方向の語で反対語ではない。"}], "correct_answer": "出す", "explanations": {"出す": "気持ちを外に出さない「抑える」の反対。", "こらえる": "類義語で反対語ではない。", "我慢する": "類義語で反対語ではない。", "隠す": "似た方向の語で反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e865bcea-c569-4f22-8864-82c030d8bc83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
