INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51916, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の手で作ること。また、作ったもの。", "primary_collocate": null, "pronunciation": "てづくり", "ipa": "tez̥ɯkɯɾi", "syllable_count": 4, "sentences": [{"text": "趣味で手作りしたアクセサリーを収入につなげたいなら、オンラインビジネスの構築が有効です。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "しゅみ てづく しゅうにゅう こうちく ゆうこう", "sentence_source": "mined"}, {"text": "記録的な暑さが続く夏の午後、公園の入り方で一人の少年が手作りのレモネードを販売していた。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "きろくてき あつ つづ なつ ごご こうえん い かた ひとり しょうねん てづく はんばい", "sentence_source": "mined"}, {"text": "母の手作りのケーキはとてもおいしい。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "はは てづく", "sentence_source": "generated"}, {"text": "友だちに手作りのカードをあげた。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "とも てづく", "sentence_source": "generated"}, {"text": "この店のパンは全部手作りだ。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "みせ ぜんぶ てづく", "sentence_source": "generated"}, {"text": "手作りは時間がかかるが、楽しい。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "てづく じかん たの", "sentence_source": "generated"}, {"text": "祖父が手作りした椅子に座っている。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "そふ てづく いす すわ", "sentence_source": "generated"}, {"text": "手作りの料理で家族を喜ばせたい。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "てづく りょうり かぞく よろこ", "sentence_source": "generated"}, {"text": "彼女は服を手作りできる。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "かのじょ ふく てづく", "sentence_source": "generated"}, {"text": "文化祭で手作りの品を売っている。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "ぶんかさい てづく しな う", "sentence_source": "generated"}], "morphological_forms": [{"form": "手作りする", "label": "派生"}, {"form": "手作り感", "label": "派生"}, {"form": "手作り品", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分の手で作ること・作った物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0d6136-7ce6-49ec-9491-12721d895b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38763, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "目的にかなって、よい効果があること。", "primary_collocate": null, "pronunciation": "ゆうこう", "ipa": "jɯːkoː", "syllable_count": 4, "sentences": [{"text": "趣味で手作りしたアクセサリーを収入につなげたいなら、オンラインビジネスの構築が有効です。", "target_word": "有効", "complexity_tier": "T3", "furigana": "しゅみ てづく しゅうにゅう こうちく ゆうこう", "sentence_source": "mined"}, {"text": "現代の高等教育において、画一的な知識伝達モデルはもはやその有効性を維持し得ない。", "target_word": "有効", "complexity_tier": "T3", "furigana": "げんだい こうとうきょういく かくいつてき ちしき でんたつ いじ え ゆうこうせい", "sentence_source": "mined"}, {"text": "毎日の復習は暗記にとても有効だ。", "target_word": "有効", "complexity_tier": "T3", "furigana": "まいにち ふくしゅう あんき ゆうこう", "sentence_source": "generated"}, {"text": "時間を有効に使いたいと思っている。", "target_word": "有効", "complexity_tier": "T3", "furigana": "じかん ゆうこう つか おも", "sentence_source": "generated"}, {"text": "この薬はかぜに有効だそうだ。", "target_word": "有効", "complexity_tier": "T3", "furigana": "くすり ゆうこう", "sentence_source": "generated"}, {"text": "もっと有効な方法を考えてみよう。", "target_word": "有効", "complexity_tier": "T3", "furigana": "ゆうこう ほうほう かんが", "sentence_source": "generated"}, {"text": "運動はストレスを減らすのに有効です。", "target_word": "有効", "complexity_tier": "T3", "furigana": "うんどう へ ゆうこう", "sentence_source": "generated"}, {"text": "話し合いは問題の解決に有効だった。", "target_word": "有効", "complexity_tier": "T3", "furigana": "はな あ もんだい かいけつ ゆうこう", "sentence_source": "generated"}, {"text": "有効な練習を続ければ上手になれる。", "target_word": "有効", "complexity_tier": "T3", "furigana": "ゆうこう れんしゅう つづ じょうず", "sentence_source": "generated"}, {"text": "地図アプリは旅行で有効に使える。", "target_word": "有効", "complexity_tier": "T3", "furigana": "ちず りょこう ゆうこう つか", "sentence_source": "generated"}], "morphological_forms": [{"form": "有効な", "label": "活用"}, {"form": "有効に", "label": "活用"}, {"form": "有効だった", "label": "活用"}, {"form": "有効性", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 目的に合いよい効果がある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0d6136-7ce6-49ec-9491-12721d895b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35177, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "情報や気持ちを、言葉などで相手に知らせる。", "primary_collocate": null, "pronunciation": "つたえる", "ipa": "tsɯtaeɾɯ", "syllable_count": 4, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "せいこう かぎ しょうひん みりょく つた しゃしん くふう そう とど", "sentence_source": "mined"}, {"text": "色は単なる装飾ではなく、記号論の観点から特定のメッセージを伝える記号として機能するのだ。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "いろ たん そうしょく きごうろん かんてん とくてい つた きごう きのう", "sentence_source": "mined"}, {"text": "先生に休むことを伝える。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "せんせい やす つた", "sentence_source": "generated"}, {"text": "気持ちを言葉で伝えるのは難しい。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "きも ことば つた むずか", "sentence_source": "generated"}, {"text": "母に「ありがとう」と伝えたい。", "target_word": "伝え", "complexity_tier": "T3", "furigana": "はは つた", "sentence_source": "generated"}, {"text": "彼にこのニュースを伝えてください。", "target_word": "伝え", "complexity_tier": "T3", "furigana": "かれ つた", "sentence_source": "generated"}, {"text": "友だちに本当の理由を伝えなかった。", "target_word": "伝え", "complexity_tier": "T3", "furigana": "とも ほんとう りゆう つた", "sentence_source": "generated"}, {"text": "伝える力は社会で大切だ。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "つた ちから しゃかい たいせつ", "sentence_source": "generated"}, {"text": "手紙で感謝を伝えることができた。", "target_word": "伝える", "complexity_tier": "T3", "furigana": "てがみ かんしゃ つた", "sentence_source": "generated"}, {"text": "大事な話は早めに伝えている。", "target_word": "伝え", "complexity_tier": "T3", "furigana": "だいじ はなし はや つた", "sentence_source": "generated"}], "morphological_forms": [{"form": "伝えた", "label": "活用"}, {"form": "伝えて", "label": "活用"}, {"form": "伝えない", "label": "活用"}, {"form": "伝えられる", "label": "活用"}, {"form": "お伝えする", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "動詞 | 情報や気持ちを人に知らせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0d6136-7ce6-49ec-9491-12721d895b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41347, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "それがさらに進んで、もっと広い結果につながることを表す。", "primary_collocate": null, "pronunciation": "ひいては", "ipa": "çiːtewa", "syllable_count": 4, "sentences": [{"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "きそん りょくち ゆうきてき けいせい せいたいけい かいろう きのう ほかん ちいき ぜんたい かんきょう こうじょう げんどうりょく え", "sentence_source": "mined"}, {"text": "資金のみならず、経営の知見や人的ネットワークが注入されることで、個々の企業の成長が触発され、結果として社会実装を加速させ、ひいては経済構造の変革を促す強力な原動力となるのだ。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "しきん けいえい ちけん じんてき ちゅうにゅう ここ きぎょう せいちょう しょくはつ けっか しゃかい じっそう かそく けいざい こうぞう へんかく うなが きょうりょく げんどうりょく", "sentence_source": "mined"}, {"text": "自分を守り、ひいては家族を守る。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "じぶん まも かぞく まも", "sentence_source": "generated"}, {"text": "町が育ち、ひいては国も強くなる。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "まち そだ くに つよ", "sentence_source": "generated"}, {"text": "勉強は将来、ひいては人生に役立つ。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "べんきょう しょうらい じんせい やくだ", "sentence_source": "generated"}, {"text": "一人の努力がひいては皆を助ける。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "ひとり どりょく みな たす", "sentence_source": "generated"}, {"text": "ごみを減らし、ひいては地球を守る。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "へ ちきゅう まも", "sentence_source": "generated"}, {"text": "笑顔は友だち、ひいてはクラスを変える。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "えがお とも か", "sentence_source": "generated"}, {"text": "健康はひいては仕事の力になる。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "けんこう しごと ちから", "sentence_source": "generated"}, {"text": "小さな親切がひいては町を明るくする。", "target_word": "ひいては", "complexity_tier": "T3", "furigana": "ちい しんせつ まち あか", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "副詞 | さらに進んで広い結果に及ぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0d6136-7ce6-49ec-9491-12721d895b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36361, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "社会や集団の中で、物事が正しい順序や決まりに従って整っている状態。", "primary_collocate": null, "pronunciation": "ちつじょ", "ipa": "tɕitsɯdʑo", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "きんねん とし むちつじょ かくだい ともな みどり きはくか はど かくち けんざいか", "sentence_source": "mined"}, {"text": "むしろ、それらの相互作用が織りなす複雑適応システムにおいては、正負のフィードバックを介した非線形なダイナミクスが、予測不可能なマクロな秩序、すなわち創発をもたらすのである。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "そうごさよう お ふくざつ てきおう せいふ かい ひせんけい よそく ふかのう ちつじょ そうはつ", "sentence_source": "mined"}, {"text": "学校の秩序を守るのは大切だ。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "がっこう ちつじょ まも たいせつ", "sentence_source": "generated"}, {"text": "社会の秩序が乱れている。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "しゃかい ちつじょ みだ", "sentence_source": "generated"}, {"text": "警察は町の秩序を守っている。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "けいさつ まち ちつじょ まも", "sentence_source": "generated"}, {"text": "ルールがあると秩序が生まれる。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "う ちつじょ う", "sentence_source": "generated"}, {"text": "秩序のある教室は勉強しやすい。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "ちつじょ きょうしつ べんきょう", "sentence_source": "generated"}, {"text": "みんなで秩序を作っていこう。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "ちつじょ つく", "sentence_source": "generated"}, {"text": "祭りの日も秩序は保たれていた。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "まつ ひ ちつじょ たも", "sentence_source": "generated"}, {"text": "秩序がない集団はまとまらない。", "target_word": "秩序", "complexity_tier": "T3", "furigana": "ちつじょ しゅうだん", "sentence_source": "generated"}], "morphological_forms": [{"form": "無秩序", "label": "派生"}, {"form": "秩序立てる", "label": "派生"}, {"form": "秩序正しい", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事が決まりに従い整った状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 5 words above tier T3 (max 3): 織りなす (Zipf 2.63), 正負 (Zipf 2.09), 非線形 (Zipf 2.6), ダイナミクス (Zipf 2.32), 創発 (Zipf 2.41)']::text[], 'fa0d6136-7ce6-49ec-9491-12721d895b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37911, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "今までなかったものや考えを、新しく作り出すこと。", "primary_collocate": null, "pronunciation": "そうしゅつ", "ipa": "soːɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "創出", "complexity_tier": "T3", "furigana": "とく じゅうみん しゅたいてき さんか そうしゅつ せいぶつ たようせい かいふく びきこう かいぜん そくめん きんりん りょくち こうえいきょう およ", "sentence_source": "mined"}, {"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "創出", "complexity_tier": "T3", "furigana": "ちょっかん たよ けいさん ろんり きのうてき どくそうてき とし くうかん そうしゅつ めざ", "sentence_source": "mined"}, {"text": "町は新しい仕事を創出している。", "target_word": "創出", "complexity_tier": "T3", "furigana": "まち あたら しごと そうしゅつ", "sentence_source": "generated"}, {"text": "雇用の創出が大きな目標だ。", "target_word": "創出", "complexity_tier": "T3", "furigana": "こよう そうしゅつ おお もくひょう", "sentence_source": "generated"}, {"text": "若者が新しい文化を創出した。", "target_word": "創出", "complexity_tier": "T3", "furigana": "わかもの あたら ぶんか そうしゅつ", "sentence_source": "generated"}, {"text": "価値の創出には時間がかかる。", "target_word": "創出", "complexity_tier": "T3", "furigana": "かち そうしゅつ じかん", "sentence_source": "generated"}, {"text": "観光で地域に活気を創出したい。", "target_word": "創出", "complexity_tier": "T3", "furigana": "かんこう ちいき かっき そうしゅつ", "sentence_source": "generated"}, {"text": "この会社はアイデアの創出が得意だ。", "target_word": "創出", "complexity_tier": "T3", "furigana": "かいしゃ そうしゅつ とくい", "sentence_source": "generated"}, {"text": "創出された場所に人が集まる。", "target_word": "創出", "complexity_tier": "T3", "furigana": "そうしゅつ ばしょ ひと あつ", "sentence_source": "generated"}, {"text": "みんなで新しい祭りを創出できる。", "target_word": "創出", "complexity_tier": "T3", "furigana": "あたら まつ そうしゅつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "創出する", "label": "派生"}, {"form": "創出した", "label": "活用"}, {"form": "創出される", "label": "活用"}], "register": "formal", "sense_fingerprint": "名詞 | 新しい物を作り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa0d6136-7ce6-49ec-9491-12721d895b2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51916, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手作り", "is_correct": true, "explanation": "「てづくり」。聞こえた音そのもの。"}, {"text": "手詰まり", "is_correct": false, "explanation": "「てづまり」。三拍目「く」が「ま」に変わる一モーラ差。"}, {"text": "荷造り", "is_correct": false, "explanation": "「にづくり」。一拍目「て」が「に」に変わる一モーラ差。"}, {"text": "田作り", "is_correct": false, "explanation": "「たづくり」。一拍目「て」が「た」に変わる一モーラ差。"}], "explanations": {"手作り": "「てづくり」。聞こえた音そのもの。", "手詰まり": "「てづまり」。三拍目「く」が「ま」に変わる一モーラ差。", "荷造り": "「にづくり」。一拍目「て」が「に」に変わる一モーラ差。", "田作り": "「たづくり」。一拍目「て」が「た」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "手作り"}, "level_3": {"options": [{"text": "手作り", "is_correct": true, "explanation": "趣味で自分で作ったアクセサリーなので文意に合う。"}, {"text": "紛失", "is_correct": false, "explanation": "意味：なくしたアクセサリーを収入につなげることはできない。"}, {"text": "返品", "is_correct": false, "explanation": "意味：趣味で返品するという状況は文脈に合わない。"}, {"text": "解約", "is_correct": false, "explanation": "連語：「アクセサリーを解約する」とは言わない。"}], "explanations": {"手作り": "趣味で自分で作ったアクセサリーなので文意に合う。", "紛失": "意味：なくしたアクセサリーを収入につなげることはできない。", "返品": "意味：趣味で返品するという状況は文脈に合わない。", "解約": "連語：「アクセサリーを解約する」とは言わない。"}, "sentence_index": 0, "correct_answer": "手作り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちに手作るカードをあげた。", "explanation": "語形の誤り：「手作る」という動詞はない。「手作りの」か「手作りした」。"}, {"text": "友だちに手作りしたのカードをあげた。", "explanation": "接続の誤り：「手作りした」は直接名詞を修飾し、「の」は不要。"}, {"text": "友だちに工場で大量に手作りしたカードをあげた。", "explanation": "意味の誤り：工場での大量生産は「手作り」と矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51916, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母の手作るケーキはとてもおいしい。", "corrected_sentence": "母の手作りのケーキはとてもおいしい。", "error_description": "語形の誤り：「手作る」という動詞はない。名詞「手作り」に「の」を付ける。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51916, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「販売する」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「レモネードが販売していた」では売る人と物が逆になり非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、販売する物を示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、ここでは目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「販売する」の目的語を示す。", "が": "「レモネードが販売していた」では売る人と物が逆になり非文。", "に": "着点を表し、販売する物を示せない。", "で": "手段・場所を表し、ここでは目的語にならない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "既製", "is_correct": true, "explanation": "前もって工場などで作られた品で、自分で作る「手作り」の対義。"}, {"text": "手料理", "is_correct": false, "explanation": "手作りの料理の一種で、対義ではない。"}, {"text": "自作", "is_correct": false, "explanation": "自分で作ることで、類義であり対義ではない。"}, {"text": "手書き", "is_correct": false, "explanation": "手で書くことで、「手作り」の対義ではない。"}], "correct_answer": "既製", "explanations": {"既製": "前もって工場などで作られた品で、自分で作る「手作り」の対義。", "手料理": "手作りの料理の一種で、対義ではない。", "自作": "自分で作ることで、類義であり対義ではない。", "手書き": "手で書くことで、「手作り」の対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51916, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手作り", "is_correct": true, "explanation": "「てづくり」と読む。正解。"}, {"text": "荷造り", "is_correct": false, "explanation": "「にづくり」。最初の拍が「に」。"}, {"text": "手袋", "is_correct": false, "explanation": "「てぶくろ」。二拍目が「ぶ」、最後が「ろ」。"}, {"text": "手繰り", "is_correct": false, "explanation": "「たぐり」。音の並びが異なる。"}], "explanations": {"手作り": "「てづくり」と読む。正解。", "荷造り": "「にづくり」。最初の拍が「に」。", "手袋": "「てぶくろ」。二拍目が「ぶ」、最後が「ろ」。", "手繰り": "「たぐり」。音の並びが異なる。"}, "sentence_index": null, "correct_answer": "手作り"}, "level_3": {"options": [{"text": "手作り", "is_correct": true, "explanation": "祖父が自分で作った椅子なので自然。"}, {"text": "紛失", "is_correct": false, "explanation": "意味：なくした椅子に座ることはできない。"}, {"text": "廃棄", "is_correct": false, "explanation": "意味：捨てた椅子に今座っているのは矛盾する。"}, {"text": "欠席", "is_correct": false, "explanation": "項構造：「欠席する」は目的語を取らず、椅子を修飾できない。"}], "explanations": {"手作り": "祖父が自分で作った椅子なので自然。", "紛失": "意味：なくした椅子に座ることはできない。", "廃棄": "意味：捨てた椅子に今座っているのは矛盾する。", "欠席": "項構造：「欠席する」は目的語を取らず、椅子を修飾できない。"}, "sentence_index": 6, "correct_answer": "手作り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "文化祭で手作るの品を売っている。", "explanation": "語形の誤り：「手作る」という動詞はない。「手作りの品」。"}, {"text": "文化祭で手作りに品を売っている。", "explanation": "接続の誤り：名詞を修飾するときは「手作りの」。"}, {"text": "文化祭で機械で手作りした品を売っている。", "explanation": "意味の誤り：機械で作った物は「手作り」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51916, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店のパンは全部手作るだ。", "corrected_sentence": "この店のパンは全部手作りだ。", "error_description": "語形の誤り：「手作る」という動詞はない。名詞「手作り」に「だ」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51916, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「料理」が家族を喜ばせる手段なので「で」。"}, {"text": "を", "is_correct": false, "explanation": "すでに「家族を」があり、目的語が二重になって非文。"}, {"text": "が", "is_correct": false, "explanation": "「料理が家族を喜ばせたい」では料理が願う主体になり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、手段を示せない。"}], "correct_answer": "で", "explanations": {"で": "「料理」が家族を喜ばせる手段なので「で」。", "を": "すでに「家族を」があり、目的語が二重になって非文。", "が": "「料理が家族を喜ばせたい」では料理が願う主体になり不自然。", "へ": "方向を表し、手段を示せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "既製", "is_correct": true, "explanation": "すでに作られて売られている品。自分で作る「手作り」と反対。"}, {"text": "自作", "is_correct": false, "explanation": "自分で作ること。意味が近く、対義ではない。"}, {"text": "手作業", "is_correct": false, "explanation": "手で行う作業。対義ではない。"}, {"text": "手書き", "is_correct": false, "explanation": "手で書くこと。手作りの反対ではない。"}], "correct_answer": "既製", "explanations": {"既製": "すでに作られて売られている品。自分で作る「手作り」と反対。", "自作": "自分で作ること。意味が近く、対義ではない。", "手作業": "手で行う作業。対義ではない。", "手書き": "手で書くこと。手作りの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38763, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有効", "is_correct": true, "explanation": "「ゆうこう」。正解。"}, {"text": "夕刻", "is_correct": false, "explanation": "「ゆうこく」。最後の拍「う」が「く」に変わる一モーラ差。"}, {"text": "融合", "is_correct": false, "explanation": "「ゆうごう」。三拍目「こ」が濁音「ご」になる清濁の差。"}, {"text": "有用", "is_correct": false, "explanation": "「ゆうよう」。三拍目「こ」が「よ」に変わる一モーラ差。"}, {"text": "郵送", "is_correct": false, "explanation": "「ゆうそう」。三拍目「こ」が「そ」に変わる一モーラ差。"}], "explanations": {"有効": "「ゆうこう」。正解。", "夕刻": "「ゆうこく」。最後の拍「う」が「く」に変わる一モーラ差。", "融合": "「ゆうごう」。三拍目「こ」が濁音「ご」になる清濁の差。", "有用": "「ゆうよう」。三拍目「こ」が「よ」に変わる一モーラ差。", "郵送": "「ゆうそう」。三拍目「こ」が「そ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "有効"}, "level_3": {"options": [{"text": "有効", "is_correct": true, "explanation": "目的にかなって役に立つので文意に合う。"}, {"text": "有名", "is_correct": false, "explanation": "意味：構築が「有名」では助言として成り立たない。"}, {"text": "無駄", "is_correct": false, "explanation": "意味：勧める文脈で「無駄」は矛盾する。"}, {"text": "賑やか", "is_correct": false, "explanation": "連語：「構築が賑やかです」とは言わない。"}], "explanations": {"有効": "目的にかなって役に立つので文意に合う。", "有名": "意味：構築が「有名」では助言として成り立たない。", "無駄": "意味：勧める文脈で「無駄」は矛盾する。", "賑やか": "連語：「構築が賑やかです」とは言わない。"}, "sentence_index": 0, "correct_answer": "有効"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時間を有効で使いたいと思っている。", "explanation": "活用の誤り：動詞を修飾するときは「有効に」。"}, {"text": "時間を有効な使いたいと思っている。", "explanation": "活用の誤り：「有効な」は名詞を修飾する形で、動詞の前には「有効に」。"}, {"text": "時間を有効に無駄にしたいと思っている。", "explanation": "意味の誤り：「有効に」と「無駄にする」は矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38763, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日の復習は暗記にとても有効い。", "corrected_sentence": "毎日の復習は暗記にとても有効だ。", "error_description": "活用の誤り：「有効」はな形容詞なので「有効だ」。い形容詞のように「有効い」とはしない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "有効", "is_correct": true, "explanation": "「性」が付いて名詞「有効性」になるので語幹のまま。"}, {"text": "有効な", "is_correct": false, "explanation": "「有効な性」とは言わない。連体形は名詞化の接尾辞と結びつかない。"}, {"text": "有効に", "is_correct": false, "explanation": "連用形「有効に」は動詞を修飾する形で、「性」の前に置けない。"}, {"text": "有効だった", "is_correct": false, "explanation": "過去形は文を終える形で、「性」に続かない。"}], "correct_form": "有効", "base_form": "有効", "form_label": "語幹", "sentence_index": 1, "explanations": {"有効": "「性」が付いて名詞「有効性」になるので語幹のまま。", "有効な": "「有効な性」とは言わない。連体形は名詞化の接尾辞と結びつかない。", "有効に": "連用形「有効に」は動詞を修飾する形で、「性」の前に置けない。", "有効だった": "過去形は文を終える形で、「性」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38763, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無効", "is_correct": true, "explanation": "効き目がない、役に立たないことで「有効」の対義。"}, {"text": "有利", "is_correct": false, "explanation": "得になることで、対義は「不利」。"}, {"text": "重要", "is_correct": false, "explanation": "大切なことで、対義ではない。"}, {"text": "有名", "is_correct": false, "explanation": "よく知られていることで、対義ではない。"}], "correct_answer": "無効", "explanations": {"無効": "効き目がない、役に立たないことで「有効」の対義。", "有利": "得になることで、対義は「不利」。", "重要": "大切なことで、対義ではない。", "有名": "よく知られていることで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38763, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有効", "is_correct": true, "explanation": "「ゆうこう」と読む。正解。"}, {"text": "優等", "is_correct": false, "explanation": "「ゆうとう」。三拍目が「と」。"}, {"text": "郵送", "is_correct": false, "explanation": "「ゆうそう」。三拍目が「そ」。"}, {"text": "遊興", "is_correct": false, "explanation": "「ゆうきょう」。三拍目が「きょ」。"}, {"text": "憂国", "is_correct": false, "explanation": "「ゆうこく」。最後の拍が「く」。"}], "explanations": {"有効": "「ゆうこう」と読む。正解。", "優等": "「ゆうとう」。三拍目が「と」。", "郵送": "「ゆうそう」。三拍目が「そ」。", "遊興": "「ゆうきょう」。三拍目が「きょ」。", "憂国": "「ゆうこく」。最後の拍が「く」。"}, "sentence_index": null, "correct_answer": "有効"}, "level_3": {"options": [{"text": "有効", "is_correct": true, "explanation": "ストレスを減らす効果があるので正しい。"}, {"text": "不利", "is_correct": false, "explanation": "意味：運動の効果を述べる文で「不利」は逆の意味になる。"}, {"text": "丁寧", "is_correct": false, "explanation": "連語：「減らすのに丁寧です」とは言わない。"}, {"text": "退屈", "is_correct": false, "explanation": "意味：「退屈」は効果を表さず文脈に合わない。"}], "explanations": {"有効": "ストレスを減らす効果があるので正しい。", "不利": "意味：運動の効果を述べる文で「不利」は逆の意味になる。", "丁寧": "連語：「減らすのに丁寧です」とは言わない。", "退屈": "意味：「退屈」は効果を表さず文脈に合わない。"}, "sentence_index": 6, "correct_answer": "有効"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地図アプリは旅行で有効が使える。", "explanation": "助詞・活用の誤り：「使える」を修飾するには「有効に」。"}, {"text": "地図アプリは旅行で有効く使える。", "explanation": "活用の誤り：「有効」はな形容詞で、い形容詞のように「有効く」とはしない。"}, {"text": "地図アプリは有効な旅行で使える。", "explanation": "係り受けの誤り：「有効」がアプリの使い方でなく旅行を修飾してしまう。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38763, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "もっと有効の方法を考えてみよう。", "corrected_sentence": "もっと有効な方法を考えてみよう。", "error_description": "活用の誤り：な形容詞が名詞を修飾するときは「有効な」。「有効の」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "有効", "is_correct": true, "explanation": "後ろに「だった」があるので語幹のまま。"}, {"text": "有効な", "is_correct": false, "explanation": "「有効なだった」は連体形と過去が重なり非文。"}, {"text": "有効に", "is_correct": false, "explanation": "「有効にだった」は連用形のあとに「だった」が続かず非文。"}, {"text": "有効で", "is_correct": false, "explanation": "「有効でだった」は接続形のあとに「だった」が続かず非文。"}], "correct_form": "有効", "base_form": "有効", "form_label": "語幹", "sentence_index": 7, "explanations": {"有効": "後ろに「だった」があるので語幹のまま。", "有効な": "「有効なだった」は連体形と過去が重なり非文。", "有効に": "「有効にだった」は連用形のあとに「だった」が続かず非文。", "有効で": "「有効でだった」は接続形のあとに「だった」が続かず非文。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (38763, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無効", "is_correct": true, "explanation": "効果がないこと。「有効」の反対。"}, {"text": "便利", "is_correct": false, "explanation": "使いやすいこと。対義ではない。"}, {"text": "確実", "is_correct": false, "explanation": "まちがいないこと。対義ではない。"}, {"text": "適切", "is_correct": false, "explanation": "ふさわしいこと。意味は近いが対義ではない。"}], "correct_answer": "無効", "explanations": {"無効": "効果がないこと。「有効」の反対。", "便利": "使いやすいこと。対義ではない。", "確実": "まちがいないこと。対義ではない。", "適切": "ふさわしいこと。意味は近いが対義ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35177, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伝える", "is_correct": true, "explanation": "「つたえる」。正解。"}, {"text": "称える", "is_correct": false, "explanation": "「たたえる」。一拍目「つ」が「た」に変わる一モーラ差。"}, {"text": "仕える", "is_correct": false, "explanation": "「つかえる」。二拍目「た」が「か」に変わる一モーラ差。"}, {"text": "伝わる", "is_correct": false, "explanation": "「つたわる」。三拍目「え」が「わ」に変わる一モーラ差。"}], "explanations": {"伝える": "「つたえる」。正解。", "称える": "「たたえる」。一拍目「つ」が「た」に変わる一モーラ差。", "仕える": "「つかえる」。二拍目「た」が「か」に変わる一モーラ差。", "伝わる": "「つたわる」。三拍目「え」が「わ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "伝える"}, "level_3": {"options": [{"text": "伝える", "is_correct": true, "explanation": "商品の魅力を人に知らせる写真なので正しい。"}, {"text": "隠す", "is_correct": false, "explanation": "意味：魅力を隠す写真は成功の鍵にならない。"}, {"text": "忘れる", "is_correct": false, "explanation": "連語：「魅力を忘れる写真」は不自然。"}, {"text": "断る", "is_correct": false, "explanation": "項構造：「魅力を断る」とは言わない。"}], "explanations": {"伝える": "商品の魅力を人に知らせる写真なので正しい。", "隠す": "意味：魅力を隠す写真は成功の鍵にならない。", "忘れる": "連語：「魅力を忘れる写真」は不自然。", "断る": "項構造：「魅力を断る」とは言わない。"}, "sentence_index": 0, "correct_answer": "伝える"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "気持ちを言葉に伝えるのは難しい。", "explanation": "助詞の混同：手段は「で」。「言葉に」では意味が通らない。"}, {"text": "気持ちが言葉で伝えるのは難しい。", "explanation": "助詞の混同：他動詞「伝える」の目的語は「を」。"}, {"text": "気持ちを言葉で伝わるのは難しい。", "explanation": "自他の誤り：「を」を取るのは他動詞「伝える」。「伝わる」は自動詞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35177, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生を休むことを伝える。", "corrected_sentence": "先生に休むことを伝える。", "error_description": "助詞の混同：知らせる相手は「に」で示す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "伝える", "is_correct": true, "explanation": "名詞「記号」を修飾する現在の連体形。"}, {"text": "伝えて", "is_correct": false, "explanation": "て形は名詞を直接修飾できない。"}, {"text": "伝えよう", "is_correct": false, "explanation": "意向形は名詞を修飾する形として不自然。"}, {"text": "伝えれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できない。"}], "correct_form": "伝える", "base_form": "伝える", "form_label": "活用", "sentence_index": 1, "explanations": {"伝える": "名詞「記号」を修飾する現在の連体形。", "伝えて": "て形は名詞を直接修飾できない。", "伝えよう": "意向形は名詞を修飾する形として不自然。", "伝えれば": "仮定形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35177, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「伝える」の目的語「メッセージ」を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、「伝える」の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "相手を表す助詞で、伝える内容は示せない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、目的語の位置では非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「伝える」の目的語「メッセージ」を示す。", "が": "主格になり、「伝える」の目的語にならない。", "に": "相手を表す助詞で、伝える内容は示せない。", "で": "手段を表し、目的語の位置では非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35177, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伝える", "is_correct": true, "explanation": "「つたえる」と読む。正解。"}, {"text": "支える", "is_correct": false, "explanation": "「ささえる」。一・二拍目が異なる。"}, {"text": "叶える", "is_correct": false, "explanation": "「かなえる」。一・二拍目が異なる。"}, {"text": "伝わる", "is_correct": false, "explanation": "「つたわる」。三拍目が「わ」。"}], "explanations": {"伝える": "「つたえる」と読む。正解。", "支える": "「ささえる」。一・二拍目が異なる。", "叶える": "「かなえる」。一・二拍目が異なる。", "伝わる": "「つたわる」。三拍目が「わ」。"}, "sentence_index": null, "correct_answer": "伝える"}, "level_3": {"options": [{"text": "伝え", "is_correct": true, "explanation": "理由を友だちに知らせなかったので正しい。"}, {"text": "洗わ", "is_correct": false, "explanation": "連語：「理由を洗う」とは言わない。"}, {"text": "走ら", "is_correct": false, "explanation": "項構造：「走る」は「理由を」を目的語に取らない。"}, {"text": "植え", "is_correct": false, "explanation": "意味：理由を植えることはできない。"}], "explanations": {"伝え": "理由を友だちに知らせなかったので正しい。", "洗わ": "連語：「理由を洗う」とは言わない。", "走ら": "項構造：「走る」は「理由を」を目的語に取らない。", "植え": "意味：理由を植えることはできない。"}, "sentence_index": 6, "correct_answer": "伝え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大事な話は早めに伝えるている。", "explanation": "活用の誤り：「いる」の前はて形「伝えて」。"}, {"text": "大事な話は早めに伝わせている。", "explanation": "語形の誤り：「伝える」は他動詞で、「伝わせる」とは言わない。"}, {"text": "大事な話は早めに伝えて、だれにも知らせていない。", "explanation": "意味の誤り：伝えたのに誰にも知らせていないのは矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35177, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼にこのニュースを伝えるてください。", "corrected_sentence": "彼にこのニュースを伝えてください。", "error_description": "活用の誤り：「ください」の前はて形「伝えて」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "伝える", "is_correct": true, "explanation": "名詞「力」を修飾する連体形。"}, {"text": "伝えて", "is_correct": false, "explanation": "て形では「力」に続かない。"}, {"text": "伝えれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できない。"}, {"text": "伝えろ", "is_correct": false, "explanation": "命令形は名詞を修飾できない。"}], "correct_form": "伝える", "base_form": "伝える", "form_label": "活用", "sentence_index": 7, "explanations": {"伝える": "名詞「力」を修飾する連体形。", "伝えて": "て形では「力」に続かない。", "伝えれば": "仮定形は名詞を修飾できない。", "伝えろ": "命令形は名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35177, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「社会」は大切さが成り立つ場なので「で」。"}, {"text": "を", "is_correct": false, "explanation": "目的語の助詞で、「大切だ」と結びつかない。"}, {"text": "が", "is_correct": false, "explanation": "「社会が大切だ」となり、別の意味になる上に「力は」と主語が重なる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、場を示せない。"}], "correct_answer": "で", "explanations": {"で": "「社会」は大切さが成り立つ場なので「で」。", "を": "目的語の助詞で、「大切だ」と結びつかない。", "が": "「社会が大切だ」となり、別の意味になる上に「力は」と主語が重なる。", "へ": "方向を表し、場を示せない。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41347, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "延いては", "is_correct": true, "explanation": "「ひいては」。正解。"}, {"text": "吹いては", "is_correct": false, "explanation": "「ふいては」。一拍目「ひ」が「ふ」に変わる一モーラ差。"}, {"text": "書いては", "is_correct": false, "explanation": "「かいては」。一拍目「ひ」が「か」に変わる一モーラ差。"}, {"text": "置いては", "is_correct": false, "explanation": "「おいては」。一拍目「ひ」が「お」に変わる一モーラ差。"}, {"text": "引いても", "is_correct": false, "explanation": "「ひいても」。最後の拍「は」が「も」に変わる一モーラ差。"}], "explanations": {"延いては": "「ひいては」。正解。", "吹いては": "「ふいては」。一拍目「ひ」が「ふ」に変わる一モーラ差。", "書いては": "「かいては」。一拍目「ひ」が「か」に変わる一モーラ差。", "置いては": "「おいては」。一拍目「ひ」が「お」に変わる一モーラ差。", "引いても": "「ひいても」。最後の拍「は」が「も」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "延いては"}, "level_3": {"options": [{"text": "ひいては", "is_correct": true, "explanation": "機能の補完がさらに地域全体へと広がることを表す。"}, {"text": "決して", "is_correct": false, "explanation": "連語：「決して」は否定と結びつき、肯定文に合わない。"}, {"text": "まるで", "is_correct": false, "explanation": "連語：「まるで」は「ようだ」を伴う比喩で、ここでは成り立たない。"}, {"text": "かつて", "is_correct": false, "explanation": "意味：過去を表し、「向上させる原動力となり得る」と合わない。"}], "explanations": {"ひいては": "機能の補完がさらに地域全体へと広がることを表す。", "決して": "連語：「決して」は否定と結びつき、肯定文に合わない。", "まるで": "連語：「まるで」は「ようだ」を伴う比喩で、ここでは成り立たない。", "かつて": "意味：過去を表し、「向上させる原動力となり得る」と合わない。"}, "sentence_index": 0, "correct_answer": "ひいては"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "町が育ち、ひいては国も弱くなる。", "explanation": "意味の誤り：「ひいては」は前の事柄が同じ方向に広がる結果を導く。町の成長から国の衰えは続かない。"}, {"text": "ひいては町が育ち、国も強くなる。", "explanation": "語順の誤り：「ひいては」は前の事柄を受けて後に来る結果の前に置く。"}, {"text": "町が育ち、ひいて国も強くなる。", "explanation": "語形の誤り：副詞は「ひいては」の形で使い、「は」を落とせない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41347, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自分を守り、ひいてには家族を守る。", "corrected_sentence": "自分を守り、ひいては家族を守る。", "error_description": "語形の誤り：「ひいては」が固定の形で、「ひいてには」とは言わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
