INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41347, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "延いては", "is_correct": true, "explanation": "「ひいては」と読む。正解。"}, {"text": "強いては", "is_correct": false, "explanation": "「しいては」。最初の拍が「し」。"}, {"text": "剥いては", "is_correct": false, "explanation": "「むいては」。最初の拍が「む」。"}, {"text": "聞いては", "is_correct": false, "explanation": "「きいては」。最初の拍が「き」。"}, {"text": "拭いては", "is_correct": false, "explanation": "「ふいては」。最初の拍が「ふ」。"}], "explanations": {"延いては": "「ひいては」と読む。正解。", "強いては": "「しいては」。最初の拍が「し」。", "剥いては": "「むいては」。最初の拍が「む」。", "聞いては": "「きいては」。最初の拍が「き」。", "拭いては": "「ふいては」。最初の拍が「ふ」。"}, "sentence_index": null, "correct_answer": "延いては"}, "level_3": {"options": [{"text": "ひいては", "is_correct": true, "explanation": "ごみを減らすことが、さらに地球を守ることにつながる。"}, {"text": "めったに", "is_correct": false, "explanation": "連語：「めったに」は否定を伴い、肯定文に合わない。"}, {"text": "ちっとも", "is_correct": false, "explanation": "連語：「ちっとも」も否定を伴う語で、ここでは非文。"}, {"text": "まるで", "is_correct": false, "explanation": "連語：比喩の「ようだ」がなく成り立たない。"}], "explanations": {"ひいては": "ごみを減らすことが、さらに地球を守ることにつながる。", "めったに": "連語：「めったに」は否定を伴い、肯定文に合わない。", "ちっとも": "連語：「ちっとも」も否定を伴う語で、ここでは非文。", "まるで": "連語：比喩の「ようだ」がなく成り立たない。"}, "sentence_index": 6, "correct_answer": "ひいては"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小さな親切がひいては町を暗くする。", "explanation": "意味の誤り：「ひいては」は前の良い事柄が広がる結果を導く。親切から町が暗くなるのは続かない。"}, {"text": "ひいては小さな親切が町を明るくする。", "explanation": "語順の誤り：「ひいては」は前の事柄を受けるので文頭に置けない。"}, {"text": "小さな親切がひいても町を明るくする。", "explanation": "語形の誤り：副詞は「ひいては」。「ひいても」では意味が変わる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (41347, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一人の努力がひいてに皆を助ける。", "corrected_sentence": "一人の努力がひいては皆を助ける。", "error_description": "語形の誤り：副詞は「ひいては」。「ひいてに」とは言わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
