INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36361, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「ちつじょ」。正解。"}, {"text": "長女", "is_correct": false, "explanation": "「ちょうじょ」。音は近いが一拍目と二拍目が異なる。"}, {"text": "地上", "is_correct": false, "explanation": "「ちじょう」。音は近いが拍の並びが異なる。"}, {"text": "蟄居", "is_correct": false, "explanation": "「ちっきょ」。二拍目が促音、三拍目が「きょ」。"}], "explanations": {"秩序": "「ちつじょ」。正解。", "長女": "「ちょうじょ」。音は近いが一拍目と二拍目が異なる。", "地上": "「ちじょう」。音は近いが拍の並びが異なる。", "蟄居": "「ちっきょ」。二拍目が促音、三拍目が「きょ」。"}, "sentence_index": null, "correct_answer": "秩序"}, "level_3": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「無秩序な拡大」で、決まりなく広がる様子を表す。"}, {"text": "平和", "is_correct": false, "explanation": "連語：「無平和」という語はない。"}, {"text": "順番", "is_correct": false, "explanation": "連語：「無順番」という語はない。"}, {"text": "整頓", "is_correct": false, "explanation": "連語：「無整頓」という語はない。"}], "explanations": {"秩序": "「無秩序な拡大」で、決まりなく広がる様子を表す。", "平和": "連語：「無平和」という語はない。", "順番": "連語：「無順番」という語はない。", "整頓": "連語：「無整頓」という語はない。"}, "sentence_index": 0, "correct_answer": "秩序"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社会の秩序を乱れている。", "explanation": "助詞の混同：自動詞「乱れる」の主語は「が」。"}, {"text": "社会の秩序が散らかっている。", "explanation": "連語の誤り：「散らかる」は物に使い、「秩序」には「乱れる」。"}, {"text": "社会の秩序がうるさくなっている。", "explanation": "連語の誤り：「秩序」は音の性質を持たず「うるさい」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36361, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校の秩序に守るのは大切だ。", "corrected_sentence": "学校の秩序を守るのは大切だ。", "error_description": "助詞の混同：「守る」の目的語は「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36361, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「介する」の目的語「フィードバック」を示す。"}, {"text": "が", "is_correct": false, "explanation": "主格になり、「介した」の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "対象を表す助詞で、「介する」とは結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表すが、「〜で介した」は非文。"}], "correct_answer": "を", "explanations": {"を": "「介する」の目的語「フィードバック」を示す。", "が": "主格になり、「介した」の目的語にならない。", "に": "対象を表す助詞で、「介する」とは結びつかない。", "で": "手段を表すが、「〜で介した」は非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "混乱", "is_correct": true, "explanation": "物事が入り乱れてまとまらない状態で、「秩序」の対義。"}, {"text": "規則", "is_correct": false, "explanation": "決まりのことで、秩序を支えるものであり対義ではない。"}, {"text": "平和", "is_correct": false, "explanation": "争いのない状態で、対義ではない。"}, {"text": "安全", "is_correct": false, "explanation": "危険がないことで、対義ではない。"}], "correct_answer": "混乱", "explanations": {"混乱": "物事が入り乱れてまとまらない状態で、「秩序」の対義。", "規則": "決まりのことで、秩序を支えるものであり対義ではない。", "平和": "争いのない状態で、対義ではない。", "安全": "危険がないことで、対義ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36361, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "秩序", "is_correct": true, "explanation": "「ちつじょ」と読む。正解。"}, {"text": "地上", "is_correct": false, "explanation": "「ちじょう」。二拍目に「つ」がない。"}, {"text": "次女", "is_correct": false, "explanation": "「じじょ」。音の並びが異なる。"}, {"text": "実情", "is_correct": false, "explanation": "「じつじょう」。最初が濁り、最後が長音。"}], "explanations": {"秩序": "「ちつじょ」と読む。正解。", "地上": "「ちじょう」。二拍目に「つ」がない。", "次女": "「じじょ」。音の並びが異なる。", "実情": "「じつじょう」。最初が濁り、最後が長音。"}, "sentence_index": null, "correct_answer": "秩序"}, "level_3": {"options": [{"text": "秩序", "is_correct": true, "explanation": "決まりが守られた教室は勉強しやすい。"}, {"text": "騒音", "is_correct": false, "explanation": "意味：騒音のある教室は勉強しにくく、文意と矛盾する。"}, {"text": "混乱", "is_correct": false, "explanation": "意味：混乱のある教室は勉強しやすくない。"}, {"text": "欠点", "is_correct": false, "explanation": "連語：「欠点のある教室は勉強しやすい」は意味が通らない。"}], "explanations": {"秩序": "決まりが守られた教室は勉強しやすい。", "騒音": "意味：騒音のある教室は勉強しにくく、文意と矛盾する。", "混乱": "意味：混乱のある教室は勉強しやすくない。", "欠点": "連語：「欠点のある教室は勉強しやすい」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "秩序"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秩序をない集団はまとまらない。", "explanation": "助詞の混同：「ない」の主語は「が」。"}, {"text": "秩序がない集団はよくまとまる。", "explanation": "意味の誤り：秩序がなければ集団はまとまらない。"}, {"text": "秩序がいない集団はまとまらない。", "explanation": "語の誤り：「秩序」は無生物なので「いる」でなく「ある」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36361, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察は町の秩序が守っている。", "corrected_sentence": "警察は町の秩序を守っている。", "error_description": "助詞の混同：「秩序」は「守る」の目的語なので「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36361, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「作る」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「秩序が作っていこう」では秩序が行為者になり非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、作る物を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「作る」の目的語を示す。", "が": "「秩序が作っていこう」では秩序が行為者になり非文。", "に": "着点を表し、作る物を示せない。", "へ": "方向を表し、目的語にならない。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "混沌", "is_correct": true, "explanation": "すべてが入りまじり区別のない状態で、「秩序」の反対。"}, {"text": "規律", "is_correct": false, "explanation": "決まりのこと。秩序に近く、反対ではない。"}, {"text": "調和", "is_correct": false, "explanation": "よくつり合うこと。反対ではない。"}, {"text": "安定", "is_correct": false, "explanation": "落ち着いていること。反対ではない。"}], "correct_answer": "混沌", "explanations": {"混沌": "すべてが入りまじり区別のない状態で、「秩序」の反対。", "規律": "決まりのこと。秩序に近く、反対ではない。", "調和": "よくつり合うこと。反対ではない。", "安定": "落ち着いていること。反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37911, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "創出", "is_correct": true, "explanation": "「そうしゅつ」。正解。"}, {"text": "喪失", "is_correct": false, "explanation": "「そうしつ」。三拍目「しゅ」が「し」に変わる一モーラ差。"}, {"text": "槍術", "is_correct": false, "explanation": "「そうじゅつ」。三拍目が濁音になる清濁の差。"}, {"text": "漏出", "is_correct": false, "explanation": "「ろうしゅつ」。一拍目「そ」が「ろ」に変わる一モーラ差。"}, {"text": "早秋", "is_correct": false, "explanation": "「そうしゅう」。最後の拍「つ」が「う」に変わる一モーラ差。"}], "explanations": {"創出": "「そうしゅつ」。正解。", "喪失": "「そうしつ」。三拍目「しゅ」が「し」に変わる一モーラ差。", "槍術": "「そうじゅつ」。三拍目が濁音になる清濁の差。", "漏出": "「ろうしゅつ」。一拍目「そ」が「ろ」に変わる一モーラ差。", "早秋": "「そうしゅう」。最後の拍「つ」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "創出"}, "level_3": {"options": [{"text": "創出", "is_correct": true, "explanation": "住民の参加で新しく作り出されるガーデンなので正しい。"}, {"text": "破壊", "is_correct": false, "explanation": "意味：壊されたガーデンが好影響を及ぼすのは矛盾する。"}, {"text": "削除", "is_correct": false, "explanation": "連語：「ガーデンを削除する」とは言わない。"}, {"text": "輸出", "is_correct": false, "explanation": "意味：ガーデンを輸出することはできない。"}], "explanations": {"創出": "住民の参加で新しく作り出されるガーデンなので正しい。", "破壊": "意味：壊されたガーデンが好影響を及ぼすのは矛盾する。", "削除": "連語：「ガーデンを削除する」とは言わない。", "輸出": "意味：ガーデンを輸出することはできない。"}, "sentence_index": 0, "correct_answer": "創出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雇用を創出が大きな目標だ。", "explanation": "助詞の混同：名詞をつなぐのは「の」。"}, {"text": "雇用の創出を大きな目標だ。", "explanation": "助詞の混同：「目標だ」の主語は「が」。"}, {"text": "雇用の創出しが大きな目標だ。", "explanation": "語形の誤り：名詞「創出」に「し」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
