INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37911, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "創出", "is_correct": true, "explanation": "「そうしゅつ」と読む。正解。"}, {"text": "抽出", "is_correct": false, "explanation": "「ちゅうしゅつ」。最初の拍が「ちゅ」。"}, {"text": "総数", "is_correct": false, "explanation": "「そうすう」。後半が「すう」。"}, {"text": "相続", "is_correct": false, "explanation": "「そうぞく」。後半が「ぞく」。"}, {"text": "消失", "is_correct": false, "explanation": "「しょうしつ」。最初が「しょ」。"}], "explanations": {"創出": "「そうしゅつ」と読む。正解。", "抽出": "「ちゅうしゅつ」。最初の拍が「ちゅ」。", "総数": "「そうすう」。後半が「すう」。", "相続": "「そうぞく」。後半が「ぞく」。", "消失": "「しょうしつ」。最初が「しょ」。"}, "sentence_index": null, "correct_answer": "創出"}, "level_3": {"options": [{"text": "創出", "is_correct": true, "explanation": "観光で地域に新しく活気を生み出したいので正しい。"}, {"text": "削減", "is_correct": false, "explanation": "意味：活気を減らしたいという内容になり矛盾する。"}, {"text": "処分", "is_correct": false, "explanation": "連語：「活気を処分する」とは言わない。"}, {"text": "禁止", "is_correct": false, "explanation": "意味：活気を禁止するのは文意に合わない。"}], "explanations": {"創出": "観光で地域に新しく活気を生み出したいので正しい。", "削減": "意味：活気を減らしたいという内容になり矛盾する。", "処分": "連語：「活気を処分する」とは言わない。", "禁止": "意味：活気を禁止するのは文意に合わない。"}, "sentence_index": 6, "correct_answer": "創出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "みんなで新しい祭りが創出できる。", "explanation": "助詞の混同：作り出す物は「を」。"}, {"text": "みんなで昔からある祭りを創出できる。", "explanation": "意味の誤り：「創出」は新しく作り出すことで、昔からある物には使えない。"}, {"text": "みんなで新しい祭りを創出られる。", "explanation": "活用の誤り：「創出する」の可能形は「創出できる」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0285cf16-08a9-41f4-a40e-cb0f3b087b25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
