INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36007, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "録音や録画した音や映像をもう一度流すこと。", "primary_collocate": null, "pronunciation": "さいせい", "ipa": "sai.seː", "syllable_count": 4, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせい", "sentence_source": "mined"}, {"text": "再生可能エネルギーの導入加速にもかかわらず、製造プロセスの性質上、炭素発生をゼロ化し得ない領域において、CCUSは極めて重要な役割を担う。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせい", "sentence_source": "mined"}, {"text": "動画の再生が急に止まった。", "target_word": "再生", "complexity_tier": "T3", "furigana": "どうが さいせい きゅう と", "sentence_source": "generated"}, {"text": "ボタンを押して再生してください。", "target_word": "再生", "complexity_tier": "T3", "furigana": "お さいせい", "sentence_source": "generated"}, {"text": "この曲の再生回数はとても多い。", "target_word": "再生", "complexity_tier": "T3", "furigana": "きょく さいせい かいすう おお", "sentence_source": "generated"}, {"text": "録音した声を再生して聞いた。", "target_word": "再生", "complexity_tier": "T3", "furigana": "ろくおん こえ さいせい き", "sentence_source": "generated"}, {"text": "再生中に画面が暗くなった。", "target_word": "再生", "complexity_tier": "T3", "furigana": "さいせいちゅう がめん くら", "sentence_source": "generated"}, {"text": "先生がビデオを再生している。", "target_word": "再生", "complexity_tier": "T3", "furigana": "せんせい さいせい", "sentence_source": "generated"}, {"text": "もう一度最初から再生しよう。", "target_word": "再生", "complexity_tier": "T3", "furigana": "いちど さいしょ さいせい", "sentence_source": "generated"}, {"text": "このアプリは音楽の再生ができる。", "target_word": "再生", "complexity_tier": "T3", "furigana": "おんがく さいせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "再生する", "label": "活用"}, {"form": "再生した", "label": "活用"}, {"form": "再生ボタン", "label": "派生"}, {"form": "再生回数", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 録音・録画をもう一度流すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218b857b-b33b-43e8-b706-8702edae4cb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53168, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "同じ地域や同じ関心を持つ人々が交流し合う集団。", "primary_collocate": null, "pronunciation": "こみゅにてぃ", "ipa": "ko.mʲɯ.ni.tʲi", "syllable_count": 4, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "こみゅにてぃ", "sentence_source": "mined"}, {"text": "コンクリートの打ちっぱなしという素材感を活かした設計は、入居者のコミュニティ形成に多大な社会的影響を与えました。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "こみゅにてぃ", "sentence_source": "mined"}, {"text": "町のコミュニティに参加した。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "まち さんか", "sentence_source": "generated"}, {"text": "このコミュニティはとても温かい。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "あたた", "sentence_source": "generated"}, {"text": "ネットのコミュニティで友達ができた。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "ともだち", "sentence_source": "generated"}, {"text": "コミュニティの集まりが毎月ある。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "あつ まいつき", "sentence_source": "generated"}, {"text": "新しいコミュニティを作りたい。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "あたら つく", "sentence_source": "generated"}, {"text": "祖父は地元のコミュニティで働く。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "そふ じもと はたら", "sentence_source": "generated"}, {"text": "コミュニティが小さくなっている。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "ちい", "sentence_source": "generated"}, {"text": "みんなでコミュニティを支えている。", "target_word": "コミュニティ", "complexity_tier": "T3", "furigana": "ささ", "sentence_source": "generated"}], "morphological_forms": [{"form": "コミュニティー", "label": "派生"}, {"form": "地域コミュニティ", "label": "派生"}, {"form": "オンラインコミュニティ", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 交流し合う人々の集団", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)','sentence 1 above tier T2: contains vocabulary far above tier T2: 打ちっぱなし (Zipf 2.18)']::text[], '218b857b-b33b-43e8-b706-8702edae4cb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある物事の、特定の部分や見方。", "primary_collocate": null, "pronunciation": "そくめん", "ipa": "so.kɯ.meɴ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん", "sentence_source": "mined"}, {"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん", "sentence_source": "mined"}, {"text": "彼には優しい側面もある。", "target_word": "側面", "complexity_tier": "T3", "furigana": "かれ やさ そくめん", "sentence_source": "generated"}, {"text": "この問題には二つの側面がある。", "target_word": "側面", "complexity_tier": "T3", "furigana": "もんだい ふた そくめん", "sentence_source": "generated"}, {"text": "別の側面から考えてみよう。", "target_word": "側面", "complexity_tier": "T3", "furigana": "べつ そくめん かんが", "sentence_source": "generated"}, {"text": "経済的な側面が大切だ。", "target_word": "側面", "complexity_tier": "T3", "furigana": "けいざいてき そくめん たいせつ", "sentence_source": "generated"}, {"text": "その側面は見落とされていた。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん みお", "sentence_source": "generated"}, {"text": "新しい側面を知って驚いた。", "target_word": "側面", "complexity_tier": "T3", "furigana": "あたら そくめん し おどろ", "sentence_source": "generated"}, {"text": "社会の側面について話し合う。", "target_word": "側面", "complexity_tier": "T3", "furigana": "しゃかい そくめん はな あ", "sentence_source": "generated"}, {"text": "どの側面を重視するかが問題だ。", "target_word": "側面", "complexity_tier": "T3", "furigana": "そくめん じゅうし もんだい", "sentence_source": "generated"}], "morphological_forms": [{"form": "側面的", "label": "派生"}, {"form": "側面から", "label": "派生"}, {"form": "一側面", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事の一部分や一つの見方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 6 words above tier T3 (max 3): オペレーション (Zipf 3.24), 量的 (Zipf 3.1), とどまら (Zipf 3.23), 歪曲 (Zipf 3.06), せしめる (Zipf 2.46), 孕ん (Zipf 2.81)']::text[], '218b857b-b33b-43e8-b706-8702edae4cb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39111, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他のものと比べて、特に目立つ性質や点。", "primary_collocate": null, "pronunciation": "とくちょう", "ipa": "to.kɯ.tɕoː", "syllable_count": 4, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "とくちょう", "sentence_source": "mined"}, {"text": "次いで、分岐や終点といった特徴点の配列を精密に分析する。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "とくちょう", "sentence_source": "mined"}, {"text": "この町の特徴は古い寺だ。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "まち とくちょう ふる てら", "sentence_source": "generated"}, {"text": "彼の声には特徴がある。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "かれ こえ とくちょう", "sentence_source": "generated"}, {"text": "犬の特徴を絵にかいた。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "いぬ とくちょう え", "sentence_source": "generated"}, {"text": "特徴のある字を書く人だ。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "とくちょう じ か ひと", "sentence_source": "generated"}, {"text": "その鳥の特徴を調べている。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "とり とくちょう しら", "sentence_source": "generated"}, {"text": "大きな目が特徴の人形だ。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "おお め とくちょう にんぎょう", "sentence_source": "generated"}, {"text": "特徴をつかむのが上手だ。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "とくちょう じょうず", "sentence_source": "generated"}, {"text": "この料理の特徴は辛さだ。", "target_word": "特徴", "complexity_tier": "T3", "furigana": "りょうり とくちょう から", "sentence_source": "generated"}], "morphological_forms": [{"form": "特徴的", "label": "派生"}, {"form": "特徴づける", "label": "派生"}, {"form": "特徴点", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 他と比べて目立つ性質や点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218b857b-b33b-43e8-b706-8702edae4cb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35529, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある範囲の土地や場所。", "primary_collocate": null, "pronunciation": "ちいき", "ipa": "tɕi.i.ki", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき", "sentence_source": "mined"}, {"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき", "sentence_source": "mined"}, {"text": "彼がこれらを大切に育てる理由は、地域の子供たちに安全な給食を安定的に提供するためだ。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき", "sentence_source": "mined"}, {"text": "この地域は雪が多い。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ゆき おお", "sentence_source": "generated"}, {"text": "地域の祭りに行った。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき まつ い", "sentence_source": "generated"}, {"text": "寒い地域で育った。", "target_word": "地域", "complexity_tier": "T3", "furigana": "さむ ちいき そだ", "sentence_source": "generated"}, {"text": "地域によって言葉が違う。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ことば ちが", "sentence_source": "generated"}, {"text": "その地域には川がある。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき かわ", "sentence_source": "generated"}, {"text": "地域の人と掃除をした。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ひと そうじ", "sentence_source": "generated"}, {"text": "山の多い地域に住んでいる。", "target_word": "地域", "complexity_tier": "T3", "furigana": "やま おお ちいき す", "sentence_source": "generated"}], "morphological_forms": [{"form": "地域的", "label": "派生"}, {"form": "地域社会", "label": "派生"}, {"form": "地域差", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 一定の範囲の土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 4 words above tier T1 (max 2): 無秩序 (Zipf 2.99), 希薄 (Zipf 3.22), 歯止め (Zipf 3.18), 顕在 (Zipf 3.05)','sentence 1 above tier T1: 7 words above tier T1 (max 2): 緑地 (Zipf 3.09), 生態 (Zipf 3.81), 回廊 (Zipf 3.11), 補完 (Zipf 3.71), ひいては (Zipf 3.24), リテラシー (Zipf 3.08)']::text[], '218b857b-b33b-43e8-b706-8702edae4cb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37453, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "足りない部分を補って、完全にすること。", "primary_collocate": null, "pronunciation": "ほかん", "ipa": "ho.kaɴ", "syllable_count": 3, "sentences": [{"text": "既存の緑地と有機的にネットワークを形成することで生態系の回廊としての機能を補完し、ひいては地域全体の環境リテラシーを向上させる原動力となり得るのである。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん", "sentence_source": "mined"}, {"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん", "sentence_source": "mined"}, {"text": "二人は互いに補完している。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ふたり たが ほかん", "sentence_source": "generated"}, {"text": "足りない情報を補完した。", "target_word": "補完", "complexity_tier": "T3", "furigana": "た じょうほう ほかん", "sentence_source": "generated"}, {"text": "この本は授業を補完する。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほん じゅぎょう ほかん", "sentence_source": "generated"}, {"text": "補完の役目を果たす道具だ。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん やくめ は どうぐ", "sentence_source": "generated"}, {"text": "データの補完が必要だ。", "target_word": "補完", "complexity_tier": "T3", "furigana": "ほかん ひつよう", "sentence_source": "generated"}, {"text": "弱い点を補完し合おう。", "target_word": "補完", "complexity_tier": "T3", "furigana": "よわ てん ほかん あ", "sentence_source": "generated"}, {"text": "説明の補完として図を使う。", "target_word": "補完", "complexity_tier": "T3", "furigana": "せつめい ほかん ず つか", "sentence_source": "generated"}, {"text": "先生の話を本で補完する。", "target_word": "補完", "complexity_tier": "T3", "furigana": "せんせい はなし ほん ほかん", "sentence_source": "generated"}], "morphological_forms": [{"form": "補完する", "label": "活用"}, {"form": "補完した", "label": "活用"}, {"form": "補完し合う", "label": "派生"}, {"form": "補完的", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 足りない所を補い完全にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 緑地 (Zipf 3.09), 回廊 (Zipf 3.11), ひいては (Zipf 3.24), リテラシー (Zipf 3.08)']::text[], '218b857b-b33b-43e8-b706-8702edae4cb1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36007, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "再生", "is_correct": true, "explanation": "正解。「再生（さいせい）」と聞こえる。"}, {"text": "体制", "is_correct": false, "explanation": "「たいせい」と読み、最初の拍が違う別の語。"}, {"text": "改正", "is_correct": false, "explanation": "「かいせい」と読み、最初の拍が違う別の語。"}, {"text": "賽銭", "is_correct": false, "explanation": "「さいせん」と読み、最後の拍が違う別の語。"}, {"text": "最低", "is_correct": false, "explanation": "「さいてい」と読み、三つ目の拍が違う別の語。"}], "explanations": {"再生": "正解。「再生（さいせい）」と聞こえる。", "体制": "「たいせい」と読み、最初の拍が違う別の語。", "改正": "「かいせい」と読み、最初の拍が違う別の語。", "賽銭": "「さいせん」と読み、最後の拍が違う別の語。", "最低": "「さいてい」と読み、三つ目の拍が違う別の語。"}, "sentence_index": null, "correct_answer": "再生"}, "level_3": {"options": [{"text": "再生", "is_correct": true, "explanation": "文脈に合う唯一の語。"}, {"text": "机", "is_correct": false, "explanation": "物の名前で、「環境〜」として意味が通らない。"}, {"text": "昼寝", "is_correct": false, "explanation": "「環境昼寝」という語はない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文脈に合わない具体物。"}], "explanations": {"再生": "文脈に合う唯一の語。", "机": "物の名前で、「環境〜」として意味が通らない。", "昼寝": "「環境昼寝」という語はない。", "鉛筆": "文脈に合わない具体物。"}, "sentence_index": 0, "correct_answer": "再生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この古い靴を再生して歩いた。", "explanation": "靴を履くことに「再生」は使わない。"}, {"text": "友達に手紙を再生した。", "explanation": "手紙を送る意味では使わない。"}, {"text": "昨日の夕ご飯を再生して食べた。", "explanation": "食べ物を温め直す意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdfefe4-8ec6-4c0d-80ea-0b95dc66eb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
