INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36007, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "この位置に入る正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「ゼロ化する」の対象を示せず非文になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表し、この位置では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "この位置に入る正しい助詞。", "に": "「ゼロ化する」の対象を示せず非文になる。", "へ": "方向を表し、目的語にならない。", "より": "比較を表し、この位置では意味が通らない。"}, "error_tags": {"に": "object_marking", "へ": "direction", "より": "other"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停止", "is_correct": true, "explanation": "意味が反対になる語。"}, {"text": "録画", "is_correct": false, "explanation": "映像を記録することで、反対の意味ではない。"}, {"text": "音楽", "is_correct": false, "explanation": "再生する対象であり、対義語ではない。"}, {"text": "画面", "is_correct": false, "explanation": "映像が映る場所で、対義語ではない。"}], "correct_answer": "停止", "explanations": {"停止": "意味が反対になる語。", "録画": "映像を記録することで、反対の意味ではない。", "音楽": "再生する対象であり、対義語ではない。", "画面": "映像が映る場所で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cdfefe4-8ec6-4c0d-80ea-0b95dc66eb93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
