INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物のサイズや程度、規模が標準以上であること。", "primary_collocate": null, "pronunciation": "おおきい", "ipa": "oːkiː", "syllable_count": 4, "sentences": [{"text": "その社会的意義は極めて大きい。", "target_word": "大きい", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "都会の限られたスペースを持つアパートメントでは、モダンなインテリアデザインが空間の印象を大きく左右します。", "target_word": "大きく", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この犬はとても大きい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお", "sentence_source": "generated"}, {"text": "大きい箱を二つ買った。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお はこ ふた か", "sentence_source": "generated"}, {"text": "彼の声は大きくて元気だ。", "target_word": "大きく", "complexity_tier": "T3", "furigana": "かれ こえ おお げんき", "sentence_source": "generated"}, {"text": "父の手は大きい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "ちち て おお", "sentence_source": "generated"}, {"text": "大きいかばんが欲しい。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお ほ", "sentence_source": "generated"}, {"text": "この町は前より大きくなった。", "target_word": "大きく", "complexity_tier": "T3", "furigana": "まち まえ おお", "sentence_source": "generated"}, {"text": "問題はとても大きいと思う。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "もんだい おお おも", "sentence_source": "generated"}, {"text": "大きい木の下で休んだ。", "target_word": "大きい", "complexity_tier": "T3", "furigana": "おお き した やす", "sentence_source": "generated"}], "morphological_forms": [{"form": "大きかった", "label": "活用"}, {"form": "大きく", "label": "活用"}, {"form": "大きくない", "label": "活用"}, {"form": "大きさ", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | サイズや程度が標準より上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for