INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "悪くなった状態が、もとのよい状態にもどること。", "primary_collocate": null, "pronunciation": "かいふく", "ipa": "kaiɸɯkɯ", "syllable_count": 4, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "回復", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "次いで、ラズベリー等のジャムを対になる片割れ、あるいは同一の切片上に重ね合わせる。\n\n甘味と塩気、滑らかさと顆粒感が口腔内で織りなす対照的なハーモニーは、単なる栄養補給の域を超え、短時間での認知機能回復をもたらし、合理性と美学が融合した食の営みとして完成する。", "target_word": "回復", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "祖母の体の回復を祈っている。", "target_word": "回復", "complexity_tier": "T3", "furigana": "そぼ からだ かいふく いの", "sentence_source": "generated"}, {"text": "景気の回復はまだ遅い。", "target_word": "回復", "complexity_tier": "T3", "furigana": "けいき かいふく おそ", "sentence_source": "generated"}, {"text": "彼は病気から回復した。", "target_word": "回復", "complexity_tier": "T3", "furigana": "かれ びょうき かいふく", "sentence_source": "generated"}, {"text": "よく寝ると体力が回復する。", "target_word": "回復", "complexity_tier": "T3", "furigana": "ね たいりょく かいふく", "sentence_source": "generated"}, {"text": "回復には時間がかかる。", "target_word": "回復", "complexity_tier": "T3", "furigana": "かいふく じかん", "sentence_source": "generated"}, {"text": "信頼の回復は難しい。", "target_word": "回復", "complexity_tier": "T3", "furigana": "しんらい かいふく むずか", "sentence_source": "generated"}, {"text": "天気が回復して晴れた。", "target_word": "回復", "complexity_tier": "T3", "furigana": "てんき かいふく は", "sentence_source": "generated"}, {"text": "早い回復を願っています。", "target_word": "回復", "complexity_tier": "T3", "furigana": "はや かいふく ねが", "sentence_source": "generated"}], "morphological_forms": [{"form": "回復する", "label": "派生"}, {"form": "回復した", "label": "活用"}, {"form": "回復力", "label": "派生"}, {"form": "回復期", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 悪い状態から元に戻ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 好影響 (Zipf 2.16)','sentence 1 above tier T2: contains vocabulary far above tier T2: 切片 (Zipf 1.86)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "植物の葉のような色。また、草や木。", "primary_collocate": null, "pronunciation": "みどり", "ipa": "midoɾi", "syllable_count": 3, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "緑", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "さらに、こうした緑の拠点が生み出す波及効果は計り知れない。", "target_word": "緑", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "鉢という限定された宇宙の中で、命は水という恩恵を糧に、時を重ねてその緑を深めていく。", "target_word": "緑", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "公園には緑が多い。", "target_word": "緑", "complexity_tier": "T3", "furigana": "こうえん みどり おお", "sentence_source": "generated"}, {"text": "春になると山が緑になる。", "target_word": "緑", "complexity_tier": "T3", "furigana": "はる やま みどり", "sentence_source": "generated"}, {"text": "緑のシャツを着ている。", "target_word": "緑", "complexity_tier": "T3", "furigana": "みどり き", "sentence_source": "generated"}, {"text": "窓から緑が見えて気持ちいい。", "target_word": "緑", "complexity_tier": "T3", "furigana": "まど みどり み きも", "sentence_source": "generated"}, {"text": "町の緑を守りたい。", "target_word": "緑", "complexity_tier": "T3", "furigana": "まち みどり まも", "sentence_source": "generated"}, {"text": "信号が緑に変わった。", "target_word": "緑", "complexity_tier": "T3", "furigana": "しんごう みどり か", "sentence_source": "generated"}, {"text": "緑の葉がきれいだ。", "target_word": "緑", "complexity_tier": "T3", "furigana": "みどり は", "sentence_source": "generated"}], "morphological_forms": [{"form": "緑色", "label": "派生"}, {"form": "緑茶", "label": "派生"}, {"form": "緑地", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 草木の葉のような色や植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'c