INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37471, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "集まって行う活動やイベントに加わること。", "primary_collocate": null, "pronunciation": "さんか", "ipa": "saŋka", "syllable_count": 3, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "参加", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この創造的プロセスこそが、行事の記憶を永続的なものへと変貌させ、参加者の帰属意識を強固なものへと昇華させるのである。", "target_word": "参加", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "友だちと大会に参加した。", "target_word": "参加", "complexity_tier": "T3", "furigana": "とも たいかい さんか", "sentence_source": "generated"}, {"text": "参加は自由です。", "target_word": "参加", "complexity_tier": "T3", "furigana": "さんか じゆう", "sentence_source": "generated"}, {"text": "明日の会議に参加できますか。", "target_word": "参加", "complexity_tier": "T3", "furigana": "あした かいぎ さんか", "sentence_source": "generated"}, {"text": "参加の申し込みは今日までだ。", "target_word": "参加", "complexity_tier": "T3", "furigana": "さんか もう こ きょう", "sentence_source": "generated"}, {"text": "多くの人が祭りに参加している。", "target_word": "参加", "complexity_tier": "T3", "furigana": "おお ひと まつ さんか", "sentence_source": "generated"}, {"text": "彼は参加を決めた。", "target_word": "参加", "complexity_tier": "T3", "furigana": "かれ さんか き", "sentence_source": "generated"}, {"text": "参加者に名前を書いてもらう。", "target_word": "参加", "complexity_tier": "T3", "furigana": "さんかしゃ なまえ か", "sentence_source": "generated"}, {"text": "クラブ活動への参加が楽しい。", "target_word": "参加", "complexity_tier": "T3", "furigana": "かつどう さんか たの", "sentence_source": "generated"}], "morphological_forms": [{"form": "参加する", "label": "派生"}, {"form": "参加者", "label": "派生"}, {"form": "参加した", "label": "活用"}, {"form": "不参加", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 活動や行事に加わること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 好影響 (Zipf 2.16)','sentence 1 above tier T1: 5 words above tier T1 (max 2): 永続 (Zipf 3.37), 変貌 (Zipf 3.46), 帰属 (Zipf 3.56), 強固 (Zipf 3.56), 昇華 (Zipf 3.35)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39285, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の意思で行動する中心となる人や集団。", "primary_collocate": null, "pronunciation": "しゅたい", "ipa": "ɕɯtai", "syllable_count": 3, "sentences": [{"text": "特に、住民の主体的な参加により創出されるガーデンは、生物多様性の回復のみならず、微気候の改善といった側面においても近隣緑地に好影響を及ぼしている。", "target_word": "主体", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "グローバルな金融市場やサプライチェーンといった社会経済的文脈において、個々の企業や投資家といったミクロな主体による局所的な意思決定は、決して単純な線形モデルでは捉えきれない。", "target_word": "主体", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "なぜならば、無数の主体が限られた情報に基づき絶えず適応を繰り返す過程で、意図せぬイノベーションやシステミック・リスクが突発的に顕現するからに他ならない。", "target_word": "主体", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "この活動の主体は生徒だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "かつどう しゅたい せいと", "sentence_source": "generated"}, {"text": "市民が主体となって町を作る。", "target_word": "主体", "complexity_tier": "T3", "furigana": "しみん しゅたい まち つく", "sentence_source": "generated"}, {"text": "学ぶ主体は自分自身だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "まな しゅたい じぶんじしん", "sentence_source": "generated"}, {"text": "若者主体の会が開かれた。", "target_word": "主体", "complexity_tier": "T3", "furigana": "わかもの しゅたい かい ひら", "sentence_source": "generated"}, {"text": "行動の主体を考える。", "target_word": "主体", "complexity_tier": "T3", "furigana": "こうどう しゅたい かんが", "sentence_source": "generated"}, {"text": "主体がはっきりしない文だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "しゅたい ぶん", "sentence_source": "generated"}, {"text": "地域の住民が主体だ。", "target_word": "主体", "complexity_tier": "T3", "furigana": "ちいき じゅうみん しゅたい", "sentence_source": "generated"}], "morphological_forms": [{"form": "主体的", "label": "派生"}, {"form": "主体性", "label": "派生"}, {"form": "主体的に", "label": "派生"}], "register": "