INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37755, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "はっきりと表に現れていること。", "primary_collocate": null, "pronunciation": "けんざい", "ipa": "kenzai", "syllable_count": 4, "sentences": [{"text": "近年、都市の無秩序な拡大に伴う緑の希薄化に歯止めをかけるべく、地域コミュニティガーデンプロジェクトが各地で顕在化している。", "target_word": "顕在", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "まず、現場や鑑識ラボにおいて、肉眼では捉えられぬ潜在指紋を、シアノアクリレート法や光学的手法といったアプローチにより顕在化させる。", "target_word": "顕在", "complexity_tier": "T6", "furigana": "", "sentence_source": "mined"}, {"text": "問題が顕在化してきた。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "もんだい けんざい か", "sentence_source": "generated"}, {"text": "不満が顕在化している。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "ふまん けんざいか", "sentence_source": "generated"}, {"text": "危険はまだ顕在していない。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "きけん けんざい", "sentence_source": "generated"}, {"text": "顕在する問題から考える。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "けんざい もんだい かんが", "sentence_source": "generated"}, {"text": "顕在的な需要を調べる。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "けんざいてき じゅよう しら", "sentence_source": "generated"}, {"text": "対立が顕在化した。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "たいりつ けんざいか", "sentence_source": "generated"}, {"text": "課題が顕在化する前に動く。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "かだい けんざいか まえ うご", "sentence_source": "generated"}, {"text": "リスクの顕在化を防ぐ。", "target_word": "顕在", "complexity_tier": "T3", "furigana": "けんざいか ふせ", "sentence_source": "generated"}], "morphological_forms": [{"form": "顕在化", "label": "派生"}, {"form": "顕在的", "label": "派生"}, {"form": "顕在化する", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 表面にはっきり現れていること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T4: contains vocabulary far above tier T4: シアノアクリレート (Zipf 1.04)']::text[], 'bd46283a-be24-4984-9df4-26cf7330d10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大きい", "is_correct": true, "explanation": "正解：おおきい。"}, {"text": "雄々しい", "is_correct": false, "explanation": "おおしい。三つ目の「き」が「し」に変わる一モーラ差。"}, {"text": "大君", "is_correct": false, "explanation": "おおきみ。最後の「い」が「み」に変わる一モーラ差。"}, {"text": "おおきに", "is_correct": false, "explanation": "おおきに。最後の「い」が「に」に変わる一モーラ差。"}], "explanations": {"大きい": "正解：おおきい。", "雄々しい": "おおしい。三つ目の「き」が「し」に変わる一モーラ差。", "大君": "おおきみ。最後の「い」が「み」に変わる一モーラ差。", "おおきに": "おおきに。最後の「い」が「に」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "大きい"}, "level_3": {"options": [{"text": "大きい", "is_correct": true, "explanation": "意義の程度が標準以上であることを表す。"}, {"text": "丸い", "is_correct": false, "explanation": "意味：形を表す語で、意義の程度は表せない。"}, {"text": "冷たい", "is_correct": false, "explanation": "意味：温度を表す語で、意義には使えない。"}, {"text": "若い", "is_correct": false, "explanation": "連語：「意義」は年齢を表す「若い」と結びつかない。"}], "explanations": {"大きい": "意義の程度が標準以上であることを表す。", "丸い": "意味：形を表す語で、意義の程度は表せない。", "冷たい": "意味：温度を表す語で、意義には使えない。", "若い": "連語：「意義」は年齢を表す「若い」と結びつかない。"}, "sentence_index": 0, "correct_answer": "大きい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大きいな箱を二つ買った。", "explanation": "活用の誤り：い形容詞「大きい」は「な」を付けずに名詞を修飾する。"}, {"text": "大きく箱を二つ買った。", "explanation": "活用の誤り：名詞「箱」を修飾するには連用形「大きく」ではなく「大きい」。"}, {"text": "箱を大きい二つ買った。", "explanation": "語順の誤り：「大きい」は名詞「箱」の前に置く。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この犬はとても大きいだ。", "corrected_sentence": "この犬はとても大きい。", "error_description": "活用の誤り：い形容詞の後に「だ」は付けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大きく", "is_correct": true, "explanation": "動詞「左右します」を修飾するので連用形「く」が必要。"}, {"text": "大きい", "is_correct": false, "explanation": "終止・連体形で、動詞を修飾できない。"}, {"text": "大きかった", "is_correct": false, "explanation": "過去形で、動詞の前に置けない。"}, {"text": "大きくない", "is_correct": false, "explanation": "否定形で文意と矛盾し、形もつながらない。"}], "correct_form": "大きく", "base_form": "大きい", "form_label": "連用形（く形）", "sentence_index": 1, "explanations": {"大きく": "動詞「左右します」を修飾するので連用形「く」が必要。", "大きい": "終止・連体形で、動詞を修飾できない。", "大きかった": "過去形で、動詞の前に置けない。", "大きくない": "否定形で文意と矛盾し、形もつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
