INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35917, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大きい", "is_correct": true, "explanation": "読みは「おおきい」。"}, {"text": "大木戸", "is_correct": false, "explanation": "最後の「い」が「ど」になる一モーラ差の語（おおきど）。"}, {"text": "多い", "is_correct": false, "explanation": "「き」が抜けた語（おおい）。"}, {"text": "おおきに", "is_correct": false, "explanation": "最後の「い」が「に」になる一モーラ差の語。"}], "explanations": {"大きい": "読みは「おおきい」。", "大木戸": "最後の「い」が「ど」になる一モーラ差の語（おおきど）。", "多い": "「き」が抜けた語（おおい）。", "おおきに": "最後の「い」が「に」になる一モーラ差の語。"}, "sentence_index": null, "correct_answer": "大きい"}, "level_3": {"options": [{"text": "大きい", "is_correct": true, "explanation": "かばんのサイズを表し、自然に入る。"}, {"text": "眠い", "is_correct": false, "explanation": "意味：人の状態を表し、かばんには使えない。"}, {"text": "嬉しい", "is_correct": false, "explanation": "意味：気持ちを表し、物の性質にならない。"}, {"text": "痛い", "is_correct": false, "explanation": "連語：「痛いかばん」とは言わない。"}], "explanations": {"大きい": "かばんのサイズを表し、自然に入る。", "眠い": "意味：人の状態を表し、かばんには使えない。", "嬉しい": "意味：気持ちを表し、物の性質にならない。", "痛い": "連語：「痛いかばん」とは言わない。"}, "sentence_index": 6, "correct_answer": "大きい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きいの木の下で休んだ。", "explanation": "活用の誤り：い形容詞は「の」を挟まずに名詞を修飾する。"}, {"text": "大きく木の下で休んだ。", "explanation": "活用の誤り：名詞「木」を修飾するには「大きい」が必要。"}, {"text": "下で大きい木の休んだ。", "explanation": "語順の誤り：「大きい木の下で」の順でなければならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
