INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回復", "is_correct": true, "explanation": "正解：かいふく。"}, {"text": "海賊", "is_correct": false, "explanation": "かいぞく。「ふ」が「ぞ」に変わる一モーラ差。"}, {"text": "快速", "is_correct": false, "explanation": "かいそく。「ふ」が「そ」に変わる一モーラ差。"}, {"text": "解読", "is_correct": false, "explanation": "かいどく。「ふ」が「ど」に変わる一モーラ差。"}, {"text": "開封", "is_correct": false, "explanation": "かいふう。最後の「く」が「う」に変わる一モーラ差。"}], "explanations": {"回復": "正解：かいふく。", "海賊": "かいぞく。「ふ」が「ぞ」に変わる一モーラ差。", "快速": "かいそく。「ふ」が「そ」に変わる一モーラ差。", "解読": "かいどく。「ふ」が「ど」に変わる一モーラ差。", "開封": "かいふう。最後の「く」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "回復"}, "level_3": {"options": [{"text": "回復", "is_correct": true, "explanation": "生物多様性が元のよい状態に戻ることを表す。"}, {"text": "出席", "is_correct": false, "explanation": "意味：人が会に出ることで、生物多様性には使えない。"}, {"text": "卒業", "is_correct": false, "explanation": "意味：学校を終えることで、文脈に合わない。"}, {"text": "到着", "is_correct": false, "explanation": "連語：「生物多様性の到着」とは言わない。"}], "explanations": {"回復": "生物多様性が元のよい状態に戻ることを表す。", "出席": "意味：人が会に出ることで、生物多様性には使えない。", "卒業": "意味：学校を終えることで、文脈に合わない。", "到着": "連語：「生物多様性の到着」とは言わない。"}, "sentence_index": 0, "correct_answer": "回復"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "景気が回復はまだ遅い。", "explanation": "助詞の混同：「景気の回復」と「の」でつなぐ。"}, {"text": "景気の回復はまだ遅かっている。", "explanation": "活用の誤り：い形容詞に「ている」は付かない。"}, {"text": "まだ景気の遅い回復は。", "explanation": "語順の誤り：主題と述語の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
