INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「もたらす」の目的語を表す。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、目的語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表し、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「もたらす」の目的語を表す。", "で": "手段・場所を表し、目的語にならない。", "へ": "方向を表し、ここでは非文。", "と": "並列・相手を表し、意味が通らない。"}, "error_tags": {"で": "instrument", "へ": "direction", "と": "listing"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "状態が悪くなることで、「回復」の反対。"}, {"text": "改善", "is_correct": false, "explanation": "よくなることで、対義語ではない。"}, {"text": "治療", "is_correct": false, "explanation": "病気を治す行為で、対義関係にない。"}, {"text": "発展", "is_correct": false, "explanation": "伸びていくことで、反対の意味ではない。"}], "correct_answer": "悪化", "explanations": {"悪化": "状態が悪くなることで、「回復」の反対。", "改善": "よくなることで、対義語ではない。", "治療": "病気を治す行為で、対義関係にない。", "発展": "伸びていくことで、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "回復", "is_correct": true, "explanation": "読みは「かいふく」。"}, {"text": "快楽", "is_correct": false, "explanation": "「ふ」が「ら」になる一モーラ差の語（かいらく）。"}, {"text": "海賊", "is_correct": false, "explanation": "「ふ」が「ぞ」になる一モーラ差の語（かいぞく）。"}, {"text": "開幕", "is_correct": false, "explanation": "「ふ」が「ま」になる一モーラ差の語（かいまく）。"}, {"text": "会則", "is_correct": false, "explanation": "「ふ」が「そ」になる一モーラ差の語（かいそく）。"}], "explanations": {"回復": "読みは「かいふく」。", "快楽": "「ふ」が「ら」になる一モーラ差の語（かいらく）。", "海賊": "「ふ」が「ぞ」になる一モーラ差の語（かいぞく）。", "開幕": "「ふ」が「ま」になる一モーラ差の語（かいまく）。", "会則": "「ふ」が「そ」になる一モーラ差の語（かいそく）。"}, "sentence_index": null, "correct_answer": "回復"}, "level_3": {"options": [{"text": "回復", "is_correct": true, "explanation": "元の状態に戻るまでには時間が必要という意味になる。"}, {"text": "瞬間", "is_correct": false, "explanation": "意味：ごく短い時間で、「時間がかかる」と矛盾する。"}, {"text": "即答", "is_correct": false, "explanation": "意味：すぐに答えることで、時間がかからない。"}, {"text": "昨日", "is_correct": false, "explanation": "アスペクト：過去の日を表し、これからかかる時間と合わない。"}], "explanations": {"回復": "元の状態に戻るまでには時間が必要という意味になる。", "瞬間": "意味：ごく短い時間で、「時間がかかる」と矛盾する。", "即答": "意味：すぐに答えることで、時間がかからない。", "昨日": "アスペクト：過去の日を表し、これからかかる時間と合わない。"}, "sentence_index": 6, "correct_answer": "回復"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早い回復が願っています。", "explanation": "助詞の混同：願う対象は「を」で表す。"}, {"text": "回復を早い願っています。", "explanation": "語順の誤り：「早い」は名詞「回復」の前に置く。"}, {"text": "早い回復を一枚願っています。", "explanation": "助数詞の誤り：「回復」は数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天気を回復して晴れた。", "corrected_sentence": "天気が回復して晴れた。", "error_description": "助詞の混同：天気が自然に戻る意味では主語「が」を使い、「を」は取らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36953, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞「信頼」と「回復」をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "後ろに動詞がなく、目的語標示にならない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、名詞同士をつなげない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}], "correct_answer": "の", "explanations": {"の": "名詞「信頼」と「回復」をつなぐ。", "を": "後ろに動詞がなく、目的語標示にならない。", "で": "手段を表し、名詞同士をつなげない。", "へ": "方向を表し、ここでは非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悪化", "is_correct": true, "explanation": "よい状態が悪くなることで、「回復」の対義語。"}, {"text": "進歩", "is_correct": false, "explanation": "よくなっていくことで、対義語ではない。"}, {"text": "変化", "is_correct": false, "explanation": "単に変わることで、反対の意味ではない。"}, {"text": "安定", "is_correct": false, "explanation": "落ち着いた状態で、対義関係にない。"}], "correct_answer": "悪化", "explanations": {"悪化": "よい状態が悪くなることで、「回復」の対義語。", "進歩": "よくなっていくことで、対義語ではない。", "変化": "単に変わることで、反対の意味ではない。", "安定": "落ち着いた状態で、対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "緑", "is_correct": true, "explanation": "正解：みどり。"}, {"text": "千鳥", "is_correct": false, "explanation": "ちどり。最初の「み」が「ち」に変わる一モーラ差。"}, {"text": "実り", "is_correct": false, "explanation": "みのり。「ど」が「の」に変わる一モーラ差。"}, {"text": "看取り", "is_correct": false, "explanation": "みとり。「ど」と「と」の清濁の違い。"}, {"text": "御堂", "is_correct": false, "explanation": "みどう。最後の「り」が「う」に変わる一モーラ差。"}], "explanations": {"緑": "正解：みどり。", "千鳥": "ちどり。最初の「み」が「ち」に変わる一モーラ差。", "実り": "みのり。「ど」が「の」に変わる一モーラ差。", "看取り": "みとり。「ど」と「と」の清濁の違い。", "御堂": "みどう。最後の「り」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "緑"}, "level_3": {"options": [{"text": "緑", "is_correct": true, "explanation": "都市の草木が少なくなることを表す。"}, {"text": "赤", "is_correct": false, "explanation": "意味：色を表すが、都市で減る植物を指さない。"}, {"text": "夜", "is_correct": false, "explanation": "意味：時間を表し、文脈に合わない。"}, {"text": "机", "is_correct": false, "explanation": "連語：「机の希薄化」とは言わない。"}], "explanations": {"緑": "都市の草木が少なくなることを表す。", "赤": "意味：色を表すが、都市で減る植物を指さない。", "夜": "意味：時間を表し、文脈に合わない。", "机": "連語：「机の希薄化」とは言わない。"}, "sentence_index": 0, "correct_answer": "緑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園には緑を多い。", "explanation": "助詞の混同：「多い」の主語は「が」で表す。"}, {"text": "公園には緑が三冊多い。", "explanation": "助数詞の誤り：緑は「冊」で数えない。"}, {"text": "多い公園には緑が。", "explanation": "語順の誤り：述語が前に出て文が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
