INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36831, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "緑", "is_correct": true, "explanation": "読みは「みどり」。"}, {"text": "日取り", "is_correct": false, "explanation": "「み」が「ひ」になる一モーラ差の語（ひどり）。"}, {"text": "看取り", "is_correct": false, "explanation": "「ど」が清音「と」になった語（みとり）。"}, {"text": "見張り", "is_correct": false, "explanation": "「ど」が「は」になる一モーラ差の語（みはり）。"}, {"text": "身振り", "is_correct": false, "explanation": "「ど」が「ぶ」になる一モーラ差の語（みぶり）。"}], "explanations": {"緑": "読みは「みどり」。", "日取り": "「み」が「ひ」になる一モーラ差の語（ひどり）。", "看取り": "「ど」が清音「と」になった語（みとり）。", "見張り": "「ど」が「は」になる一モーラ差の語（みはり）。", "身振り": "「ど」が「ぶ」になる一モーラ差の語（みぶり）。"}, "sentence_index": null, "correct_answer": "緑"}, "level_3": {"options": [{"text": "緑", "is_correct": true, "explanation": "窓から草木が見えるという意味になる。"}, {"text": "音", "is_correct": false, "explanation": "項構造：音は聞こえるもので「見える」の主語にならない。"}, {"text": "匂い", "is_correct": false, "explanation": "項構造：匂いは見えない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：窓から見える景色ではない。"}], "explanations": {"緑": "窓から草木が見えるという意味になる。", "音": "項構造：音は聞こえるもので「見える」の主語にならない。", "匂い": "項構造：匂いは見えない。", "宿題": "意味：窓から見える景色ではない。"}, "sentence_index": 6, "correct_answer": "緑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "緑の葉をきれいだ。", "explanation": "助詞の混同：「きれいだ」の主語は「が」。"}, {"text": "緑い葉がきれいだ。", "explanation": "品詞の誤り：「緑」は名詞で「い」は付かない。「緑の葉」とする。"}, {"text": "緑の葉がきれいだった明日。", "explanation": "アスペクトの誤り：「明日」に過去形は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
