INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37471, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "参加", "is_correct": true, "explanation": "正解：さんか。"}, {"text": "担架", "is_correct": false, "explanation": "たんか。最初の「さ」が「た」に変わる一モーラ差。"}, {"text": "珊瑚", "is_correct": false, "explanation": "さんご。「か」が「ご」に変わる一モーラ差。"}, {"text": "秋刀魚", "is_correct": false, "explanation": "さんま。「か」が「ま」に変わる一モーラ差。"}, {"text": "作家", "is_correct": false, "explanation": "さっか。「ん」が促音「っ」に変わる。"}], "explanations": {"参加": "正解：さんか。", "担架": "たんか。最初の「さ」が「た」に変わる一モーラ差。", "珊瑚": "さんご。「か」が「ご」に変わる一モーラ差。", "秋刀魚": "さんま。「か」が「ま」に変わる一モーラ差。", "作家": "さっか。「ん」が促音「っ」に変わる。"}, "sentence_index": null, "correct_answer": "参加"}, "level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "住民が活動に加わることを表す。"}, {"text": "欠席", "is_correct": false, "explanation": "意味：加わらないことで、創出と矛盾する。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：眠ることで、ガーデン作りと無関係。"}, {"text": "誕生", "is_correct": false, "explanation": "連語：「主体的な誕生」とは言わない。"}], "explanations": {"参加": "住民が活動に加わることを表す。", "欠席": "意味：加わらないことで、創出と矛盾する。", "睡眠": "意味：眠ることで、ガーデン作りと無関係。", "誕生": "連語：「主体的な誕生」とは言わない。"}, "sentence_index": 0, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加が自由ます。", "explanation": "活用の誤り：名詞の後は「です」。"}, {"text": "参加を自由です。", "explanation": "助詞の混同：主題は「は」で表す。"}, {"text": "自由参加はです。", "explanation": "語順の誤り：主題—解説の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
