INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37471, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "参加", "is_correct": true, "explanation": "読みは「さんか」。"}, {"text": "サンタ", "is_correct": false, "explanation": "「か」が「た」になる一モーラ差の語（さんた）。"}, {"text": "珊瑚", "is_correct": false, "explanation": "「か」が「ご」になる一モーラ差の語（さんご）。"}, {"text": "産地", "is_correct": false, "explanation": "「か」が「ち」になる一モーラ差の語（さんち）。"}, {"text": "感化", "is_correct": false, "explanation": "「さ」が「か」になる一モーラ差の語（かんか）。"}], "explanations": {"参加": "読みは「さんか」。", "サンタ": "「か」が「た」になる一モーラ差の語（さんた）。", "珊瑚": "「か」が「ご」になる一モーラ差の語（さんご）。", "産地": "「か」が「ち」になる一モーラ差の語（さんち）。", "感化": "「さ」が「か」になる一モーラ差の語（かんか）。"}, "sentence_index": null, "correct_answer": "参加"}, "level_3": {"options": [{"text": "参加", "is_correct": true, "explanation": "祭りに加わっているという意味になる。"}, {"text": "卒業", "is_correct": false, "explanation": "項構造：「卒業」は「〜を」「〜から」をとり、「祭りに」と合わない。"}, {"text": "掃除", "is_correct": false, "explanation": "項構造：「掃除」は「〜を」をとり、「祭りに」と合わない。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：眠ることで、祭りと結びつかない。"}], "explanations": {"参加": "祭りに加わっているという意味になる。", "卒業": "項構造：「卒業」は「〜を」「〜から」をとり、「祭りに」と合わない。", "掃除": "項構造：「掃除」は「〜を」をとり、「祭りに」と合わない。", "睡眠": "意味：眠ることで、祭りと結びつかない。"}, "sentence_index": 6, "correct_answer": "参加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "クラブ活動への参加を楽しい。", "explanation": "助詞の混同：「楽しい」の主語は「が」。"}, {"text": "クラブ活動への参加が一本楽しい。", "explanation": "助数詞の誤り：参加は「本」で数えない。"}, {"text": "楽しいがクラブ活動への参加。", "explanation": "語順の誤り：述語と主語の順が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EX