INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39285, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「による」で行為の主を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語標示で、「よる」とつながらない。"}, {"text": "で", "is_correct": false, "explanation": "手段を表し、「でよる」とは言わない。"}, {"text": "が", "is_correct": false, "explanation": "主格で、「がよる」は非文。"}], "correct_answer": "に", "explanations": {"に": "「による」で行為の主を表す。", "を": "目的語標示で、「よる」とつながらない。", "で": "手段を表し、「でよる」とは言わない。", "が": "主格で、「がよる」は非文。"}, "error_tags": {"を": "object_marking", "で": "instrument", "が": "topic_vs_subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "客体", "is_correct": true, "explanation": "働きかけを受ける側で、「主体」の対義語。"}, {"text": "中心", "is_correct": false, "explanation": "真ん中の意で、対義語ではない。"}, {"text": "主役", "is_correct": false, "explanation": "中心人物で、反対の意味ではない。"}, {"text": "全体", "is_correct": false, "explanation": "すべてを指し、対義関係にない。"}], "correct_answer": "客体", "explanations": {"客体": "働きかけを受ける側で、「主体」の対義語。", "中心": "真ん中の意で、対義語ではない。", "主役": "中心人物で、反対の意味ではない。", "全体": "すべてを指し、対義関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39285, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主体", "is_correct": true, "explanation": "読みは「しゅたい」。"}, {"text": "醜態", "is_correct": false, "explanation": "「しゅ」が伸びて「しゅう」になった語（しゅうたい）。"}, {"text": "取材", "is_correct": false, "explanation": "「た」が「ざ」になる一モーラ差の語（しゅざい）。"}, {"text": "主催", "is_correct": false, "explanation": "「た」が「さ」になる一モーラ差の語（しゅさい）。"}], "explanations": {"主体": "読みは「しゅたい」。", "醜態": "「しゅ」が伸びて「しゅう」になった語（しゅうたい）。", "取材": "「た」が「ざ」になる一モーラ差の語（しゅざい）。", "主催": "「た」が「さ」になる一モーラ差の語（しゅさい）。"}, "sentence_index": null, "correct_answer": "主体"}, "level_3": {"options": [{"text": "主体", "is_correct": true, "explanation": "若者が中心となる会という意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "意味：空の様子で、会の中心にならない。"}, {"text": "机", "is_correct": false, "explanation": "意味：物で、会の担い手にならない。"}, {"text": "速度", "is_correct": false, "explanation": "連語：「若者速度の会」とは言わない。"}], "explanations": {"主体": "若者が中心となる会という意味になる。", "天気": "意味：空の様子で、会の中心にならない。", "机": "意味：物で、会の担い手にならない。", "速度": "連語：「若者速度の会」とは言わない。"}, "sentence_index": 6, "correct_answer": "主体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地域の住民を主体だ。", "explanation": "助詞の混同：主語は「が」で表す。"}, {"text": "地域の住民が主体ました。", "explanation": "活用の誤り：名詞の後に「ました」は付かない。"}, {"text": "主体だが住民の地域。", "explanation": "語順の誤り：係り受けが壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
