INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39285, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「考える」の目的語を表す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、「考える」の目的語にならない。"}, {"text": "や", "is_correct": false, "explanation": "並列を表し、後ろに名詞がなく非文。"}], "correct_answer": "を", "explanations": {"を": "「考える」の目的語を表す。", "へ": "方向を表し、ここでは非文。", "に": "着点を表し、「考える」の目的語にならない。", "や": "並列を表し、後ろに名詞がなく非文。"}, "error_tags": {"へ": "direction", "に": "location_vs_target", "や": "listing"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "客体", "is_correct": true, "explanation": "行為を受ける側で、「主体」の反対。"}, {"text": "本体", "is_correct": false, "explanation": "物の中心部分で、対義語ではない。"}, {"text": "個人", "is_correct": false, "explanation": "一人の人で、反対の意味ではない。"}, {"text": "団体", "is_correct": false, "explanation": "人の集まりで、対義関係にない。"}], "correct_answer": "客体", "explanations": {"客体": "行為を受ける側で、「主体」の反対。", "本体": "物の中心部分で、対義語ではない。", "個人": "一人の人で、反対の意味ではない。", "団体": "人の集まりで、対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37755, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "顕在", "is_correct": true, "explanation": "正解：けんざい。"}, {"text": "現在", "is_correct": false, "explanation": "げんざい。「け」と「げ」の清濁の違い。"}, {"text": "経済", "is_correct": false, "explanation": "けいざい。「ん」が「い」に変わる一モーラ差。"}, {"text": "洗剤", "is_correct": false, "explanation": "せんざい。「け」が「せ」に変わる一モーラ差。"}, {"text": "見解", "is_correct": false, "explanation": "けんかい。「ざ」が「か」に変わる一モーラ差。"}], "explanations": {"顕在": "正解：けんざい。", "現在": "げんざい。「け」と「げ」の清濁の違い。", "経済": "けいざい。「ん」が「い」に変わる一モーラ差。", "洗剤": "せんざい。「け」が「せ」に変わる一モーラ差。", "見解": "けんかい。「ざ」が「か」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "顕在"}, "level_3": {"options": [{"text": "顕在", "is_correct": true, "explanation": "プロジェクトがはっきり表に現れてきたことを表す。"}, {"text": "液", "is_correct": false, "explanation": "意味：「液化」は液体になることで、文脈に合わない。"}, {"text": "気", "is_correct": false, "explanation": "意味：「気化」は気体になることで、プロジェクトに使えない。"}, {"text": "酸", "is_correct": false, "explanation": "意味：「酸化」は化学変化で、プロジェクトに使えない。"}], "explanations": {"顕在": "プロジェクトがはっきり表に現れてきたことを表す。", "液": "意味：「液化」は液体になることで、文脈に合わない。", "気": "意味：「気化」は気体になることで、プロジェクトに使えない。", "酸": "意味：「酸化」は化学変化で、プロジェクトに使えない。"}, "sentence_index": 0, "correct_answer": "顕在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不満が顕在化にしている。", "explanation": "活用の誤り：サ変動詞「顕在化する」に「に」は入らない。"}, {"text": "不満が顕在的している。", "explanation": "派生の誤り：形容動詞「顕在的」に「している」は付かない。"}, {"text": "顕在化が不満している。", "explanation": "語順の誤り：主語「不満」と述語「顕在化」が入れ替わっている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e87d3055-8596-4c46-b8a0-4861d25596b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
