INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39687, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の代わりに、自動で動いたり作業をしたりする機械。", "primary_collocate": null, "pronunciation": "ろぼっと", "ipa": "ɾobotto", "syllable_count": 4, "sentences": [{"text": "あたらしいロボットは、おうちでいろいろなてつだいをします。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "それこそが、静謐な自宅の工房において初学者が向き合う、ロボット製作の本質である。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "せいひつ じたく こうぼう しょがくしゃ む あ せいさく ほんしつ", "sentence_source": "mined"}, {"text": "ロボット工学の深淵を志す者がまず体現すべきは、DIYの精神に根ざした泥臭い試行錯誤のプロセスに他ならない。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "こうがく しんえん こころざ もの たいげん せいしん ね どろくさ しこうさくご ほか", "sentence_source": "mined"}, {"text": "弟はロボットが大好きだ。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "おとうと だいす", "sentence_source": "generated"}, {"text": "工場でロボットが働いている。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "こうじょう はたら", "sentence_source": "generated"}, {"text": "このロボットは話すことができる。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "はな", "sentence_source": "generated"}, {"text": "友達とロボットを作った。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "ともだち つく", "sentence_source": "generated"}, {"text": "掃除はロボットに任せている。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "そうじ まか", "sentence_source": "generated"}, {"text": "ロボットの動きがおもしろい。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "うご", "sentence_source": "generated"}, {"text": "未来の町にはロボットが多い。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "みらい まち おお", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "助数詞"}, {"form": "ロボット工学", "label": "派生"}, {"form": "ロボット掃除機", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自動