INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36235, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "親しく付き合い、一緒に楽しい時間を過ごす人。", "primary_collocate": null, "pronunciation": "ともだち", "ipa": "tomodatɕi", "syllable_count": 4, "sentences": [{"text": "これからのともだちになれるでしょうか。", "target_word": "ともだち", "complexity_tier": "T3", "furigana": "", "sentence_source": "mined"}, {"text": "教室という微型社会において、彼女は未知の友達とどのように接し、どのようになじんでいくのだろうか。", "target_word": "友達", "complexity_tier": "T3", "furigana": "きょうしつ びけいしゃかい かのじょ みち ともだち せっ", "sentence_source": "mined"}, {"text": "友達と公園で遊んだ。", "target_word": "友達", "complexity_tier": "T3", "furigana": "ともだち こうえん あそ", "sentence_source": "generated"}, {"text": "私には友達が三人いる。", "target_word": "友達", "complexity_tier": "T3", "furigana": "わたし ともだち さんにん", "sentence_source": "generated"}, {"text": "友達の家に泊まりに行った。", "target_word": "友達", "complexity_tier": "T3", "furigana": "ともだち いえ と い", "sentence_source": "generated"}, {"text": "彼は小学校からの友達だ。", "target_word": "友達", "complexity_tier": "T3", "furigana": "かれ しょうがっこう ともだち", "sentence_source": "generated"}, {"text": "友達に手紙を書いている。", "target_word": "友達", "complexity_tier": "T3", "furigana": "ともだち てがみ か", "sentence_source": "generated"}, {"text": "新しい友達ができた。", "target_word": "友達", "complexity_tier": "T3", "furigana": "あたら ともだち", "sentence_source": "generated"}, {"text": "友達を家族に紹介した。", "target_word": "友達", "complexity_tier": "T3", "furigana": "ともだち かぞく しょうかい", "sentence_source": "generated"}, {"text": "困った時は友達に相談する。", "target_word": "友達", "complexity_tier": "T3", "furigana": "こま とき ともだち そうだん", "sentence_source": "generated"}], "morphological_forms": [{"form": "人", "label": "助数詞"}, {"form": "友達付き合い", "label": "派生"}, {"form": "お友達", "label": "敬語形"}], "register": "plain", "sense_fingerprint": "名詞 | 親しく付き合い一緒に過ごす人", "collocate_grounding": {"status": "no_source", "reason":