INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35875, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "ほかと比べて、さらに程度が進んでいるさま。もっと。", "primary_collocate": null, "pronunciation": "より", "ipa": "joɾi", "syllable_count": 2, "sentences": [{"text": "ミニマリストの思想に基づき、必要な要素だけを残すことで、居住者はより穏やかな日常を送ることができます。", "target_word": "より", "complexity_tier": "T3", "furigana": "しそう もと ひつよう ようそ のこ きょじゅうしゃ おだ にちじょう おく", "sentence_source": "mined"}, {"text": "かかる感覚的知見の蓄積は、単一品種を基準とした旧来の分類体系を相対化し、微細な区画ごとの個性を階層的に位置づけるアペラシオンの概念を、より厳密かつ動的なヒエラルキーへと昇華させ、ワインの価値評価基準そのものを哲学的かつ実践的に再定義しているのである。", "target_word": "より", "complexity_tier": "T3", "furigana": "かんかくてき ちけん ちくせき たんいつひんしゅ きじゅん きゅうらい ぶんるいたいけい そうたいか びさい くかく こせい かいそうてき いち がいねん げんみつ どうてき しょうか かち ひょうか てつがくてき じっせんてき さいていぎ", "sentence_source": "mined"}, {"text": "より速く走れるようになった。", "target_word": "より", "complexity_tier": "T3", "furigana": "はや はし", "sentence_source": "generated"}, {"text": "この町をより良くしたい。", "target_word": "より", "complexity_tier": "T3", "furigana": "まち よ", "sentence_source": "generated"}, {"text": "より多くの人に読んでほしい。", "target_word": "より", "complexity_tier": "T3", "furigana": "おお ひと よ", "sentence_source": "generated"}, {"text": "練習してより上手になった。", "target_word": "より", "complexity_tier": "T3", "furigana": "れんしゅう じょうず", "sentence_source": "generated"}, {"text": "より深く考えてみよう。", "target_word": "より", "complexity_tier": "T3", "furigana": "ふか かんが", "sentence_source": "generated"}, {"text": "より安全な道を選んだ。", "target_word": "より", "complexity_tier": "T3", "furigana": "あんぜん みち えら", "sentence_source": "generated"}, {"text": "より大きな夢を持っている。", "target_word": "より", "complexity_tier": "T3", "furigana": "おお ゆめ も", "sentence_source": "generated"}, {"text": "説明がより分かりやすくなった。", "target_word": "より", "complexity_tier": "T3", "furigana": "せつめい わ", "sentence_source": "generated"}], "morphological_forms": [], "register": "forma