INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51688, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "よけいなものがまじっていないこと。けがれがなく純粋なこと。", "primary_collocate": null, "pronunciation": "むく", "ipa": "mɯkɯ", "syllable_count": 2, "sentences": [{"text": "具体的には、無垢材の家具と白壁の組み合わせ、あるいは間接照明による陰影の演出などが効果的です。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "ぐたいてき むくざい かぐ しらかべ く あ かんせつしょうめい いんえい えんしゅつ こうかてき", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "かれつ かんぷう ほお う そと せかい むく こうきしん たずさ か だ せなか にんげん ほんらい そな かこく かんきょう たの へんぼう たくま ぎょうしゅく", "sentence_source": "mined"}, {"text": "子どもの無垢な笑顔が好きだ。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "こ むく えがお す", "sentence_source": "generated"}, {"text": "このテーブルは無垢の木でできている。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "むく き", "sentence_source": "generated"}, {"text": "彼女の目は無垢に見えた。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "かのじょ め むく み", "sentence_source": "generated"}, {"text": "無垢な心を大切にしたい。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "むく こころ たいせつ", "sentence_source": "generated"}, {"text": "赤ちゃんは無垢そのものだ。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "あか むく", "sentence_source": "generated"}, {"text": "無垢の床はあたたかい。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "むく ゆか", "sentence_source": "generated"}, {"text": "その無垢さに心を打たれた。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "むく こころ う", "sentence_source": "generated"}, {"text": "彼は無垢な質問をした。", "target_word": "無垢", "complexity_tier": "T3", "furigana": "かれ むく しつもん", "sentence_source": "generated"}], "morphological_forms": [{"form": "無垢材", "label": "派生"}, {"form": "純真無垢", "label": "派生"}, {"form": "白無垢", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | まじりけやけがれがないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '708abd34-0229-4afa-9b45-7c1d0622f24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新しい", "is_correct": true, "explanation": "正解。「あたらしい」。"}, {"text": "温かい", "is_correct": false, "explanation": "「あたたかい」。三拍目以降が異なる近い音の語。"}, {"text": "痛ましい", "is_correct": false, "explanation": "「いたましい」。一拍目と三拍目が異なる。"}, {"text": "浅ましい", "is_correct": false, "explanation": "「あさましい」。二拍目と三拍目が異なる。"}], "explanations": {"新しい": "正解。「あたらしい」。", "温かい": "「あたたかい」。三拍目以降が異なる近い音の語。", "痛ましい": "「いたましい」。一拍目と三拍目が異なる。", "浅ましい": "「あさましい」。二拍目と三拍目が異なる。"}, "sentence_index": null, "correct_answer": "新しい"}, "level_3": {"options": [{"text": "あたらしい", "is_correct": true, "explanation": "正解。できたばかりのロボットを表す。"}, {"text": "すっぱい", "is_correct": false, "explanation": "意味：味の語でロボットの性質を表せない。"}, {"text": "にがい", "is_correct": false, "explanation": "連語：「にがいロボット」は味の語でロボットと結びつかない。"}, {"text": "さむい", "is_correct": false, "explanation": "意味：気温の語でロボットの性質を表せない。"}], "explanations": {"あたらしい": "正解。できたばかりのロボットを表す。", "すっぱい": "意味：味の語でロボットの性質を表せない。", "にがい": "連語：「にがいロボット」は味の語でロボットと結びつかない。", "さむい": "意味：気温の語でロボットの性質を表せない。"}, "sentence_index": 0, "correct_answer": "あたらしい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しいの駅に行った。", "explanation": "活用の誤り：形容詞は「の」を介さず「新しい駅」と直接名詞を修飾する。"}, {"text": "駅は昨日から新しいている。", "explanation": "活用・アスペクトの誤り：形容詞に「ている」は付かない。「新しくなった」が正しい。"}, {"text": "駅をとても新しい。", "explanation": "助詞の誤り：述語が形容詞なので主語は「が／は」で示す。「駅はとても新しい」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいな靴を買ってもらった。", "corrected_sentence": "新しい靴を買ってもらった。", "error_description": "い形容詞「新しい」は「な」を付けずに名詞を直接修飾する。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "新しい", "is_correct": true, "explanation": "正解。名詞「知識」を修飾する連体形。"}, {"text": "新しく", "is_correct": false, "explanation": "連用形で、名詞の前には置けない。"}, {"text": "新しかった", "is_correct": false, "explanation": "過去形で、一般的な必要性を述べる文脈に合わない。"}, {"text": "新しければ", "is_correct": false, "explanation": "仮定形で、名詞を修飾できない。"}], "correct_form": "新しい", "base_form": "新しい", "form_label": "連体形", "sentence_index": 1, "explanations": {"新しい": "正解。名詞「知識」を修飾する連体形。", "新しく": "連用形で、名詞の前には置けない。", "新しかった": "過去形で、一般的な必要性を述べる文脈に合わない。", "新しければ": "仮定形で、名詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "古い", "is_correct": true, "explanation": "正解。「新しい」の反対語。"}, {"text": "広い", "is_correct": false, "explanation": "大きさの語で反対語ではない。"}, {"text": "高い", "is_correct": false, "explanation": "高さ・値段の語で反対語ではない。"}, {"text": "明るい", "is_correct": false, "explanation": "光の語で反対語ではない。"}], "correct_answer": "古い", "explanations": {"古い": "正解。「新しい」の反対語。", "広い": "大きさの語で反対語ではない。", "高い": "高さ・値段の語で反対語ではない。", "明るい": "光の語で反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "新しい", "is_correct": true, "explanation": "正解。「あたらしい」。"}, {"text": "煩わしい", "is_correct": false, "explanation": "「わずらわしい」。拍数・音が近いが別の語。"}, {"text": "いやらしい", "is_correct": false, "explanation": "「いやらしい」。前の二拍が異なり、「らしい」が共通。"}, {"text": "温かい", "is_correct": false, "explanation": "「あたたかい」。「あた」が共通で後半が異なる。"}], "explanations": {"新しい": "正解。「あたらしい」。", "煩わしい": "「わずらわしい」。拍数・音が近いが別の語。", "いやらしい": "「いやらしい」。前の二拍が異なり、「らしい」が共通。", "温かい": "「あたたかい」。「あた」が共通で後半が異なる。"}, "sentence_index": null, "correct_answer": "新しい"}, "level_3": {"options": [{"text": "新しい", "is_correct": true, "explanation": "正解。始まったばかりのクラスを表す。"}, {"text": "すっぱい", "is_correct": false, "explanation": "意味：味の語で「クラス」とは結びつかない。"}, {"text": "おいしい", "is_correct": false, "explanation": "連語：味の語で「クラス」とは結びつかない。"}, {"text": "重い", "is_correct": false, "explanation": "意味：重さはクラスの性質にならない。"}], "explanations": {"新しい": "正解。始まったばかりのクラスを表す。", "すっぱい": "意味：味の語で「クラス」とは結びつかない。", "おいしい": "連語：味の語で「クラス」とは結びつかない。", "重い": "意味：重さはクラスの性質にならない。"}, "sentence_index": 6, "correct_answer": "新しい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の家はまだ新しいだった。", "explanation": "活用の誤り：い形容詞の過去は「新しかった」で、「だった」は付かない。"}, {"text": "彼の家をまだ新しかった。", "explanation": "助詞の誤り：形容詞述語の主語は「は／が」で示す。"}, {"text": "まだ彼の新しかった家はです。", "explanation": "語順の誤り：主題—解説の構造が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35109, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この本は新しいて、きれいだ。", "corrected_sentence": "この本は新しくて、きれいだ。", "error_description": "い形容詞のて形は「新しくて」で、「新しいて」とは言わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "新しく", "is_correct": true, "explanation": "正解。「て」に続く連用形。"}, {"text": "新しい", "is_correct": false, "explanation": "終止・連体形で「て」には続かない。"}, {"text": "新しかっ", "is_correct": false, "explanation": "過去の語幹で「た」に続く形。"}, {"text": "新しけれ", "is_correct": false, "explanation": "仮定の形で「ば」に続く。"}], "correct_form": "新しく", "base_form": "新しい", "form_label": "連用形（て形）", "sentence_index": 7, "explanations": {"新しく": "正解。「て」に続く連用形。", "新しい": "終止・連体形で「て」には続かない。", "新しかっ": "過去の語幹で「た」に続く形。", "新しけれ": "仮定の形で「ば」に続く。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
