INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39687, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "正解。「ろぼっと」。"}, {"text": "ロケット", "is_correct": false, "explanation": "「ろけっと」。二拍目「ぼ」が「け」に変わる一拍差。"}, {"text": "ロゼット", "is_correct": false, "explanation": "「ろぜっと」。二拍目「ぼ」が「ぜ」に変わる一拍差。"}, {"text": "ポケット", "is_correct": false, "explanation": "「ぽけっと」。一・二拍目が異なる。"}], "explanations": {"ロボット": "正解。「ろぼっと」。", "ロケット": "「ろけっと」。二拍目「ぼ」が「け」に変わる一拍差。", "ロゼット": "「ろぜっと」。二拍目「ぼ」が「ぜ」に変わる一拍差。", "ポケット": "「ぽけっと」。一・二拍目が異なる。"}, "sentence_index": null, "correct_answer": "ロボット"}, "level_3": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "正解。家で手伝いをする機械。"}, {"text": "テレビ", "is_correct": false, "explanation": "意味：テレビは手伝いをしない。"}, {"text": "リンゴ", "is_correct": false, "explanation": "意味：果物は手伝いができない。"}, {"text": "ポスト", "is_correct": false, "explanation": "意味：郵便受けは家で動いて手伝わない。"}], "explanations": {"ロボット": "正解。家で手伝いをする機械。", "テレビ": "意味：テレビは手伝いをしない。", "リンゴ": "意味：果物は手伝いができない。", "ポスト": "意味：郵便受けは家で動いて手伝わない。"}, "sentence_index": 0, "correct_answer": "ロボット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟は一冊のロボットが大好きだ。", "explanation": "助数詞の誤り：ロボットは「一台」で数える。"}, {"text": "弟をロボットが大好きだ。", "explanation": "助詞の誤り：好きな人は「は」で示す。「弟はロボットが大好きだ」。"}, {"text": "弟はロボットを大好きだ。", "explanation": "助詞の誤り：「好きだ」の対象は「が」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
