INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (36235, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "友達", "is_correct": true, "explanation": "正解。「ともだち」。"}, {"text": "面立ち", "is_correct": false, "explanation": "「おもだち」。一拍目「と」が「お」に変わる一拍差。"}, {"text": "友引", "is_correct": false, "explanation": "「ともびき」。「とも」が共通で後半が異なる。"}, {"text": "友垣", "is_correct": false, "explanation": "「ともがき」。後半二拍が異なる。"}], "explanations": {"友達": "正解。「ともだち」。", "面立ち": "「おもだち」。一拍目「と」が「お」に変わる一拍差。", "友引": "「ともびき」。「とも」が共通で後半が異なる。", "友垣": "「ともがき」。後半二拍が異なる。"}, "sentence_index": null, "correct_answer": "友達"}, "level_3": {"options": [{"text": "ともだち", "is_correct": true, "explanation": "正解。これから親しくなる人。"}, {"text": "つくえ", "is_correct": false, "explanation": "意味：物には「なれる」と言わない。"}, {"text": "てんき", "is_correct": false, "explanation": "意味：人間関係の文脈に合わない。"}, {"text": "しゅくだい", "is_correct": false, "explanation": "意味：課題は親しい相手にならない。"}], "explanations": {"ともだち": "正解。これから親しくなる人。", "つくえ": "意味：物には「なれる」と言わない。", "てんき": "意味：人間関係の文脈に合わない。", "しゅくだい": "意味：課題は親しい相手にならない。"}, "sentence_index": 0, "correct_answer": "ともだち"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私には友達が三枚いる。", "explanation": "助数詞の誤り：人は「人」で数える。"}, {"text": "私には友達を三人いる。", "explanation": "助詞の誤り：存在の主体は「が」で示す。"}, {"text": "私には友達に三人いる。", "explanation": "助詞の誤り：存在するものは「が」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
