INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (37149, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手段", "is_correct": true, "explanation": "正解。「しゅだん」。"}, {"text": "主題", "is_correct": false, "explanation": "「しゅだい」。三拍目「ん」が「い」に変わる一拍差。"}, {"text": "主犯", "is_correct": false, "explanation": "「しゅはん」。二拍目「だ」が「は」に変わる一拍差。"}, {"text": "主観", "is_correct": false, "explanation": "「しゅかん」。二拍目「だ」が「か」に変わる一拍差。"}, {"text": "集団", "is_correct": false, "explanation": "「しゅうだん」。長音の有無の違い。"}], "explanations": {"手段": "正解。「しゅだん」。", "主題": "「しゅだい」。三拍目「ん」が「い」に変わる一拍差。", "主犯": "「しゅはん」。二拍目「だ」が「は」に変わる一拍差。", "主観": "「しゅかん」。二拍目「だ」が「か」に変わる一拍差。", "集団": "「しゅうだん」。長音の有無の違い。"}, "sentence_index": null, "correct_answer": "手段"}, "level_3": {"options": [{"text": "手段", "is_correct": true, "explanation": "正解。心の豊かさを求める方法。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は豊かさを追求する方法にならない。"}, {"text": "場所", "is_correct": false, "explanation": "意味：雑音を減らす行為は場所ではない。"}, {"text": "料金", "is_correct": false, "explanation": "意味：お金の語で文脈に合わない。"}], "explanations": {"手段": "正解。心の豊かさを求める方法。", "天気": "意味：天気は豊かさを追求する方法にならない。", "場所": "意味：雑音を減らす行為は場所ではない。", "料金": "意味：お金の語で文脈に合わない。"}, "sentence_index": 0, "correct_answer": "手段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "連絡の手段をメールだけだ。", "explanation": "助詞の誤り：主題は「は」で示す。"}, {"text": "連絡の手段にメールだけだ。", "explanation": "助詞の誤り：主題は「は」で示す。"}, {"text": "メールだけ連絡の手段はだ。", "explanation": "語順の誤り：主題—解説の構造が崩れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713bbf6-4bd1-4f74-b6e6-5187738b8141') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.gen